def docx_text(path):
    """Весь текст, включая поля формы (python-docx их иначе пропускает)."""
    doc = Document(path)
    lines = []
    for p in doc.element.body.iter(qn('w:p')):
        parts = []
        for node in p.iter():
            if node.tag == qn('w:t'):
                parts.append(node.text or '')
            elif node.tag == qn('w:tab'):
                parts.append('\t')
            elif node.tag in (qn('w:br'), qn('w:cr')):
                parts.append('\n')
        lines.append(''.join(parts))
    return '\n'.join(lines)


def form_value(raw):
    value = str(raw or '').strip()
    return '' if value.rstrip('.').strip().lower() in PLACEHOLDERS else value


def parse_date(raw):
    """ДД.ММ.ГГ или ДД.ММ.ГГГГ → ДД.ММ.ГГГГ."""
    m = re.search(r'(\d{1,2})\.(\d{1,2})\.(\d{4}|\d{2})', str(raw or ''))
    if not m:
        return ''
    d, mo, y = m.groups()
    if len(y) == 2:
        y = '20' + y
    return f'{int(d):02d}.{int(mo):02d}.{y}'


def parse_price(raw):
    s = re.sub(r'[^\d,.]', '', str(raw).replace('\xa0', ' ').replace(' ', ''))
    if not s:
        return None
    if ',' in s and '.' in s:
        k = max(s.rfind(','), s.rfind('.'))
        s = re.sub(r'[.,]', '', s[:k]) + '.' + re.sub(r'[.,]', '', s[k + 1:])
    else:
        s = s.replace(',', '.')
    try:
        return float(s)
    except ValueError:
        return None


def date_in_words(value):
    try:
        dt = datetime.strptime(value, '%d.%m.%Y')
    except (TypeError, ValueError):
        return value or ''
    return f'{dt.day} {MONTHS[dt.month - 1]} {dt.year}'


def short_responsible(full):
    """«Кузнецова Мария Александровна» → «Кузнецова М.А.»."""
    return fio_initials(full)


def field(text, label):
    """Значение строки шапки «Метка: значение»."""
    m = re.search(rf'^\s*{label}\s*:\s*(.*)$', text, re.IGNORECASE | re.MULTILINE)
    return form_value(m.group(1)) if m else ''


def after(text, pattern):
    m = re.search(pattern, text, re.IGNORECASE)
    return m.group(1).strip() if m else ''


def parse_notice(path):
    return parse_text(docx_text(path), path.name)


def parse_text(text, name=''):
    head = text[:1500]
    d = {'file': name}

    # --- шапка из шаблона
    d['noncompetitive'] = bool(re.search(r'Вид\s+закупки\s*:.*неконкурент', head, re.IGNORECASE))
    d['oao'] = re.sub(r'^номер\s*[):]?\s*', '', field(head, r'ОАО\s*\(?\s*(?:номер)?\s*\)?'),
                      flags=re.IGNORECASE).lstrip(':').strip()
    m = re.match(r'(\d+\s*[А-Яа-яЁё]+)\s*[,;]', d['oao'])
    if m:                                   # «ОАО: 1388зэк, КЦ №1727/к-26, НМЦК: …»
        d['oao'] = m.group(1).replace(' ', '')

    letter = field(head, r'(?:Категория\s+ТРУ\s*\(буква\)|Буква\s+предмета)')
    d['letter_raw'] = letter
    if re.match(r'то', letter, re.IGNORECASE):
        d['letter'] = 'ТО'
    else:
        m = re.match(r'[А-Яа-яA-Za-z]', letter)
        d['letter'] = m.group().upper() if m else ''

    d['one_c'] = field(head, '1С').lower() == 'да'

    sub = field(head, 'ПОДЧИНЕННОСТЬ')
    d['subordination'] = re.sub(r'[^А-Яа-яA-Za-z]', '', sub)[:10]
    # Номер КЦ пишут по-разному: «КЦ№ 2160», «КЦ 2160», «2160КЦ№».
    m = re.search(r'(?:КЦ|ВУЗ)\s*№?\s*(\d+)', sub, re.IGNORECASE) or \
        re.search(r'(\d+)\s*(?:КЦ|ВУЗ)', sub, re.IGNORECASE)
    d['kc_number'] = m.group(1) if m else ''

    d['subsidy'] = field(head, 'Субсидия')
    d['bid_start'] = parse_date(field(head, 'Вскрытие') or inline_field(head, 'Вскрытие'))
    d['review_date'] = parse_date(field(head, 'Рассмотрение') or inline_field(head, 'Рассмотрение'))
    d['trade_date'] = parse_date(field(head, 'Торги') or inline_field(head, 'Торги'))
    d['result_date'] = parse_date(field(head, 'Итоги') or inline_field(head, 'Итоги'))
    # «Email бухгалтерия» (раньше «Email основной») — два адреса бухгалтерии.
    d['email'] = ', '.join(re.findall(r'[\w.%+-]+@[\w.-]+\.\w+', field(head, 'Email (?:бухгалтерия|основной)')))
    d['email2'] = ', '.join(re.findall(r'[\w.%+-]+@[\w.-]+\.\w+', field(head, 'Email дополнительный')))

    # --- номер «387зцп»: из шапки или откуда угодно в тексте (старая шапка)
    zcp = re.search(r'(?<!\d)(\d+)\s*(зцп)', text, re.IGNORECASE)
    if not d['oao'] and zcp:
        d['oao'] = zcp.group(1) + zcp.group(2).lower()
    if 'зцп' in d['oao'].lower() or zcp:
        d['noncompetitive'] = True
    m = re.search(r'\d+\s*([А-Яа-яЁё]+)', d['oao'])
    d['abbr'] = m.group(1).upper() if m else 'ЗЦП'

    # --- тело извещения с площадки
    d['number'] = after(text, r'Номер (?:извещения|приглашения):\s*\[?([A-Z0-9]+)')
    d['name'] = re.sub(r'\s+', ' ', after(text, r'Наименование (?:процедуры|закупки):\s*(.+)')
                       or after(text, r'Предмет договора:\s*(.+)'))
    # Дата публикации: сначала «(в редакции № 1 от ДД.ММ.ГГГГ)» — дата самого извещения
    # (ГПБ, АСТ ГОЗ), потом «Дата публикации:» (Росэлторг).
    d['publish_date'] = parse_date(after(text, r'в редакции\s*№\s*\d+\s*от\s*(\d{1,2}\.\d{1,2}\.\d{2,4})')) or \
        parse_date(after(text, r'Дата публикации:\s*(\d{1,2}\.\d{1,2}\.\d{2,4})'))
    d['price'] = parse_price(after(text, r'Начальная (?:\(максимальная\) )?цена(?: договора)?:\s*([\d\s\xa0,.]+)')) or 0
    contact = after(text, r'(?:Ф\.И\.О\.?\s*(?:контактного\s+лица)?|Контактное лицо):\s*([^\n\t]+)')
    # Почты из текста площадки (без строк «Email основной/дополнительный» — это рассылка, не ответственный).
    # Сначала — почта рядом с контактным лицом (в тексте могут быть адреса инициаторов из проекта договора).
    lines = text.split('\n')
    mails_in = lambda ls: [m for line in ls if not re.match(r'\s*Email', line, re.IGNORECASE)
                           for m in re.findall(r'[\w.%+-]+@[\w.-]+\.\w+', line)]
    at = next((i for i, line in enumerate(lines)
               if re.search(r'Ф\.И\.О\.?\s*(?:контактного\s+лица)?\s*:|Контактное лицо\s*:', line)), None)
    body_mails = (mails_in(lines[at:at + 5]) if at is not None else []) or mails_in(lines)
    fio, mail, hint = resolve_responsible(contact, body_mails)
    d['responsible'] = fio
    d['responsible_email'] = mail
    d['responsible_hint'] = hint
    d['contact'] = contact
    url = re.search(r'https?://[^\s]*(?:roseltorg|astgoz|etpgpb)[^\s]*', text, re.IGNORECASE)
    d['site_url'] = url.group().rstrip('/') if url else ''

    if not d['bid_start']:
        d['bid_start'] = parse_date(after(
            text, r'окончания\s+(?:срока\s+)?подачи\s+заявок[^:\n]*:\s*(\d{1,2}\.\d{1,2}\.\d{2,4})'))
    if not d['result_date']:
        d['result_date'] = parse_date(after(
            text, r'подведения\s+итогов[^:\n]*:\s*(\d{1,2}\.\d{1,2}\.\d{2,4})'))

    d['smp'] = bool(re.search(
        r'только\s+субъекты\s+малого\s+и\s+среднего\s+предпринимательства\s*:\s*установлено',
        text, re.IGNORECASE)) or 'субъектов малого и среднего предпринимательства' in d['name'].lower()
    d['p2030'] = d['subsidy'] == '2030' or bool(re.search(r'приоритет[\s\-–]*2030', d['name'], re.IGNORECASE))

    # Шапка, написанная вручную: «1535зэа, кц 1839 / В-03.08 / П-05.08 …» или «ОАО: 1388зэк, КЦ №…».
    short = parse_short_header(head, d['publish_date'])
    if short:
        if not d['oao'] or not re.match(r'\d', d['oao']):
            d['oao'] = short.get('oao', d['oao'])
        for key, src in (('bid_start', 'bid'), ('review_date', 'review'), ('trade_date', 'trade'), ('result_date', 'result')):
            if not d[key] and short.get(src):
                d[key] = short[src]
        if not d['subordination'] and short.get('subordination'):
            d['subordination'] = short['subordination']
            d['kc_number'] = d['kc_number'] or short.get('kc_number', '')
        if short.get('one_c'):
            d['one_c'] = True
        if not d['subsidy'] and short.get('subsidy'):
            d['subsidy'] = short['subsidy']
            d['p2030'] = d['p2030'] or short['subsidy'] == '2030'
        m = re.search(r'\d+\s*([А-Яа-яЁё]+)', d['oao'])
        if m:
            d['abbr'] = m.group(1).upper()
        if 'зцп' in d['oao'].lower():
            d['noncompetitive'] = True
    if not d['review_date']:
        d['review_date'] = parse_date(after(text, r'Дата рассмотрения заявок[^:\n]*:\s*(\d{1,2}\.\d{1,2}\.\d{2,4})'))
    if not d['trade_date']:
        d['trade_date'] = parse_date(after(
            text, r'Дата (?:и время )?(?:проведения|начала) (?:аукциона|торгов|переторжки)[^:\n]*:\s*(\d{1,2}\.\d{1,2}\.\d{2,4})'))

    # Вид закупки: неконкурентная (зцп, метка шаблона) или конкурентная (зэа, зэк…).
    if (d['number'] or '').upper().startswith('COM'):
        d['noncompetitive'] = True   # коммерческая секция Росэлторга — неконкурентные
    d['kind'] = 'nk' if d['noncompetitive'] else ('k' if re.search(r'\d+\s*з[эе]', d['oao'], re.IGNORECASE) else '')
    if not d['kind']:
        # Шапки нет — смотрим на сам текст площадки.
        method = after(text, r'Способ проведения закупки:\s*([^\n]+)').lower()
        if re.search(r'аукцион|конкурс', method) or re.fullmatch(r'\d{11}', d['number'] or ''):
            d['kind'] = 'k'
        elif (d['number'] or '').upper().startswith('COM') or re.search(r'котировочн|запрос ценовых', text, re.IGNORECASE):
            d['kind'] = 'nk'
    if d['kind'] == 'k' and d['abbr'] == 'ЗЦП':
        d['abbr'] = 'ЗЭА'
    return d


def build_row(d):
    """Словарь «заголовок колонки → значение» для листа неконкурентных."""
    oao = d['oao'] + ('' if not d['oao'] or d['oao'].endswith('-оа') else '-оа')
    url = d['site_url'] or ('https://com.roseltorg.ru' if d.get('kind', 'nk') == 'nk' else '')
    publication = re.sub(r'\s+', ' ', f"{oao} {d['number']} {'(' + url + ')' if url else ''} "
                                      f"{date_in_words(d['publish_date'])}").strip()
    return {
        'абрев процедур': d['abbr'],
        'К,Л,М,ТО,Р': d['letter'],
        'субсидия': '' if d['subsidy'] == '2030' else d['subsidy'],
        'смп': 'смп' if d['smp'] else '',
        '2030': '2030' if d['p2030'] else '',
        '1С': '1С' if d['one_c'] else '',
        'НАИМЕНОВАНИЕ ТОВАРА/УСЛУГ/РАБОТ': d['name'],
        '№ КЦ/ВУЗ': d['kc_number'],
        'Подчин.': d['subordination'],
        'Ответственный за документацию': d.get('responsible_short') or short_responsible(d['responsible']),
        'Номер и Дата публикации': publication,
        'Дата вскрытия и время окончания подачи заявок по процедуре': date_in_words(d['bid_start']),
        'Дата рассмотрения и подведения итогов заявок и номер протокола': date_in_words(d['result_date']),
        'всего торгов': 1,
        'Начальная максимальня цена договора': d['price'],
    }


def site_name(url):
    u = (url or '').lower()
    if 'roseltorg' in u:
        return 'Росэлторг'
    if 'etpgpb' in u:
        return 'ЭТП ГПБ'
    if 'astgoz' in u:
        return 'АСТ ГОЗ'
    return ''


def build_row_competitive(d):
    """Строка для листа «Реестр 2026г.» — те же колонки и форматы, что пишет main.py."""
    oao = d['oao'] + ('' if not d['oao'] or d['oao'].endswith('-оа') else '-оа')
    url = d['site_url'] or ('https://com.roseltorg.ru' if d.get('kind', 'nk') == 'nk' else '')
    publication = re.sub(r'\s+', ' ', f"{oao} {d['number']} {'(' + url + ')' if url else ''} "
                                      f"{date_in_words(d['publish_date'])}").strip()
    return {
        'аббрев процедур': d['abbr'],
        'К,Л,М,ТО,Р': d['letter'],
        'субсидия,2030': d['subsidy'],
        '1С': '1С' if d['one_c'] else '',
        'Закон 223/44': 223,
        'НАИМЕНОВАНИЕ ТОВАРА/УСЛУГ/РАБОТ': d['name'],
        'н.КЦ/ВУЗ': d['kc_number'],
        'Подчин.': d['subordination'],
        'Ответственный за документацию': d.get('responsible_short') or fio_initials(d['responsible']),
        'Наименование торговой площадки': site_name(d['site_url']),
        'Номер и Дата публикации': publication,
        'Дата вскрытия и номер протокола/ дата и время окончания подачи заявок по процедуре': d['bid_start'],
        'Дата рассмотрения заявок и номер протокола': d.get('review_date', ''),
        'Дата подведения итогов и номер протокола/протокол аукциона (торги, аукцион)': d.get('trade_date', ''),
        'Дата подведения итогов ': d['result_date'],
        'всего торгов': 1,
        'Начальная максимальня цена договора': d['price'],
        'Аукцион/конкурс сотоялся ': 0,
    }


