def norm(title):
    return re.sub(r'\s+', ' ', str(title)).strip().lower()


def safe(value):
    """Текст из документа не должен превратиться в формулу Excel."""
    if isinstance(value, str) and value[:1] in ('=', '+', '-', '@'):
        return "'" + value
    return value


