THIN = Side(style='thin')
BORDER = Border(left=THIN, right=THIN, top=THIN, bottom=THIN)
CENTER = Alignment(horizontal='center', vertical='center', wrap_text=True)


def add_sheet(wb):
    """Лист «неконкурентные закупки» с заголовком и шапкой."""
    ws = wb.create_sheet(SHEET_NAME)
    ws['A1'] = 'Реестр 2026г. (НЕКОНКУРЕНТНЫЕ ЗАКУПКИ)'
    ws['A1'].font = Font(name='Times New Roman', size=48, bold=True)
    ws['A1'].alignment = CENTER
    ws.merge_cells('A1:V2')
    ws.row_dimensions[1].height = 76.5
    ws.row_dimensions[2].height = 45
    ws.row_dimensions[3].height = 156.75

    fill = PatternFill('solid', fgColor='92CDDC')
    for col, title in enumerate(HEADERS, 1):
        c = ws.cell(3, col, title)
        c.font = Font(name='Times New Roman', size=16 if title == 2030 else 10, bold=True)
        c.fill = fill
        c.border = BORDER
        c.alignment = Alignment(horizontal='center', vertical='center', wrap_text=True,
                                text_rotation=90 if title == 2030 else 0)
    for col in range(1, len(HEADERS) + 1):
        letter = ws.cell(3, col).column_letter
        ws.column_dimensions[letter].width = WIDTHS.get(letter, 13)
    ws.freeze_panes = 'A4'
    ws.auto_filter.ref = f'A3:{ws.cell(3, len(HEADERS)).column_letter}3'
    return ws


