def sheet_for(wb, kind):
    """Лист для вида закупки; если его нет — создаётся."""
    for name in wb.sheetnames:
        low = name.lower()
        if kind == 'nk' and 'неконкурент' in low:
            return wb[name]
        if kind == 'k' and 'реестр' in low and 'неконкурент' not in low:
            return wb[name]
    return add_sheet(wb) if kind == 'nk' else add_comp_sheet(wb)


def create_registry(path, year=None):
    """Новый реестр года. Есть реестр другого года — берём его шапку и оформление
    (без строк, первая строка остаётся пустой с оформлением — по ней оформятся новые)."""
    path = Path(path)
    path.parent.mkdir(parents=True, exist_ok=True)
    year = year or (year_of_path(path).y if year_of_path(path) else date.today().year)
    others = sorted((Y for Y in years() if Y.registry != path and Y.registry.exists()),
                    key=lambda Y: (abs(Y.y - year), -Y.y))
    if others:
        src = others[0]
        wb = load_workbook(src.registry)
        for ws in wb.worksheets:
            top = header_row(ws)
            if ws.max_row > top + 1:
                ws.delete_rows(top + 2, ws.max_row - top - 1)
            for c in range(1, ws.max_column + 1):
                ws.cell(top + 1, c).value = None
            for r in range(1, top):
                for c in range(1, ws.max_column + 1):
                    v = ws.cell(r, c).value
                    if isinstance(v, str) and str(src.y) in v:
                        ws.cell(r, c).value = v.replace(str(src.y), str(year))
            if str(src.y) in ws.title:
                ws.title = ws.title.replace(str(src.y), str(year))
        wb.save(path)
        return
    wb = Workbook()
    wb.remove(wb.active)
    add_comp_sheet(wb)
    add_sheet(wb)
    wb.save(path)


def default_style(ws, row):
    """Оформление строки, когда на листе ещё нет строки-образца."""
    for c in range(1, len(HEADERS) + 1):
        cell = ws.cell(row, c)
        cell.font = Font(name='Arial', size=10)
        cell.border = BORDER
        cell.alignment = CENTER
    for c in (19, 20, 21, 23, 24):
        ws.cell(row, c).number_format = '#,##0.00'


def header_row(ws):
    for r in range(1, 13):
        line = ' '.join(str(ws.cell(r, c).value or '').lower() for c in range(1, ws.max_column + 1))
        if 'наименование' in line:
            return r
    return 1


def last_row(ws, top):
    for r in range(ws.max_row, top, -1):
        if any(ws.cell(r, c).value not in (None, '') for c in range(1, ws.max_column + 1)):
            return r
    return top


def copy_style(ws, src, dst):
    for c in range(1, ws.max_column + 1):
        ws.cell(dst, c)._style = copy(ws.cell(src, c)._style)
    # Высоту берём только разумную: строка-образец бывает растянута на пол-экрана.
    height = ws.row_dimensions[src].height if src in ws.row_dimensions else None
    ws.row_dimensions[dst].height = height if height and height <= 80 else None


class RegistryBusy(Exception):
    """Реестр открыт в Excel — запись отложена до следующей проверки."""


class Year:
    """Год реестра: файл и папки приёма."""
    def __init__(self, y, cfg):
        self.y = int(y)
        self.registry = Path(cfg['реестр'])
        self.folder = Path(cfg['папка'])
        self.intake = cfg.get('приём', True)

    def notices_in(self, kind):
        return self.folder / 'Извещения' / ('Конкурентные' if kind == 'k' else 'Неконкурентные') / 'входящие'

    def notices_done(self, kind):
        return self.notices_in(kind).parent / 'отработанные'

    def protocols_in(self):
        return self.folder / 'Протоколы' / 'входящие'

    def protocols_done(self):
        return self.folder / 'Протоколы' / 'отработанные'

    def contracts_dir(self):
        return self.folder / 'Договоры'

    def intake_dirs(self):
        return [(k, self.notices_in(k)) for k in ('k', 'nk')]

    def __repr__(self):
        return f'<Год {self.y}>'


def years():
    return [Year(y, c) for y, c in sorted(ГОДЫ.items())]


def year_obj(y=None):
    """Год по номеру; без номера — текущий (или последний настроенный)."""
    ys = {x.y: x for x in years()}
    if y is not None and int(y) in ys:
        return ys[int(y)]
    cur = ТЕКУЩИЙ_ГОД or date.today().year
    if cur in ys:
        return ys[cur]
    return ys[max(k for k in ys if k <= cur)] if any(k <= cur for k in ys) else ys[min(ys)]


def year_of_path(path):
    path = Path(path)
    for Y in years():
        if Y.registry == path:
            return Y
    return None


def save_workbook(wb, path):
    """Сохраняет через временный файл и заменяет оригинал одним действием:
    при сбое реестр не остаётся полузаписанным. Перед этим — резервная копия."""
    path = Path(path)
    backups = path.parent / 'Резервные копии'
    backups.mkdir(exist_ok=True)
    if path.exists():
        shutil.copy2(path, backups / f'{path.stem}_{datetime.now():%Y%m%d_%H%M%S}.xlsx')
    for old in sorted(backups.glob(f'{path.stem}_*.xlsx'))[:-30]:
        old.unlink(missing_ok=True)

    temp = path.with_name(f'~tmp_{path.name}')
    wb.save(temp)
    for attempt in range(3):
        try:
            os.replace(temp, path)
            return
        except PermissionError:
            time.sleep(1)
    temp.unlink(missing_ok=True)
    raise RegistryBusy('Реестр открыт в Excel — запись отложена. Закройте файл, извещения внесутся автоматически.')


