# ============================================================

USER = getpass.getuser()
HOST = socket.gethostname()


def journal_path():
    return ПАПКА_ПАНЕЛИ / ЖУРНАЛ


def load_journal():
    try:
        return json.loads(journal_path().read_text(encoding='utf-8'))
    except (OSError, ValueError):
        return []


def log(kind, text, **extra):
    """kind: added / duplicate / skipped / error / info."""
    icon = {'added': '✅', 'duplicate': '⚠️', 'skipped': '⏭', 'error': '❌', 'info': 'ℹ️'}.get(kind, '•')
    print(f'[{datetime.now():%H:%M:%S}] {icon} {text}' + (f'  ({extra["file"]})' if extra.get('file') else ''))
    entry = {'ts': datetime.now().isoformat(timespec='seconds'), 'kind': kind, 'text': text,
             'user': USER, **extra}
    items = load_journal()[-299:] + [entry]
    write_atomic(journal_path(), json.dumps(items, ensure_ascii=False, indent=1))


def write_atomic(path, text):
    path.parent.mkdir(parents=True, exist_ok=True)
    temp = path.with_name(path.name + '.tmp')
    temp.write_text(text, encoding='utf-8')
    for attempt in range(5):
        try:
            os.replace(temp, path)
            return True
        except PermissionError:
            time.sleep(0.3)
    return False


# ============================================================
# ЧТЕНИЕ ДОКУМЕНТОВ: .docx, .doc (Word 97–2003), .pdf
# ============================================================

def _cfb_streams(data):
    """Минимальный разбор контейнера OLE (формат старых .doc). Возвращает {имя: байты}."""
    import struct
    if data[:8] != b'\xd0\xcf\x11\xe0\xa1\xb1\x1a\xe1':
        raise ValueError('это не файл Word 97–2003')
    sec_size = 1 << struct.unpack_from('<H', data, 0x1E)[0]
    mini_size = 1 << struct.unpack_from('<H', data, 0x20)[0]
    n_fat, first_dir = struct.unpack_from('<II', data, 0x2C)
    cutoff, first_minifat, n_minifat, first_difat, n_difat = struct.unpack_from('<IIIII', data, 0x38)

    def sector(i):
        off = (i + 1) * sec_size
        return data[off:off + sec_size]

    difat = list(struct.unpack_from('<109I', data, 0x4C))
    d = first_difat
    for _ in range(n_difat):
        if d >= 0xFFFFFFFA:
            break
        vals = struct.unpack('<%dI' % (sec_size // 4), sector(d))
        difat += vals[:-1]
        d = vals[-1]
    fat = []
    for s in difat[:n_fat]:
        if s < 0xFFFFFFFA:
            fat += struct.unpack('<%dI' % (sec_size // 4), sector(s))

    def chain(start, table):
        out, s, guard = [], start, 0
        while s < 0xFFFFFFFA and guard < 1_000_000:
            out.append(s)
            s = table[s] if s < len(table) else 0xFFFFFFFE
            guard += 1
        return out

    def read_big(start, size):
        return b''.join(sector(s) for s in chain(start, fat))[:size]

    dir_data = b''.join(sector(s) for s in chain(first_dir, fat))
    entries = []
    for i in range(0, len(dir_data), 128):
        e = dir_data[i:i + 128]
        if len(e) < 128:
            break
        name_len = struct.unpack_from('<H', e, 64)[0]
        name = e[:max(0, name_len - 2)].decode('utf-16le', 'ignore')
        etype = e[66]
        start, size = struct.unpack_from('<II', e, 0x74)
        entries.append((name, etype, start, size))
    root = next((x for x in entries if x[1] == 5), None)
    ministream = read_big(root[2], root[3]) if root else b''
    minifat = []
    if n_minifat and first_minifat < 0xFFFFFFFA:
        raw = b''.join(sector(s) for s in chain(first_minifat, fat))
        minifat = list(struct.unpack('<%dI' % (len(raw) // 4), raw))

    streams = {}
    for name, etype, start, size in entries:
        if etype != 2:
            continue
        if size < cutoff:
            streams[name] = b''.join(ministream[s * mini_size:(s + 1) * mini_size]
                                     for s in chain(start, minifat))[:size]
        else:
            streams[name] = read_big(start, size)
    return streams


def doc_text(data):
    """Текст старого .doc (Word 97–2003) без Word и LibreOffice — по таблице фрагментов."""
    import struct
    st = _cfb_streams(data)
    wd = st.get('WordDocument')
    if not wd:
        raise ValueError('в файле нет текста Word')
    flags = struct.unpack_from('<H', wd, 0x0A)[0]
    table = st.get('1Table' if flags & 0x0200 else '0Table', b'')
    fc_clx, lcb_clx = struct.unpack_from('<II', wd, 0x01A2)
    clx = table[fc_clx:fc_clx + lcb_clx]
    pos, pieces = 0, None
    while pos < len(clx):
        if clx[pos] == 0x01:
            pos += 3 + struct.unpack_from('<h', clx, pos + 1)[0]
        elif clx[pos] == 0x02:
            lcb = struct.unpack_from('<I', clx, pos + 1)[0]
            plc = clx[pos + 5:pos + 5 + lcb]
            n = (lcb - 4) // 12
            cps = struct.unpack_from('<%dI' % (n + 1), plc, 0)
            pieces = []
            for i in range(n):
                fc = struct.unpack_from('<I', plc, 4 * (n + 1) + 8 * i + 2)[0]
                pieces.append((cps[i], cps[i + 1], fc))
            break
        else:
            break
    if not pieces:
        raise ValueError('не удалось найти текст в .doc')
    parts = []
    for cp0, cp1, fc in pieces:
        count = cp1 - cp0
        if fc & 0x40000000:
            off = (fc & 0x3FFFFFFF) // 2
            parts.append(wd[off:off + count].decode('cp1251', 'replace'))
        else:
            parts.append(wd[fc:fc + 2 * count].decode('utf-16le', 'replace'))
    text = ''.join(parts)
    # Коды полей: \x13 код \x14 результат \x15 — оставляем только результат.
    text = re.sub(r'\x13[^\x13\x14\x15]*\x14', '', text)
    text = re.sub(r'\x13[^\x13\x14\x15]*\x15', '', text)
    text = text.replace('\x15', '')
    text = text.replace('\r', '\n').replace('\x07', '\n').replace('\x0b', '\n').replace('\x0c', '\n')
    text = re.sub(r'[\x00-\x08\x0e-\x1f]', '', text)
    return text


def pdf_text(data):
    try:
        from pypdf import PdfReader
    except ImportError:
        raise ValueError('для PDF нужна библиотека pypdf: pip install pypdf')
    reader = PdfReader(io.BytesIO(data))
    text = '\n'.join(page.extract_text() or '' for page in reader.pages)
    if len(text.strip()) < 50:
        raise ValueError('в PDF нет текстового слоя (скан) — нужен PDF с текстом или Word')
    return re.sub(r'[ \t]{2,}', ' ', text)


def any_text(data, filename):
    """Текст документа любого из поддерживаемых форматов."""
    name = (filename or '').lower()
    if data[:4] == b'PK\x03\x04' or name.endswith('.docx'):
        return docx_text(io.BytesIO(data))
    if data[:8] == b'\xd0\xcf\x11\xe0\xa1\xb1\x1a\xe1' or name.endswith('.doc'):
        return doc_text(data)
    if data[:4] == b'%PDF' or name.endswith('.pdf'):
        return pdf_text(data)
    raise ValueError('поддерживаются .docx, .doc и .pdf')

# ============================================================
# РАСПОЗНАВАНИЕ: КРАТКИЕ ШАПКИ, ПРОТОКОЛЫ, ДОГОВОРЫ
# ============================================================

MONTH_NUM = {m: i + 1 for i, m in enumerate(MONTHS)}
NBSP = ' '


def money_from(s):
    """Сумма из текста: «1 234 567 рублей 00 копеек», «1234567,00 руб.», «1 234 567 (один миллион…) рублей 89 копеек»."""
    if not s:
        return None
    s = str(s).replace(NBSP, ' ').replace(' ', ' ')
    m = re.search(r'(\d[\d ]*)\s*(?:\([^)]*\)\s*)?руб\w*\.?\s*(?:(\d{1,2})\s*коп)?', s, re.DOTALL)
    if m:
        rub = int(re.sub(r'\D', '', m.group(1)))
        kop = int(m.group(2)) if m.group(2) else 0
        return round(rub + kop / 100, 2)
    m = re.search(r'\d[\d ]*[.,]\d{2}(?!\d)|\d[\d ]*\d', s)
    return parse_price(m.group()) if m else None


def quoted_date(s):
    """«05» августа 2026 → 05.08.2026."""
    m = re.search(r'«\s*(\d{1,2})\s*»\s*([а-яё]+)\s*(\d{4})', s or '', re.IGNORECASE)
    if not m:
        return ''
    mo = MONTH_NUM.get(m.group(2).lower())
    return f'{int(m.group(1)):02d}.{mo:02d}.{m.group(3)}' if mo else ''


def words_padded(ru):
    """05.08.2026 → «05 августа 2026» (как в ссылках на протоколы в реестре)."""
    try:
        dt = datetime.strptime(ru, '%d.%m.%Y')
    except (TypeError, ValueError):
        return ru or ''
    return f'{dt.day:02d} {MONTHS[dt.month - 1]} {dt.year}'


def norm_oao(s):
    """«1388-зэк» / «1388 зэк» → «1388зэк»."""
    m = re.search(r'(\d+)\s*-?\s*([а-яёА-ЯЁ]+)', s or '')
    return (m.group(1) + m.group(2).lower()) if m else (s or '').strip()


# ---------- краткие шапки извещений ----------

SHORT_LETTERS = {'в': 'bid', 'р': 'review', 'а': 'trade', 'т': 'trade', 'и': 'result'}


def parse_short_header(head, publish_date=''):
    """Шапки, которые пишут вручную:
         «1535зэа, кц 1839» / «В-03.08» / «П-05.08» / «А-06.08» / «П-07.08»
         «415р, вуз 1с 2030» / «В-10.08» / «А-11.08» / «П-12.08»
         «ОАО: 1388зэк, КЦ №1727/к-26, НМЦК: …» / «Вскрытие: 24.07.26; Рассмотрение: 28.07.26; Итоги: 29.07.26.»
    """
    out = {}
    lines = [l.strip() for l in head.split('\n') if l.strip()][:12]
    first = None
    for l in lines[:3]:
        m = re.match(r'(?:ОАО\s*(?:\(номер\))?\s*:\s*)?(\d{1,5})\s*-?\s*(зцп|зэа|зэк|зк|р|зп|еп|[а-яё]{1,4})\b(.*)$', l, re.IGNORECASE)
        if m:
            first = m
            break
    if first:
        out['oao'] = first.group(1) + first.group(2).lower()
        rest = first.group(3)
        low = rest.lower()
        sub = re.search(r'\b(вуз|кц)\b\s*№?\s*(\d+(?:/[^\s,;]+)?)?(\s*[сc]\b)?', low)
        if sub:
            out['subordination'] = sub.group(1).upper()
            if sub.group(2) and not sub.group(3):     # «вуз 1с» — это отметка 1С, не номер
                out['kc_number'] = sub.group(2)
        if re.search(r'\b1\s*[сc]\b', low):
            out['one_c'] = True
        if re.search(r'\b2030\b', low):
            out['subsidy'] = '2030'

    # Даты буквами: В-03.08, П-05.08, А-06.08, П-07.08
    seq = []
    for l in lines:
        m = re.match(r'([ВПАРТИвпартиВ])\s*[-–—:]\s*(\d{1,2})\.(\d{1,2})(?:\.(\d{2,4}))?\s*$', l)
        if m:
            seq.append((m.group(1).lower(), m.group(2), m.group(3), m.group(4)))
    if seq:
        try:
            base = datetime.strptime(publish_date, '%d.%m.%Y') if publish_date else datetime.now()
        except ValueError:
            base = datetime.now()

        def mk(d, mo, y):
            if y:
                y = int(y) + (2000 if len(y) == 2 else 0)
            else:
                y = base.year
                if date(y, int(mo), int(d)) < base.date() - timedelta(days=31):
                    y += 1
            return f'{int(d):02d}.{int(mo):02d}.{y}'

        ps = [x for x in seq if x[0] == 'п']
        for i, (ch, d, mo, y) in enumerate(seq):
            if ch in SHORT_LETTERS:
                out.setdefault(SHORT_LETTERS[ch], mk(d, mo, y))
            elif ch == 'п':
                # Последнее «П» — подведение итогов; если «П» несколько, первое — рассмотрение.
                if len(ps) >= 2 and (ch, d, mo, y) == ps[0]:
                    out.setdefault('review', mk(d, mo, y))
                else:
                    out['result'] = mk(d, mo, y)
    return out


def inline_field(text, label):
    """«Метка: значение» в начале строки или после «;» / «,» (шапка в одну строку)."""
    m = re.search(rf'(?:^|[;,]\s*){label}\s*:\s*([^;\n]*)', text, re.IGNORECASE | re.MULTILINE)
    return form_value(m.group(1)) if m else ''


# ---------- протоколы ----------

PROTO_TYPES = {
    'open': 'вскрытия заявок',
    'review': 'рассмотрения заявок',
    'review_result': 'рассмотрения заявок и подведения итогов',
    'result': 'подведения итогов',
}


def _participant_rows(lines):
    """Строки таблицы заявок: номер п/п → участник, дата, наименование, ИНН, решение."""
    rows, cur = [], None
    start = next((i for i, l in enumerate(lines) if re.search(r'Решение о допуске', l)), None)
    if start is None:
        start = next((i for i, l in enumerate(lines)
                      if re.search(r'Идентификационный номер участника|Номер, дата и время регистрации', l)), None)
    if start is None:
        return rows
    i = start + 1
    while i < len(lines):
        l = lines[i]
        # Конец таблицы: следующий пункт протокола («5. Признать…», «6.На основании…»).
        if re.match(r'^\d{1,2}\.\s*[А-ЯЁA-Z]', l) or re.match(r'^(Настоящий|Все минимальные|На участие в аукционе|Комиссией была)', l):
            break
        if re.match(r'^(Основание|Наименование|Номер, дата|Идентификационный|№\s*п/п)', l):
            i += 1
            continue
        if re.fullmatch(r'\d{1,3}', l.strip()):
            cur = {'n': int(l.strip()), 'lines': []}
            rows.append(cur)
        elif cur is not None:
            cur['lines'].append(l)
        i += 1
    result = []
    for r in rows:
        p = {'id': '', 'date': '', 'name': '', 'inn': '', 'kpp': '', 'decision': '', 'reason': '', 'price': None, 'smp': ''}
        texts = []
        for l in r['lines']:
            s = l.strip()
            m = re.search(r'Участник\s*№\s*(\d+)', s)
            if m:
                p['id'] = m.group(1)
            d = re.search(r'(\d{2}\.\d{2}\.\d{4})\s*(\d{1,2}:\d{2})', s)
            if d and not p['date']:
                p['date'] = f'{d.group(1)} {d.group(2)}'
            if re.fullmatch(r'\d{4,6}', s) and not p['id']:
                p['id'] = s
                continue
            dec = re.match(r'^(Допущена|Допущен|Отклонена|Отклонен|Не допущена|Не допущен)\b', s, re.IGNORECASE)
            if dec:
                p['decision'] = 'Отклонена' if re.match(r'(отклон|не допущ)', s, re.IGNORECASE) else 'Допущена'
                continue
            if p['decision'] and not p['reason'] and s not in ('-', '—'):
                p['reason'] = s
                continue
            if m or d or re.fullmatch(r'[\d.:\s]+', s) or s in ('-', '—') or s.startswith('от'):
                continue
            texts.append(s)
        if texts:
            name = texts[0]
            ik = re.search(r'\(\s*(\d{10,12})\s*(?:/\s*(\d{9}))?\s*\)', name)
            if ik:
                p['inn'], p['kpp'] = ik.group(1), ik.group(2) or ''
                name = name[:ik.start()].strip()
            p['name'] = name
        if p['id'] or p['name']:
            result.append(p)
    return result


def _bid_prices(lines):
    """Предложения о цене: «Участник № 12345 … 1 234 567,00» → {id: цена}."""
    prices = {}
    if not any(re.search(r'предложени\w* о цене|Предложение участника|Ценовое предложение', l, re.IGNORECASE) for l in lines):
        return prices
    start = 0
    # «Номер заявки» / «№ 12345» на соседних строках — склеиваем.
    lines = [('заявки ' + l) if re.fullmatch(r'№\s*\d+', l.strip()) else l for l in lines]
    money_re = re.compile(r'^\d[\d  ]*[.,]\d{2}$')
    # В конкурсе рядом с ценой стоят баллы («1,74») — там берём только «Ценовое предложение: …».
    scored = any('Ценовое предложение' in l for l in lines)
    for i in range(start, len(lines)):
        m = re.search(r'(?:Участник|заявки)\s*№\s*(\d+)', lines[i])
        if not m:
            continue
        for j in range(i + 1, min(i + 25, len(lines))):
            s = lines[j].strip().replace(NBSP, ' ')
            if re.search(r'(?:Участник|заявки)\s*№', s):
                break
            if money_re.match(s) and not scored:
                prices.setdefault(m.group(1), parse_price(s))
                break
            cp = re.search(r'Ценовое предложение:\s*([\d\s.,]+)\s*руб', s)
            if cp:
                prices.setdefault(m.group(1), parse_price(cp.group(1)))
                break
    return prices


def parse_protocol(text):
    t = text.replace(NBSP, ' ')
    lines = [l.strip() for l in t.split('\n') if l.strip()]
    p = {'doc': 'protocol'}
    m = re.search(r'№\s*(COM\d+|\d{11})\s*/\s*(\d+)\s*\(\s*([^)]+?)\s*\)', t)
    if m:
        p['number'], p['seq'], p['oao'] = m.group(1), int(m.group(2)), norm_oao(m.group(3))
    p['date'] = quoted_date(t[(m.end() if m else 0):(m.end() + 400) if m else 3000])
    title = ' '.join(lines[:12]).lower()
    if 'вскрыти' in title:
        p['type'] = 'open'
    elif 'рассмотрени' in title and 'подведени' in title:
        p['type'] = 'review_result'
    elif 'подведени' in title:
        p['type'] = 'result'
    elif 'рассмотрени' in title:
        p['type'] = 'review'
    else:
        p['type'] = ''
    low = t.lower()
    p['form'] = ('конкурс' if 'конкурс' in title else 'аукцион' if 'аукцион' in title
                 else 'редукцион' if 'редукцион' in title else 'запрос ценовых предложений' if 'запрос' in title else '')
    nm = re.search(r'Начальная\s*\(максимальная\)\s*цена договора:\s*(.{0,80})', t, re.DOTALL)
    p['nmck'] = money_from(nm.group(1)) if nm else None
    apps = re.search(r'(?:были|была|было)\s+подан\w*\s+(\d+)\s+заяв', t, re.IGNORECASE)
    if apps:
        p['apps'] = int(apps.group(1))
    elif re.search(r'не\s+(?:было\s+)?подано\s+ни\s+одной|не\s+поступило\s+ни\s+одной', low):
        p['apps'] = 0
    p['participants'] = _participant_rows(lines)
    prices = _bid_prices(lines)
    for x in p['participants']:
        if x['id'] in prices:
            x['price'] = prices[x['id']]
    p['bidders'] = len(prices) if p['type'] in ('result',) and 'аукцион' in p['form'] else 0
    p['admitted'] = sum(1 for x in p['participants'] if x['decision'] == 'Допущена')
    p['rejected'] = sum(1 for x in p['participants'] if x['decision'] == 'Отклонена')
    if 'apps' not in p and p['participants']:
        p['apps'] = len(p['participants'])
    p['failed'] = bool(re.search(r'несостоявш', low))

    # Победитель
    w = re.search(r'передать проект договора участнику\s*(?:\(([^)]*)\))?\s*(.+?)\s*(?:ИНН\s*)?(\d{12}|\d{10})\b'
                  r'(?:\s*\(Участник\s*№\s*(\d+)\))?\s*на сумму\s*([^.\n]+)', t, re.IGNORECASE | re.DOTALL)
    if w:
        p['winner'] = {'smp': (w.group(1) or '').strip(), 'name': re.sub(r'\s+', ' ', w.group(2)).strip(' ,'),
                       'inn': w.group(3), 'id': w.group(4) or '', 'price': money_from(w.group(5))}
    else:
        w = re.search(r'с которым планируется заключить договор:\s*(?:\(([^)]*)\),?)?\s*ИНН\s*(\d{10,12}),?\s*(.+?)\s+по цене\s*([\d\s.,]+)',
                      t, re.IGNORECASE | re.DOTALL)
        if w:
            p['winner'] = {'smp': (w.group(1) or '').strip(), 'name': re.sub(r'\s+', ' ', w.group(3)).strip(' ,'),
                           'inn': w.group(2), 'id': '', 'price': parse_price(w.group(4))}
    if p.get('winner') and not p['winner']['id']:
        first = re.search(r'заявке на участие в закупке\s*№\s*(\d+)\s*присвоен первый номер', t)
        if first:
            p['winner']['id'] = first.group(1)
    if p.get('winner'):
        smp = p['winner']['smp'].lower()
        p['winner']['smp'] = ('микро' if 'микро' in smp else 'малое' if 'мал' in smp else 'среднее' if 'сред' in smp
                              else 'СОНКО' if 'сонко' in smp or 'некоммерч' in smp else '')
        if p['winner']['price'] is None:
            win = next((x for x in p['participants'] if x['id'] == p['winner']['id']), None)
            p['winner']['price'] = win and win['price']
    ex = re.search(r'Исп\.*\s*:?\s*([А-ЯЁ][а-яё]+\s+[А-ЯЁ]\.\s*[А-ЯЁ]\.)', t)
    p['executor'] = ex.group(1) if ex else ''
    return p


# ---------- договоры ----------

OUR_INN = '7704047505'


def parse_contract(text):
    t = text.replace(NBSP, ' ')
    c = {'doc': 'contract'}
    m = re.search(r'ДОГОВОР\s*№\s*([A-ZА-Я]*\d[\w/\-]*)', t)
    c['contract_no'] = m.group(1) if m else ''
    m = re.search(r'протокола\s+заседания\s+комиссии\s*№\s*(COM\d+|\d{11})\s*/\s*(\d+)\s*\(\s*([^)]+?)\s*\)\s*от\s*(«[^»]+»\s*[а-яё]+\s*\d{4})',
                  t, re.IGNORECASE | re.DOTALL)
    if m:
        c['number'], c['protocol_seq'], c['oao'] = m.group(1), int(m.group(2)), norm_oao(m.group(3))
        c['protocol_date'] = quoted_date(m.group(4))
    else:
        c['number'] = c['contract_no'] if re.fullmatch(r'COM\d+|\d{11}', c['contract_no']) else ''
    # Дата в шапке договора «город Москва «15» сентября 2026». «___» — не проставлена.
    dm = re.search(r'город\s+Москва\s*(«[^»]*»\s*[а-яё_]*\s*\d{0,4})', t[:800], re.IGNORECASE)
    c['date'] = quoted_date(dm.group(1)) if dm else ''
    pm = re.search(r'Цена\s+Договора[^.]{0,200}?составляет\s*(.{0,260})', t, re.IGNORECASE | re.DOTALL) or \
        re.search(r'составляет\s*(\d.{0,260})', t, re.DOTALL)
    c['price'] = money_from(pm.group(1)) if pm else None
    sm = re.search(r'с\s+одной\s+стороны,\s*(?:и\s+)?(.+?),?\s*именуем\w*\s+в\s+дальнейшем\s*«Поставщик»', t, re.IGNORECASE | re.DOTALL)
    if sm:
        name = re.sub(r'\s+', ' ', sm.group(1))
        name = re.sub(r'\s*\(ОГРН\w*[^)]*\)', '', name).strip(' ,')
        c['supplier'] = name
    inns = [x for x in re.findall(r'ИНН:?\s*(\d{12}|\d{10})\b', t) if x != OUR_INN]
    c['inn'] = inns[0] if inns else ''
    return c


def detect_doc(text):
    """Что за документ: извещение, протокол или договор."""
    top = text[:1500].lower()
    if re.search(r'^\s*договор\s*№', text[:300], re.IGNORECASE | re.MULTILINE):
        return 'contract'
    if re.search(r'^\s*протокол\s*$', text[:1500], re.IGNORECASE | re.MULTILINE) or 'заседания комиссии' in top:
        return 'protocol'
    return 'notice'

