def plural_ru(n, one, few, many):
    n = abs(int(n)) % 100
    if 11 <= n <= 14:
        return many
    n %= 10
    return one if n == 1 else few if 2 <= n <= 4 else many


def money_words(v):
    """1234567.0 → «1 234 567 рублей 00 копеек»."""
    v = round(float(v or 0), 2)
    rub, kop = int(v), int(round((v - int(v)) * 100))
    return (f"{rub:,}".replace(',', ' ') + ' ' + plural_ru(rub, 'рубль', 'рубля', 'рублей') +
            f" {kop:02d} " + plural_ru(kop, 'копейка', 'копейки', 'копеек'))


def date_quoted(ru):
    try:
        dt = datetime.strptime(ru, '%d.%m.%Y')
    except (TypeError, ValueError):
        return '«__» ________ 20__'
    return f'«{dt.day:02d}» {MONTHS[dt.month - 1]} {dt.year}'


def _font(run, size=12, bold=False, italic=False, mark=False):
    run.font.name = 'Times New Roman'
    run._element.rPr.rFonts.set(qn('w:eastAsia'), 'Times New Roman')
    run.font.size = Pt(size)
    run.bold = bold
    run.italic = italic
    if mark:
        run.font.highlight_color = WD_COLOR_INDEX.YELLOW


class _Doc:
    def __init__(self):
        self.doc = Document()
        sec = self.doc.sections[0]
        sec.page_height, sec.page_width = Cm(29.7), Cm(21)
        sec.left_margin, sec.right_margin = Cm(2.5), Cm(1.5)
        sec.top_margin = sec.bottom_margin = Cm(1.5)

    def p(self, text='', bold=False, center=False, size=12, mark=False, space=4, indent=False, italic=False):
        par = self.doc.add_paragraph()
        par.paragraph_format.space_after = Pt(space)
        par.paragraph_format.space_before = Pt(0)
        if center:
            par.alignment = WD_ALIGN_PARAGRAPH.CENTER
        else:
            par.alignment = WD_ALIGN_PARAGRAPH.JUSTIFY
        if indent:
            par.paragraph_format.first_line_indent = Cm(1)
        if text:
            _font(par.add_run(text), size, bold, italic, mark)
        return par

    def runs(self, parts, indent=True):
        """parts — список (текст, жирный, выделить)."""
        par = self.p(indent=indent)
        for text, bold, mark in parts:
            _font(par.add_run(text), 12, bold, False, mark)
        return par

    def table(self, head, rows, widths=None):
        t = self.doc.add_table(rows=1, cols=len(head))
        t.style = 'Table Grid'
        for i, h in enumerate(head):
            c = t.rows[0].cells[i]
            c.text = ''
            _font(c.paragraphs[0].add_run(h), 10, True)
            c.paragraphs[0].alignment = WD_ALIGN_PARAGRAPH.CENTER
        for row in rows:
            cells = t.add_row().cells
            for i, v in enumerate(row):
                cells[i].text = ''
                _font(cells[i].paragraphs[0].add_run(str(v if v not in (None,) else '')), 10)
        if widths:
            t.autofit = False
            for i, w in enumerate(widths):
                t.columns[i].width = Cm(w)
            for row in t.rows:
                for i, w in enumerate(widths):
                    row.cells[i].width = Cm(w)
        self.p(space=2)
        return t


def _commission(d, present, members):
    d.p('Представитель заказчика: ' + ПРЕДСТАВИТЕЛЬ_ЗАКАЗЧИКА + ';', space=0)
    groups = {}
    for role, name, post in members:
        groups.setdefault(role, []).append((name, post))
    for role in ('Председатель комиссии', 'Заместитель председателя комиссии'):
        for name, post in groups.get(role, []):
            d.p(f'{role}: {name} – {post};', space=0)
    d.p('Члены комиссии:', space=0)
    for name, post in groups.get('Член комиссии', []):
        d.p(f'{name} – {post};', space=0)
    d.p('Секретарь комиссии:', space=0)
    for name, post in groups.get('Секретарь комиссии', []):
        d.p(f'{name} -  {post};', space=6)


def _signatures(d, present, executor, members):
    d.p(space=6)
    last = None
    for role, name, post in members:
        title = {'Член комиссии': 'Члены  комиссии:'}.get(role, role + ':')
        if title != last:
            d.p(title, space=0)
            last = title
        here = present.get(name, True)
        d.p(f'{name} ' + ('_____________________________' if here else 'отсутствует'), space=2)
    d.p(space=10)
    d.p(f'Исп.. {executor}  8(495)609-14-00' if executor else 'Исп.. ', size=10)


def _participants_rows(parts, with_reason=True):
    rows = []
    for i, x in enumerate(parts, 1):
        who = f"Участник № {x.get('id') or i} от {x.get('date') or ''}".strip()
        name = x.get('name') or ''
        if x.get('inn'):
            name += f" ({x['inn']}{'/' + x['kpp'] if x.get('kpp') else ''})"
        dec = x.get('decision') or 'Допущена'
        reason = x.get('reason') or ('-' if dec == 'Допущена' else '')
        rows.append([i, who, name, dec, reason] if with_reason else [i, who, name, dec])
    return rows


def _apps_sentence(n, bid):
    when = f'До 09 часов 00 минут (время московское) {bid} года' if bid else ''
    if n == 0:
        return f'По окончании срока подачи заявок до 09 часов 00 минут (время московское) {bid} года не было подано ни одной заявки.', True
    if n == 1:
        return f'По окончании срока подачи заявок до 09 часов 00 минут (время московское) {bid} года была подана 1 заявка от участника.', False
    word = plural_ru(n, 'заявка', 'заявки', 'заявок')
    verb = 'была подана' if n % 10 == 1 and n % 100 != 11 else 'были поданы'
    return f'По окончании срока подачи заявок до 09 часов 00 минут (время московское) {bid} года {verb} {n} {word} от участников.', False


def build_protocol_docx(kind, info, p, present=None, executor='', extra=None):
    """kind — ключ PROTOCOL_KINDS; info — сведения о закупке из реестра; p — данные протокола."""
    if kind == 'konk_result':
        raise ValueError('Протокол подведения итогов конкурса с оценкой по критериям формируется вручную — '
                         'загрузите готовый файл, данные внесутся в реестр.')
    present = present or {}
    title, _ = PROTOCOL_KINDS[kind]
    form_nk = (info.get('form') or '').lower()
    if kind == 'nk_result':
        title += ' редукционе' if 'редукцион' in form_nk or info.get('oao', '').lower().endswith('р') else ' запроса ценовых предложений'
    platform = PLATFORMS.get(info.get('site') or '', PLATFORMS['АСТ ГОЗ'] if kind.startswith(('konk', 'auc')) else PLATFORMS['Росэлторг'])
    parts = p.get('participants') or []
    admitted = [x for x in parts if (x.get('decision') or 'Допущена') == 'Допущена']
    winner = p.get('winner') or {}
    n_apps = p.get('apps') if p.get('apps') not in (None, '') else len(parts)

    d = _Doc()
    d.p(ORG_TITLE, bold=True, center=True, size=11, space=8)
    d.p('Протокол', bold=True, center=True, space=0)
    d.p(COMMISSION_OF, bold=True, center=True, space=0)
    d.p(title, bold=True, center=True, space=10)
    par = d.p(space=6)
    par.paragraph_format.tab_stops.add_tab_stop(Cm(17), WD_TAB_ALIGNMENT.RIGHT)
    _font(par.add_run(f"№{info['number']}/{p['seq']}({info['oao']})\tот {date_quoted(p['date'])} г."), 12, True)
    d.p('г. Москва', space=8)
    subject = {'k': 'ЭЛЕКТРОННОГО КОНКУРСА' if kind.startswith('konk') else 'ЗАКРЫТОГО АУКЦИОНА В ЭЛЕКТРОННОЙ ФОРМЕ'}.get(
        'k' if kind.startswith(('konk', 'auc')) else 'nk', 'НЕКОНКУРЕНТНОЙ ЗАКУПКИ ЗАПРОСА ЦЕНОВЫХ ПРЕДЛОЖЕНИЙ')
    d.runs([(f'ПРЕДМЕТ {subject}: ', True, False), (info.get('name', ''), False, False)], indent=False)
    d.p('Начальная (максимальная) цена договора:', bold=True, space=0)
    d.p(money_words(info.get('nmck')) + '; ', space=8)
    members = commission() + [(x.get('role') or 'Член комиссии', fio_initials(x.get('name')), x.get('post', ''))
                              for x in (extra or []) if fio_initials(x.get('name'))]
    order = {'Председатель комиссии': 0, 'Заместитель председателя комиссии': 1, 'Член комиссии': 2, 'Секретарь комиссии': 3}
    members.sort(key=lambda m: order.get(m[0], 2))
    _commission(d, present, members)

    n = 1
    d.p(f'{n}. Место рассмотрения: {PLACE} ', indent=True); n += 1
    d.p(f"{n}. Извещение о проведении настоящей процедуры и документация были размещены "
        f"{info.get('publish') or '__.__.____'} года {platform[0]}.", indent=True); n += 1
    sent, none = _apps_sentence(n_apps, info.get('bid') or '__.__.____')
    d.p(f'{n}. {sent}', indent=True); n += 1

    if kind == 'konk_open':
        d.table(['№ п/п', 'Номер, дата и время регистрации заявки', 'Идентификационный номер участника'],
                [[i, x.get('date', ''), x.get('id', '')] for i, x in enumerate(parts, 1)], [1.5, 8, 7])
    elif parts:
        d.p(f'{n}. Комиссия рассмотрела {"заявку" if len(parts) == 1 else "заявки"} на участие в процедуре и приняла решение:', indent=True); n += 1
        d.table(['№п/п', 'Номер, дата и время регистрации заявки', 'Наименование участника',
                 'Решение о допуске или об отказе в допуске',
                 'Основание допуска или отклонения с указанием положений документации, которым не соответствует заявка'],
                _participants_rows(parts), [1.2, 3.8, 4.5, 2.8, 4.7])

    if kind == 'auc_review':
        d.p(f"{n}. В соответствии с п.4.6.1 {POLICY}, закрытый аукцион в электронной форме проводится "
            f"{platform[0]}   {info.get('trade') or '__.__.____'}г. в 11.00 (время московское).", indent=True); n += 1
    elif kind == 'auc_result':
        bids = sorted([x for x in admitted if x.get('price')], key=lambda x: x['price'])
        d.p(f"{n}. Дата и время начала аукциона: {(info.get('trade') or '__.__.____').replace('.', '-')} 11:00:00 ", indent=True); n += 1
        d.p(f'Наименование электронной площадки: {platform[1]}', indent=True)
        d.p(f'Адрес электронной площадки: {platform[2]}.', indent=True)
        d.p(f'{n}. Все минимальные предложения о цене договора, сделанные участниками аукциона в электронной форме '
            f'и ранжированные по мере убывания: ', indent=True); n += 1
        d.table(['Место', 'Наименование участника', 'Сумма предложения', 'Валюта'],
                [[i, f"Участник № {x.get('id')}", money_plain(x['price']), 'RUB'] for i, x in enumerate(bids, 1)], [2, 7, 5, 3])
    elif kind == 'nk_result' and len(admitted) > 1:
        d.p('Все минимальные предложения о цене договора, сделанные участниками на участие в неконкурентной закупке '
            'запроса ценовых предложений', indent=True)
        ranked = sorted([x for x in admitted if x.get('price')], key=lambda x: x['price'])
        place = {id(x): i for i, x in enumerate(ranked, 1)}
        d.table(['Идентификационный номер участника', 'Предложение участника', 'Место'],
                [[f"Участник №{x.get('id')}", money_plain(x.get('price')), place.get(id(x), '')] for x in admitted], [6, 6, 4])

    single = kind in ('auc_single', 'nk_result') and len(admitted) == 1
    if kind in ('auc_single', 'nk_result', 'auc_result'):
        if none or not admitted:
            what = 'закрытый аукцион в электронной форме несостоявшимся' if kind.startswith('auc') else 'закупку несостоявшейся'
            reason = 'в связи с отсутствием заявок' if none else 'в связи с отклонением всех заявок'
            d.runs([(f'{n}. Признать {what} {reason} на основании {POLICY}.', False, True)]); n += 1
        else:
            if single:
                what = 'закрытый аукцион в электронной форме несостоявшимся' if kind == 'auc_single' else 'закупку несостоявшейся'
                d.p(f'{n}. Признать {what} на основании п.1.18.1.1. {POLICY}.', indent=True); n += 1
            smp = {'микро': 'микропредприятие', 'малое': 'малое предприятие', 'среднее': 'среднее предприятие',
                   'СОНКО': 'социально ориентированная некоммерческая организация'}.get(winner.get('smp', ''), '')
            d.p(f"{n}.На основании выше изложенного комиссия единогласно решила передать проект договора участнику "
                f"{'(' + smp + ') ' if smp else ''}{winner.get('name', '')} ИНН {winner.get('inn', '')} "
                f"(Участник №{winner.get('id', '')}) на сумму {money_words(winner.get('price'))}.", indent=True); n += 1

    final_word = 'рассмотрения заявок и подведение итогов' if kind == 'nk_result' and len(admitted) > 1 else 'рассмотрения заявок'
    if kind == 'konk_open':
        final_word = 'вскрытия заявок'
    d.p(f'{n}. Настоящий протокол {final_word} направлен {platform[0].replace("на сайте", "на сайт", 1)}.', indent=True); n += 1
    if single and not none:
        what = 'аукцион признан несостоявшимся' if kind == 'auc_single' else 'закупка признана несостоявшейся'
        d.p(f'{n}. В связи с тем, что {what}, Заказчик просит Вас в целях экономии бюджетных средств в добровольном '
            f'порядке снизить начальную (максимальную) цену договора, так как понижение начальной (максимальной) цены не было.', indent=True)
    _signatures(d, present, executor, members)
    buf = io.BytesIO()
    d.doc.core_properties.title = f"Протокол {info['number']}/{p['seq']}({info['oao']})"
    d.doc.save(buf)
    return buf.getvalue()


def money_plain(v):
    try:
        return f'{float(v):,.2f}'.replace(',', ' ').replace('.', ',')
    except (TypeError, ValueError):
        return ''


def protocol_info(number):
    """Сведения о закупке для протокола — из реестра и карточки."""
    r = match_row(number)
    if not r:
        raise ValueError(f'Закупка {number} не найдена в реестре')
    fields = {nkey(k): v for k, v in (r.get('fields') or [])}
    site = ''
    for name in PLATFORMS:
        if name.lower().replace(' ', '') in (fields.get(nkey('Наименование торговой площадки')) or '').lower().replace(' ', ''):
            site = name
    pub_text = fields.get(nkey('Номер и Дата публикации'), '')
    if not site:
        low = pub_text.lower()
        site = 'Росэлторг' if 'roseltorg' in low or r['number'].startswith('COM') else 'ЭТП ГПБ' if 'etpgpb' in low else 'АСТ ГОЗ'
    return {'number': r['number'], 'oao': r['oao'], 'name': r['name'], 'nmck': r.get('nmck'),
            'publish': iso_to_ru(r.get('pub') or ''), 'bid': iso_to_ru(r.get('bid') or ''),
            'trade': iso_to_ru(r.get('trade') or ''), 'site': site, 'kind': 'nk' if r['sheet'] == 'nk' else 'k',
            'abbr': r.get('abbr', ''), 'form': 'редукцион' if r.get('oao', '').lower().endswith('р') else ''}

