# ДАННЫЕ ДЛЯ ПАНЕЛИ
# ============================================================

cache = {'mtime': None, 'sheets': [], 'rows': [], 'error': None, 'years': {}}
CACHE_LOCK = threading.Lock()
started = datetime.now().isoformat(timespec='seconds')


def refresh_cache(force=False):
    """Перечитывает реестры годов, только если файл изменился."""
    with CACHE_LOCK:
        changed, errors = False, []
        for Y in years():
            yc = cache['years'].setdefault(Y.y, {'mtime': None, 'sheets': [], 'rows': []})
            try:
                mtime = Y.registry.stat().st_mtime if Y.registry.exists() else None
                if mtime is None:
                    if yc['rows']:
                        yc.update(mtime=None, sheets=[], rows=[])
                        changed = True
                    continue
                if force or mtime != yc['mtime']:
                    yc['sheets'], yc['rows'] = read_registry(Y.registry, Y.y)
                    yc['mtime'] = mtime
                    changed = True
            except PermissionError:
                errors.append(f'Реестр {Y.y} сейчас недоступен для чтения — показаны последние данные.')
            except Exception as e:
                errors.append(f'Не удалось прочитать реестр {Y.y}: {type(e).__name__}: {e}')
        if changed:
            sheets, seen = [], set()
            for y in sorted(cache['years']):
                for sh in cache['years'][y]['sheets']:
                    if sh['key'] not in seen:
                        seen.add(sh['key'])
                        sheets.append(sh)
            cache['sheets'] = sheets
            cache['rows'] = [r for y in sorted(cache['years']) for r in cache['years'][y]['rows']]
            ms = [c['mtime'] for c in cache['years'].values() if c['mtime']]
            cache['mtime'] = max(ms) + len(ms) * 1e-3 if ms else None
            try:
                track_appearances(cache['rows'])
            except Exception as e:
                log('error', f'Не удалось обновить «когда появились»: {e}')
        if not any(Y.registry.exists() for Y in years()):
            errors.append('Реестр ещё не создан: он появится после первого извещения.')
        cache['error'] = ' '.join(errors) or None


def mark_nauka(rows):
    """«Наука»: закупка ОАО, номер которой (цифры номера ОАО) есть в «Электронных заявках» ОПАиЗ (с учётом года)."""
    keys = set()
    try:
        for z in oz_load('zayavki')['rows']:
            m = re.match(r'\s*(\d+)', str(z.get('n1c') or ''))
            if m:
                fy = str(z.get('fy') or '')
                keys.add((m.group(1), int(fy) if fy.isdigit() else None))
    except Exception:
        pass
    digits = {k[0] for k in keys if k[1] is None}
    for r in rows:
        m = re.match(r'(\d+)', r.get('oao') or '')
        r['nauka'] = bool(m) and ((m.group(1), r.get('year')) in keys or m.group(1) in digits)
    return rows


def build_payload():
    refresh_cache()
    mark_nauka(cache['rows'])
    queue = []
    for Y, kind, folder in intake_folders():
        if folder.exists():
            for f in sorted(folder.glob('*.docx')):
                if not f.name.startswith('~$'):
                    queue.append({'file': f.name, 'year': Y.y, 'kind': kind,
                                  'reason': ignored.get(str(f), (0, ''))[1]})
    return {
        'title': 'Реестр закупок',
        'version': ВЕРСИЯ,
        'generated': datetime.now().isoformat(timespec='seconds'),
        'registry_path': str(ПАПКА_РЕЕСТРА),
        'registry_url': '/api/registry',
        'years': [{'year': Y.y, 'intake': Y.intake, 'exists': Y.registry.exists(), 'file': Y.registry.name,
                   'path': str(Y.registry)} for Y in years()],
        'current_year': year_obj().y,
        'registry_mtime': datetime.fromtimestamp(cache['mtime']).isoformat(timespec='seconds') if cache['mtime'] else None,
        'sheets': cache['sheets'],
        'rows': cache['rows'],
        'queue': queue,
        'journal': load_journal()[-60:],
        'watcher': {'user': USER, 'host': HOST, 'started': started,
                    'alive': datetime.now().isoformat(timespec='seconds'), 'interval': ИНТЕРВАЛ},
        'lists': {'letters': LETTERS, 'subsidies': SUBSIDIES, 'responsibles': [x['fio'] for x in load_responsibles()],
                  'resp_emails': {x['fio']: x['email'] for x in load_responsibles()},
                  'commission': [{'role': r, 'name': n, 'post': p} for r, n, p in commission()],
                  'staff_opaiz': staff_opaiz(), 'sgoz': directories().get('sgoz', {}), 'holidays': ПРАЗДНИКИ,
                  'smp_norms': {'smp': НОРМАТИВ_СМП, 'smp_only': НОРМАТИВ_ТОЛЬКО_СМП, 'sonko': НОРМАТИВ_СОНКО},
                  'protocol_kinds': {k: v[0] for k, v in PROTOCOL_KINDS.items()},
                  'contract_wait_days': ДОГОВОР_ЖДЁМ_ДНЕЙ},
        'pending': len(_pending_load()),
        'review': len(review_list()),
        'publish': publish_tasks(),
        'publish_error': ANALYSTS.get('error'),
        'error': cache['error'],
    }


# ============================================================
# ОТЧЁТЫ: руководству (неделя) и бухгалтерии (служебная записка)
# ============================================================
# Неделя отчёта закрывается в ОТЧЁТ_ДЕНЬ в ОТЧЁТ_ВРЕМЯ (по умолчанию пятница, 17:00).
# Договор попадает в отчёт той недели, когда он и подписан (дата договора), и уже был в реестре
# к моменту отправки. Подписан в пятницу в 18:00, в субботу или воскресенье, внесён после 17:00 —
# уходит в следующий отчёт, ничего не теряется и не считается дважды.
# Когда договор впервые появился в реестре, панель запоминает сама (файл «Реестр — когда появились.json»),
# а отправленные отчёты — в «Реестр — отчёты.json»: что ушло в отчёт, там и остаётся.

ОТЧЁТ_ДЕНЬ = 4            # 0 — понедельник … 4 — пятница
ОТЧЁТ_ВРЕМЯ = '17:00'
ОТЧЁТ_АВТО = True         # в ОТЧЁТ_ВРЕМЯ панель сама формирует и фиксирует отчёт (папка «Отчёты»)
ФАЙЛ_ОТЧЁТОВ = 'Реестр — отчёты.json'
ФАЙЛ_ПОЯВЛЕНИЙ = 'Реестр — когда появились.json'
ПАПКА_ОТЧЁТОВ = 'Отчёты'
# Свои шаблоны: положите файлы с этими именами рядом с журналом — панель возьмёт их вместо встроенных.
ШАБЛОН_НЕДЕЛЯ = 'Шаблон — отчёт руководству.xlsx'
ШАБЛОН_БУХ = 'Шаблон — служебная записка в бухгалтерию.docx'

REPORT_LOCK = threading.Lock()


def _cutoff_time():
    h, m = (int(x) for x in ОТЧЁТ_ВРЕМЯ.split(':'))
    return h, m


def report_day(d):
    """День отчёта (пятница), к которому относится дата: суббота и воскресенье — к следующей."""
    return d + timedelta(days=(ОТЧЁТ_ДЕНЬ - d.weekday()) % 7)


def cutoff_of(day):
    h, m = _cutoff_time()
    return datetime(day.year, day.month, day.day, h, m)


def week_of_moment(t):
    day = report_day(t.date())
    return day if t <= cutoff_of(day) else day + timedelta(days=7)


def _json_file(name, default):
    try:
        return json.loads((ПАПКА_ПАНЕЛИ / name).read_text(encoding='utf-8'))
    except (OSError, ValueError):
        return default


def item_id(r):
    return r['number'] or f"{r.get('year', '')}:{r['sheet_title']}:{r['oao']}:{r['row']}"


def is_zero_apps(r):
    w = (r.get('winner') or '').upper()
    return '0 УЧАСТНИК' in w or (r.get('apps') == 0 and r['status'] == 'failed')


def track_appearances(rows):
    """Запоминает, когда договор / «0 заявок» впервые появились в реестре.
    Первый запуск: всё, что уже есть, считается внесённым вовремя."""
    path = ПАПКА_ПАНЕЛИ / ФАЙЛ_ПОЯВЛЕНИЙ
    seen = _json_file(ФАЙЛ_ПОЯВЛЕНИЙ, None)
    first = seen is None
    seen = seen or {}
    now = datetime.now().isoformat(timespec='seconds')
    changed = False
    for r in rows:
        pairs = []
        if r.get('contract_date'):
            pairs.append(('c:' + item_id(r), r['contract_date']))
        if is_zero_apps(r):
            pairs.append(('z:' + item_id(r), r.get('result') or r.get('bid')))
        for key, d in pairs:
            if key not in seen:
                seen[key] = (d + 'T12:00:00') if first and d else now
                changed = True
    if first:
        seen['_начало'] = now
    if changed or first:
        write_atomic(path, json.dumps(seen, ensure_ascii=False, indent=0))
    return seen


def _week_items(rows, kind):
    """kind 'c' — договоры, 'z' — процедуры с 0 заявок. → [(id, базовая неделя, строка)]."""
    seen = _json_file(ФАЙЛ_ПОЯВЛЕНИЙ, {})
    out = []
    for r in rows:
        if kind == 'c':
            if not r.get('contract_date'):
                continue
            d = r['contract_date']
        else:
            if not is_zero_apps(r):
                continue
            d = r.get('result') or r.get('bid')
            if not d:
                continue
        key = kind + ':' + item_id(r)
        base = report_day(date.fromisoformat(d))
        t = seen.get(key)
        if t:
            base = max(base, week_of_moment(datetime.fromisoformat(t)))
        out.append((key, base, r))
    return out


def assign_weeks(rows):
    """{ключ: день отчёта}. Отправленный отчёт неизменен; не попавшее в него — в следующий неотправленный."""
    led = _json_file(ФАЙЛ_ОТЧЁТОВ, {}).get('weeks', {})
    fixed_in = {}
    for wk, rec in led.items():
        if rec.get('fixed'):
            for k in rec.get('items', []):
                fixed_in[k] = date.fromisoformat(wk)
    result = {}
    for kind in ('c', 'z'):
        for key, base, r in _week_items(rows, kind):
            if key in fixed_in:
                result[key] = (fixed_in[key], r, base)
                continue
            w = base
            while led.get(w.isoformat(), {}).get('fixed'):
                w += timedelta(days=7)
            result[key] = (w, r, base)
    return result


def weekly_data(day):
    """Данные отчёта руководству за неделю, которая закрывается в день day."""
    refresh_cache()
    rows = cache['rows']
    led = _json_file(ФАЙЛ_ОТЧЁТОВ, {}).get('weeks', {}).get(day.isoformat(), {})
    groups = {'k': {'c1': [], 'c2': [], 'cx': [], 'z': []}, 'nk': {'c1': [], 'c2': [], 'cx': [], 'z': []}}
    late = []
    for key, (w, r, base) in assign_weeks(rows).items():
        if w != day:
            continue
        g = groups['nk' if r['sheet'] == 'nk' else 'k']
        if key.startswith('z:'):
            g['z'].append(r)
        else:
            a = r.get('apps')
            g['c1' if a == 1 else 'c2' if (a or 0) >= 2 else 'cx'].append(r)
            if report_day(date.fromisoformat(r['contract_date'])) != day:
                late.append(r)
    start = day - timedelta(days=6)
    published = [r for r in rows if r.get('pub') and start.isoformat() <= r['pub'] <= day.isoformat()]

    def agg(lst, eco=True):
        nm = sum(r['nmck'] or 0 for r in lst)
        pr = sum(r['price'] or 0 for r in lst)
        return {'count': len(lst), 'nmck': round(nm, 2), 'price': round(pr, 2), 'eco': round(nm - pr, 2)}

    def short(r):
        return {k: r.get(k) for k in ('oao', 'number', 'name', 'responsible', 'nmck', 'price', 'apps', 'contract',
                                      'contract_date', 'winner', 'pub', 'result', 'sheet', 'letter')}
    out = {'day': day.isoformat(), 'start': (day - timedelta(days=4)).isoformat(),
           'cutoff': cutoff_of(day).isoformat(timespec='minutes'),
           'fixed': led.get('fixed'), 'fixed_by': led.get('by'), 'ep': led.get('ep') or {'count': '', 'sum': ''},
           'late': [short(r) for r in late], 'published': [short(r) for r in sorted(published, key=lambda r: r['pub'])],
           'groups': {}, 'warnings': []}
    for sh, g in groups.items():
        allc = g['c1'] + g['c2'] + g['cx']
        out['groups'][sh] = {'all': agg(allc), 'one': agg(g['c1']), 'many': agg(g['c2']), 'unknown': agg(g['cx']),
                             'zero': agg(g['z']), 'list': [short(r) for r in allc], 'zero_list': [short(r) for r in g['z']]}
        for r in g['cx']:
            out['warnings'].append(f"{r['oao'] or r['number']}: в реестре не указано число заявок — договор в итоге есть, "
                                   f"но не попал ни в «1 заявка», ни в «2 и более».")
    noddate = [r for r in rows if r['status'] == 'contract' and not r.get('contract_date')]
    for r in noddate[:30]:
        out['warnings'].append(f"{r['oao'] or r['number']}: договор отмечен, но нет даты в «Номер и дата договора» — в отчёты не попадает.")
    return out


def _template(name, builtin):
    p = ПАПКА_ПАНЕЛИ / name
    if p.exists():
        return p.read_bytes()
    return base64.b64decode(builtin)


def _period_label(day):
    s = day - timedelta(days=4)
    return f"{s:%d.%m}-{day:%d.%m}"


def build_weekly_xlsx(day):
    data = weekly_data(day)
    wb = load_workbook(io.BytesIO(_template(ШАБЛОН_НЕДЕЛЯ, ШАБЛОН_НЕДЕЛЯ_ВСТРОЕННЫЙ)))
    ws = wb.worksheets[0]
    ws.title = str(day.year)
    ws['B1'] = f'Заключенные договоры в период с {_period_label(day)}'
    k, nk = data['groups']['k'], data['groups']['nk']
    for row, g in ((4, k['all']), (5, k['one']), (6, k['many']), (8, nk['all']), (9, nk['one']), (10, nk['many'])):
        ws[f'C{row}'], ws[f'D{row}'], ws[f'E{row}'] = g['count'], g['nmck'], g['price']
    for row, g in ((7, k['zero']), (11, nk['zero'])):
        ws[f'C{row}'], ws[f'D{row}'] = g['count'], g['nmck']
    ep = data['ep']
    ws['C12'] = int(ep['count']) if str(ep.get('count', '')).strip().isdigit() else None
    ws['E12'] = parse_price(ep['sum']) if str(ep.get('sum', '')).strip() else None
    for row in (4, 8, 13):
        ws[f'G{row}'] = f'=IF(D{row}=0,0,F{row}*100/D{row})'
    note = 15
    if data['late']:
        ws[f'B{note}'] = (f"* в том числе договоров, подписанных или внесённых после отправки прошлого отчёта "
                          f"(после {ОТЧЁТ_ВРЕМЯ} в день отчёта, в выходные): {len(data['late'])}")
        ws[f'B{note}'].alignment = Alignment(wrap_text=False)
        note += 1
    ws[f'B{note}'] = f"Сформировано панелью реестра {datetime.now():%d.%m.%Y %H:%M}; отсечка — {cutoff_of(day):%d.%m.%Y %H:%M}."
    ws[f'B{note}'].font = Font(size=9, italic=True, color='7B7A75')
    ws[f'B{note}'].alignment = Alignment(wrap_text=False)

    # Расшифровка — чтобы было видно, из чего сложились цифры.
    det = wb.create_sheet('Договоры')
    heads = ['Вид', 'ОАО', 'Номер на площадке', 'Наименование', 'Ответственный', 'Заявок', 'НМЦК', 'Цена договора',
             'Экономия', 'Номер и дата договора', 'Победитель', 'Примечание']
    det.append(heads)
    late_ids = {(r['oao'], r['number']) for r in data['late']}
    for sh, title in (('k', 'Конкурентные'), ('nk', 'Неконкурентные')):
        for r in data['groups'][sh]['list']:
            det.append([title, r['oao'], r['number'], r['name'], r['responsible'], r['apps'], r['nmck'], r['price'],
                        (r['nmck'] or 0) - (r['price'] or 0), r['contract'], r['winner'],
                        'после отправки прошлого отчёта' if (r['oao'], r['number']) in late_ids else ''])
    zero = wb.create_sheet('0 заявок')
    zero.append(['Вид', 'ОАО', 'Номер на площадке', 'Наименование', 'Ответственный', 'НМЦК', 'Дата итогов'])
    for sh, title in (('k', 'Конкурентные'), ('nk', 'Неконкурентные')):
        for r in data['groups'][sh]['zero_list']:
            zero.append([title, r['oao'], r['number'], r['name'], r['responsible'], r['nmck'], iso_to_ru(r['result'] or '')])
    pub = wb.create_sheet('Опубликовано за неделю')
    pub.append(['Дата публикации', 'ОАО', 'Номер на площадке', 'Наименование', 'Ответственный', 'Предмет', 'НМЦК'])
    for r in data['published']:
        pub.append([iso_to_ru(r['pub']), r['oao'], r['number'], r['name'], r['responsible'], r['letter'], r['nmck']])
    pub.append([])
    pub.append(['Итого', len(data['published']), '', '', '', '', sum(r['nmck'] or 0 for r in data['published'])])
    for sheet, money_cols, widths in ((det, 'GHI', [14, 10, 18, 60, 16, 8, 16, 16, 16, 22, 40, 28]),
                                      (zero, 'F', [14, 10, 18, 60, 16, 16, 14]),
                                      (pub, 'G', [14, 10, 18, 60, 16, 12, 16])):
        for i, w in enumerate(widths):
            sheet.column_dimensions[chr(65 + i)].width = w
        for c in sheet[1]:
            c.font = Font(bold=True)
            c.fill = PatternFill('solid', fgColor='FFCCECFF')
            c.alignment = Alignment(wrap_text=True, vertical='center')
        for col in money_cols:
            for c in sheet[col][1:]:
                c.number_format = '#,##0.00\\ _₽'
        sheet.freeze_panes = 'A2'
    buf = io.BytesIO()
    wb.save(buf)
    return buf.getvalue(), f'Отчёт руководству {_period_label(day)}.{day.year}.xlsx'


def fix_week(day, who, auto=False):
    """Фиксирует отчёт: что в него вошло, в нём и остаётся. Файл — в папку «Отчёты»."""
    with REPORT_LOCK:
        ledger = _json_file(ФАЙЛ_ОТЧЁТОВ, {})
        weeks = ledger.setdefault('weeks', {})
        rec = weeks.setdefault(day.isoformat(), {})
        if rec.get('fixed'):
            return rec
        refresh_cache()
        items = [k for k, (w, r, b) in assign_weeks(cache['rows']).items() if w == day]
        rec.update({'fixed': datetime.now().isoformat(timespec='seconds'), 'by': who, 'auto': auto, 'items': items})
        write_atomic(ПАПКА_ПАНЕЛИ / ФАЙЛ_ОТЧЁТОВ, json.dumps(ledger, ensure_ascii=False, indent=1))
    content, name = build_weekly_xlsx(day)
    folder = ПАПКА_ПАНЕЛИ / ПАПКА_ОТЧЁТОВ
    folder.mkdir(parents=True, exist_ok=True)
    (folder / name).write_bytes(content)
    log('info', f'Отчёт руководству за {_period_label(day)} зафиксирован' + (' автоматически' if auto else '') +
        f' — {len(items)} позиций. Файл: {ПАПКА_ОТЧЁТОВ}/{name}', user=who)
    return rec


def unfix_week(day, who):
    with REPORT_LOCK:
        ledger = _json_file(ФАЙЛ_ОТЧЁТОВ, {})
        rec = ledger.get('weeks', {}).get(day.isoformat())
        if not rec or not rec.get('fixed'):
            return
        for k in ('fixed', 'by', 'auto', 'items'):
            rec.pop(k, None)
        write_atomic(ПАПКА_ПАНЕЛИ / ФАЙЛ_ОТЧЁТОВ, json.dumps(ledger, ensure_ascii=False, indent=1))
    log('edit', f'Отчёт руководству за {_period_label(day)}: фиксация снята', user=who)


def save_ep(day, ep):
    with REPORT_LOCK:
        ledger = _json_file(ФАЙЛ_ОТЧЁТОВ, {})
        rec = ledger.setdefault('weeks', {}).setdefault(day.isoformat(), {})
        rec['ep'] = {'count': str(ep.get('count', '')).strip(), 'sum': str(ep.get('sum', '')).strip()}
        write_atomic(ПАПКА_ПАНЕЛИ / ФАЙЛ_ОТЧЁТОВ, json.dumps(ledger, ensure_ascii=False, indent=1))


def weekly_list():
    """Недели для выбора: текущая и прошлые (с пометкой «отправлен»)."""
    led = _json_file(ФАЙЛ_ОТЧЁТОВ, {}).get('weeks', {})
    now = datetime.now()
    cur = week_of_moment(now)
    out = []
    for i in range(0, 26):
        d = cur - timedelta(days=7 * i)
        rec = led.get(d.isoformat(), {})
        out.append({'day': d.isoformat(), 'label': f"{_period_label(d)}.{d.year}", 'fixed': rec.get('fixed'),
                    'auto': rec.get('auto'), 'current': i == 0})
    return out


def auto_weekly():
    """Вызывается из фонового цикла: в пятницу в 17:00 фиксирует отчёт сам."""
    if not ОТЧЁТ_АВТО:
        return
    now = datetime.now()
    day = report_day(now.date())
    if now < cutoff_of(day):
        day -= timedelta(days=7)
    if (now - cutoff_of(day)) > timedelta(days=3):
        return          # панель была выключена долго — пусть зафиксируют вручную
    rec = _json_file(ФАЙЛ_ОТЧЁТОВ, {}).get('weeks', {}).get(day.isoformat(), {})
    if not rec.get('fixed') and any(Y.registry.exists() for Y in years()):
        fix_week(day, 'панель', auto=True)


# ---------- служебная записка в бухгалтерию ----------

BUH_ROWS = [('auc', 'Закрытые электронные аукционы'), ('konk', 'Закрытые электронные конкурсы'),
            ('nk', 'Запросы ценовых предложений')]


def proc_type(r):
    if r['sheet'] == 'nk':
        return 'nk'
    a = (r.get('abbr') or '').upper()
    return 'konk' if a.endswith('К') else 'auc'


def buh_data(start, end):
    """Только заключённые договоры: дата договора в периоде (обе границы включительно).
    «Размещено» = те же закупки: их количество и НМЦК; «заключено» — количество и цена договоров."""
    refresh_cache()
    s, e = start.isoformat(), end.isoformat()
    out = {}
    for key, title in BUH_ROWS:
        rs = [r for r in cache['rows'] if proc_type(r) == key]
        signed = [r for r in rs if r.get('contract_date') and s <= r['contract_date'] <= e]
        nm = sum(r['nmck'] or 0 for r in signed)
        pr = sum(r['price'] or 0 for r in signed)
        out[key] = {'title': title, 'placed': len(signed), 'placed_sum': round(nm, 2),
                    'signed': len(signed), 'signed_sum': round(pr, 2), 'eco': round(nm - pr, 2)}
    return out


def _money_ru(v):
    if v in (None, ''):
        return ''
    return f'{float(v):,.2f}'.replace(',', ' ').replace('.', ',')


def build_buh_docx(start, end, manual):
    """Строки 1–3 (аукционы, конкурсы, неконкурентные) и «Всего»; строки ПЭО (4–5) убраны по просьбе ОПАиЗ."""
    data = buh_data(start, end)
    doc = Document(io.BytesIO(_template(ШАБЛОН_БУХ, ШАБЛОН_БУХ_ВСТРОЕННЫЙ)))
    as_of = end + timedelta(days=1)
    for p in doc.paragraphs:
        if 'по состоянию на' in p.text:
            txt = re.sub(r'по состоянию на\s*[\d.\s]+', f'по состоянию на {as_of:%d.%m.%Y}', p.text)
            for i, r in enumerate(p.runs):
                r.text = txt if i == 0 else ''
            break
    t = doc.tables[0]

    def put(cell, value):
        par = cell.paragraphs[0]
        rpr = None
        for p in cell.paragraphs:
            for r in p.runs:
                rpr = rpr or r._r.rPr
        for p in cell.paragraphs[1:]:
            p._p.getparent().remove(p._p)
        for r in list(par.runs):
            r._r.getparent().remove(r._r)
        run = par.add_run(str(value))
        if rpr is not None:
            run._r.insert(0, copy(rpr))
        else:
            run.font.name, run.font.size = 'Times New Roman', Pt(12)

    total = {'placed': 0, 'placed_sum': 0.0, 'signed': 0, 'signed_sum': 0.0, 'eco': 0.0}
    for i, (key, _) in enumerate(BUH_ROWS, start=1):
        d = data[key]
        cells = t.rows[i].cells
        put(cells[2], d['placed']); put(cells[3], _money_ru(d['placed_sum']))
        put(cells[4], d['signed']); put(cells[5], _money_ru(d['signed_sum'])); put(cells[6], _money_ru(d['eco']))
        for k in total:
            total[k] += d[k]
    cells = t.rows[6].cells
    put(cells[2], total['placed']); put(cells[3], _money_ru(total['placed_sum']))
    put(cells[4], total['signed']); put(cells[5], _money_ru(total['signed_sum'])); put(cells[6], _money_ru(total['eco']))
    for i in (5, 4):        # строки ПЭО (ЕП малого объёма, без торгов) из записки убраны
        tr = t.rows[i]._tr
        tr.getparent().remove(tr)
    buf = io.BytesIO()
    doc.save(buf)
    return buf.getvalue(), f'Служебная записка в бухгалтерию на {as_of:%d.%m.%Y}.docx', data


# ---------- аналитика в Excel (таблицы считает панель, здесь — оформление и графики) ----------

def build_analytics_xlsx(spec):
    """spec: {'title', 'period', 'sheets': [{'name', 'head': [...], 'rows': [[...]], 'money': [col idx],
    'pct': [col idx], 'chart': {'type': 'bar'|'line'|'pie', 'cats': col, 'vals': [cols], 'title'}}]}"""
    from openpyxl.chart import BarChart, LineChart, PieChart, Reference
    wb = Workbook()
    wb.remove(wb.active)
    thin = Side(style='thin', color='CFCDC6')
    for sh in spec.get('sheets', [])[:30]:
        ws = wb.create_sheet(re.sub(r'[\\/*?:\[\]]', ' ', sh['name'])[:31])
        ws['A1'] = sh.get('title') or sh['name']
        ws['A1'].font = Font(bold=True, size=13)
        ws['A2'] = spec.get('period', '')
        ws['A2'].font = Font(italic=True, color='7B7A75')
        ws.append([])
        ws.append(sh['head'])
        hr = ws.max_row
        for c in ws[hr]:
            c.font = Font(bold=True)
            c.fill = PatternFill('solid', fgColor='FFCCECFF')
            c.alignment = Alignment(wrap_text=True, vertical='center', horizontal='center')
            c.border = Border(top=thin, bottom=thin, left=thin, right=thin)
        for row in sh['rows']:
            ws.append(row)
        last = ws.max_row
        for r in ws.iter_rows(min_row=hr + 1, max_row=last):
            for c in r:
                c.border = Border(top=thin, bottom=thin, left=thin, right=thin)
            for i in sh.get('money', []):
                r[i].number_format = '#,##0.00\\ _₽'
            for i in sh.get('pct', []):
                r[i].number_format = '0.0"%"'
        for i, h in enumerate(sh['head']):
            width = max([len(str(h))] + [len(str(x[i])) for x in sh['rows'][:200] if i < len(x)])
            ws.column_dimensions[chr(65 + i) if i < 26 else 'Z'].width = min(max(10, width + 2), 60)
        ws.freeze_panes = ws.cell(hr + 1, 1)
        ws.page_setup.orientation = 'landscape'
        ws.page_setup.fitToWidth, ws.page_setup.fitToHeight = 1, 0
        ws.sheet_properties.pageSetUpPr.fitToPage = True
        ch = sh.get('chart')
        n = last - hr
        if ch and n >= 1:
            kind = ch.get('type', 'bar')
            chart = {'bar': BarChart, 'line': LineChart, 'pie': PieChart}[kind]()
            chart.title = ch.get('title', '')
            chart.height, chart.width = 8, 18
            for col in ch['vals']:
                ref = Reference(ws, min_col=col + 1, min_row=hr, max_row=last)
                chart.add_data(ref, titles_from_data=True)
            chart.set_categories(Reference(ws, min_col=ch['cats'] + 1, min_row=hr + 1, max_row=last))
            if kind == 'bar':
                chart.type = 'col' if n <= 14 else 'bar'
            ws.add_chart(chart, ws.cell(hr, len(sh['head']) + 2).coordinate)
    if not wb.sheetnames:
        wb.create_sheet('Пусто')
    buf = io.BytesIO()
    wb.save(buf)
    return buf.getvalue()


# ============================================================
# «ОПУБЛИКОВАТЬ»: задачи из реестра аналитиков
# ============================================================

ANALYSTS = {'mtime': None, 'rows': [], 'error': None}


def is_workday(d):
    """Рабочий день по производственному календарю: будни, кроме ПРАЗДНИКИ, плюс перенесённые РАБОЧИЕ_ВЫХОДНЫЕ."""
    iso = d.isoformat()
    if iso in set(РАБОЧИЕ_ВЫХОДНЫЕ):
        return True
    return d.weekday() < 5 and iso not in set(ПРАЗДНИКИ)


def add_workdays(d, n):
    while n > 0:
        d += timedelta(days=1)
        if is_workday(d):
            n -= 1
    return d


def workdays_between(a, b):
    """Рабочих дней после a до b включительно (a, b — date)."""
    n, d = 0, a
    while d < b:
        d += timedelta(days=1)
        if is_workday(d):
            n += 1
    return n


def _analyst_sheet_year(title):
    m = re.fullmatch(r'\s*(1\s*[СC]\s*)?(20\d\d)\s*', title)
    return (int(m.group(2)), bool(m.group(1))) if m else None


def read_analysts():
    """Строки реестра аналитиков с датой «на публикацию». Перечитывается при изменении файла."""
    f = Path(ФАЙЛ_АНАЛИТИКОВ)
    if not f.exists():
        ANALYSTS.update(rows=[], error=None, mtime=None)
        return []
    mtime = f.stat().st_mtime
    if mtime == ANALYSTS['mtime']:
        return ANALYSTS['rows']
    rows = []
    try:
        wb = load_workbook(f, read_only=True, data_only=True)
    except PermissionError:
        return ANALYSTS['rows']
    try:
        for ws in wb.worksheets:
            sy = _analyst_sheet_year(ws.title)
            if not sy:
                continue
            data = list(ws.iter_rows(values_only=True))
            if not data:
                continue
            heads = [nkey(h) for h in data[0]]

            def col(*names):
                for n in names:
                    for i, h in enumerate(heads):
                        if h.startswith(nkey(n)):
                            return i
                return None
            c = {'num': col('Входящий номер ОАО', 'Номер ОАО'), 'name': col('Название'), 'sum': col('Сумма'),
                 'kind': col('Вид закупки'), 'resp': col('Ответственный в ОАО'), 'req': col('на публикацию'),
                 'confirm': col('Подтверждение публикации'), 'plan': col('План-график', 'по п/г'), 'peo': col('№ ПЭО', '№ ПФО')}
            if c['num'] is None or c['req'] is None:
                continue
            for i, r in enumerate(data[1:], start=2):
                g = lambda k: r[c[k]] if c[k] is not None and c[k] < len(r) else None
                num = cell_text(g('num'))
                m = re.match(r'\s*(\d+)\s*([^\d\s][^\d]*?)?\s*(\d{1,2}\.\d{1,2}\.\d{2,4})?\s*$', num)
                req = to_iso(g('req'))
                if not m or not req:
                    continue
                suffix = (m.group(2) or '').strip()
                rows.append({'year': sy[0], 'one_c': sy[1], 'sheet': ws.title, 'row': i, 'digits': m.group(1),
                             'oao': (m.group(1) + ' ' + suffix).strip(), 'suffix': suffix, 'name': cell_text(g('name')),
                             'sum': to_number(g('sum')), 'kind': cell_text(g('kind')), 'resp_raw': cell_text(g('resp')),
                             'requested': req, 'confirmed': to_iso(g('confirm')), 'plan': cell_text(g('plan')),
                             'peo': cell_text(g('peo'))})
    finally:
        wb.close()
    ANALYSTS.update(rows=rows, mtime=mtime, error=None)
    return rows


def _resp_from_surname(raw):
    key = fio_key(raw)
    if not key:
        return ''
    cands = [p['fio'] for p in load_responsibles() if fio_key(p['fio'])[0] == key[0] and same_initials(fio_key(p['fio'])[1], key[1])]
    return cands[0] if len(cands) == 1 else fio_initials(raw)


def publish_tasks():
    """Задачи «Опубликовать»: дата «на публикацию» + ДНЕЙ_НА_ПУБЛИКАЦИЮ рабочих дней.
    Закрыта, когда в реестре того же года появилась закупка с этим номером ОАО."""
    try:
        src = read_analysts()
    except Exception as e:
        ANALYSTS['error'] = f'Не удалось прочитать реестр аналитиков: {e}'
        return []
    reg = {}
    for r in cache['rows']:
        m = re.match(r'(\d+)', r.get('oao') or '')
        if m:
            reg.setdefault((r.get('year'), m.group(1)), r)
    today = date.today()
    out = []
    for a in src:
        deadline = add_workdays(date.fromisoformat(a['requested']), ДНЕЙ_НА_ПУБЛИКАЦИЮ)
        hit = reg.get((a['year'], a['digits']))
        pub = hit.get('pub') if hit else None
        if hit and (today - date.fromisoformat(a['requested'])).days > 45:
            continue            # давно опубликовано — в задачах не держим
        out.append(dict(a, responsible=_resp_from_surname(a['resp_raw']), deadline=deadline.isoformat(),
                        done=bool(hit), pub=pub, number=hit.get('number') if hit else '',
                        late=bool(hit and pub and pub > deadline.isoformat()) or (not hit and today > deadline)))
    out.sort(key=lambda t: (t['done'], t['deadline']))
    return out


# ============================================================
# СПРАВОЧНИК КОНТРАГЕНТОВ
# ============================================================
# Собирается сам: победители и ИНН из реестров всех лет, участники из внесённых протоколов,
# поставщики из договоров. Ручные правки (КПП, ОГРН, адрес, почта…) — в «Реестр — контрагенты.json».

ФАЙЛ_КОНТРАГЕНТОВ = 'Реестр — контрагенты.json'
SUPPLIER_FIELDS = ('name', 'inn', 'kpp', 'ogrn', 'smp', 'address', 'email', 'phone', 'note')


def _org_name(v):
    s = re.sub(r'\(?\s*ИНН[^)]*\)?', '', str(v or ''), flags=re.IGNORECASE)
    return re.sub(r'\s+', ' ', s).strip(' ,;')


def supplier_key(name, inn):
    inn = re.sub(r'\D', '', str(inn or ''))
    return inn if len(inn) in (10, 12) else 'n:' + nkey(_org_name(name))


def suppliers():
    refresh_cache()
    by = {}

    def add(name, inn='', kpp='', smp='', **kw):
        name = _org_name(name)
        if not name or 'НЕ СОСТОЯЛ' in name.upper():
            return None
        inn = re.sub(r'\D', '', str(inn or ''))
        key = supplier_key(name, inn)
        rec = by.setdefault(key, {'key': key, 'name': name, 'inn': inn, 'kpp': '', 'ogrn': '', 'smp': '', 'address': '',
                                  'email': '', 'phone': '', 'note': '', 'contracts': 0, 'sum': 0.0, 'bids': 0,
                                  'wins': 0, 'last': '', 'oaos': []})
        if kpp and not rec['kpp']:
            rec['kpp'] = re.sub(r'\D', '', str(kpp))
        if smp and not rec['smp']:
            rec['smp'] = smp
        return rec

    for r in cache['rows']:
        if r.get('winner') and r['status'] != 'failed':
            inn = r.get('inn') or (re.search(r'ИНН\s*(\d{10,12})', r['winner']) or [None, ''])[1]
            rec = add(r['winner'], inn)
            if rec:
                rec['wins'] += 1
                if r.get('contract_date'):
                    rec['contracts'] += 1
                    rec['sum'] += r.get('price') or 0
                    rec['last'] = max(rec['last'], r['contract_date'])
                if r.get('oao') and len(rec['oaos']) < 30:
                    rec['oaos'].append(r['oao'])
    for number, item in load_store().items():
        for x in item.get('participants') or []:
            rec = add(x.get('name'), x.get('inn'), x.get('kpp'), x.get('smp'))
            if rec:
                rec['bids'] += 1
        c = item.get('contract') or {}
        if c.get('supplier'):
            add(c['supplier'], c.get('inn'))
    manual = _json_file(ФАЙЛ_КОНТРАГЕНТОВ, {})
    for key, m in manual.items():
        rec = by.get(key) or add(m.get('name', ''), m.get('inn', ''))
        if rec:
            rec.update({k: v for k, v in m.items() if k in SUPPLIER_FIELDS and v not in (None, '')})
            rec['edited'] = True
    out = list(by.values())
    for r in out:
        r['sum'] = round(r['sum'], 2)
    out.sort(key=lambda r: (-r['contracts'], -r['bids'], r['name'].lower()))
    return out


def save_supplier(data, actor):
    name = _org_name(data.get('name'))
    if not name:
        raise ValueError('Укажите наименование')
    inn = re.sub(r'\D', '', str(data.get('inn') or ''))
    if inn and len(inn) not in (10, 12):
        raise ValueError('ИНН — 10 цифр (организация) или 12 (ИП)')
    key = data.get('key') or supplier_key(name, inn)
    new_key = supplier_key(name, inn)
    manual = _json_file(ФАЙЛ_КОНТРАГЕНТОВ, {})
    rec = {k: str(data.get(k) or '').strip() for k in SUPPLIER_FIELDS}
    rec.update(name=name, inn=inn)
    if key != new_key:
        manual.pop(key, None)
    manual[new_key] = rec
    write_atomic(ПАПКА_ПАНЕЛИ / ФАЙЛ_КОНТРАГЕНТОВ, json.dumps(manual, ensure_ascii=False, indent=1))
    log('edit', f'Справочник контрагентов: {name}' + (f' (ИНН {inn})' if inn else ''), user=(actor or {}).get('fio') or 'панель')
    return rec


# ============================================================
# ПРОТОКОЛЫ ИЗ ПАПКИ
# ============================================================
# Протокол (или договор), положенный в «Протоколы\входящие» года, вносится сам, если он только
# заполняет пустые ячейки. Если в реестре уже стоит другое значение, или закупка не найдена,
# или документ не распознан — он попадает в очередь «Проверить» в панели (файл ждёт в
# «Протоколы\входящие\на проверке»).

ФАЙЛ_ПРОВЕРКИ = 'Реестр — протоколы на проверке.json'
REVIEW_LOCK = threading.Lock()


def review_list():
    return _json_file(ФАЙЛ_ПРОВЕРКИ, [])


def _review_save(items):
    write_atomic(ПАПКА_ПАНЕЛИ / ФАЙЛ_ПРОВЕРКИ, json.dumps(items, ensure_ascii=False, indent=1, default=str))


def _to_review(Y, f, doc, reason, number='', oao=''):
    hold = Y.protocols_in() / 'на проверке'
    target = unique_path(hold, f.name)
    f.rename(target)
    with REVIEW_LOCK:
        items = review_list()
        items.append({'id': secrets.token_hex(6), 'year': Y.y, 'file': str(target), 'name': f.name, 'doc': doc,
                      'reason': reason, 'number': number, 'oao': oao, 'at': datetime.now().isoformat(timespec='seconds')})
        _review_save(items)
    log('info', f'{oao or number or f.name}: {reason} — документ ждёт проверки в панели', file=f.name)


def process_protocols():
    for Y in years():
        if not Y.intake:
            continue
        for f in ready_files(Y.protocols_in(), ('*.docx', '*.doc', '*.pdf')):
            try:
                _process_protocol_file(Y, f)
            except RegistryBusy:
                return          # реестр открыт в Excel — попробуем на следующем круге
            except Exception as e:
                ignored[str(f)] = (f.stat().st_mtime, str(e))
                log('error', f'Не удалось обработать {f.name}: {type(e).__name__}: {e}', file=f.name)


def _process_protocol_file(Y, f):
    raw = f.read_bytes()
    text = any_text(raw, f.name)
    kind = detect_doc(text)
    if kind == 'notice':
        _to_review(Y, f, 'notice', 'Это извещение, а не протокол — положите его в папку извещений')
        return
    if kind == 'protocol':
        p = parse_protocol(text)
        r = match_row(p.get('number', ''), p.get('oao', ''))
        payload = {'action': 'protocol', 'protocol': p}
        label = f"протокол №{p.get('seq') or '?'}"
    else:
        p = parse_contract(text)
        r = match_row(p.get('number', ''), p.get('oao', ''))
        payload = {'action': 'contract', 'contract': p}
        label = 'договор'
        if r and not p.get('date'):
            _to_review(Y, f, 'contract', 'В договоре не найдена дата заключения — укажите её', r['number'], r['oao'])
            return
    if not r:
        _to_review(Y, f, kind, f'Закупка для документа ({label}) не найдена в реестре',
                   p.get('number', ''), p.get('oao', ''))
        return
    payload['number'] = r['number']
    try:
        loc, changes = compute(payload['action'], payload)
    except ValueError as e:
        _to_review(Y, f, kind, str(e), r['number'], r['oao'])
        return
    conflicts = [c for c in changes if c['state'] == 'change']
    if conflicts:
        _to_review(Y, f, kind, 'В реестре уже другие данные: ' + ', '.join(c['label'] for c in conflicts[:4]),
                   r['number'], r['oao'])
        return
    payload['token'] = keep_upload(f.name, raw)
    payload['author'] = 'папка протоколов'
    code, ans = handle_apply(payload)
    if code >= 300 and code != 202:
        _to_review(Y, f, kind, ans.get('message', 'не удалось внести'), r['number'], r['oao'])
        return
    f.unlink()        # копия уже в «Протоколы\отработанные» (или «Договоры»)


def review_open(rid):
    """Документ из очереди → тот же разбор, что при перетаскивании в панель."""
    rec = next((x for x in review_list() if x['id'] == rid), None)
    if not rec:
        raise ValueError('Документа уже нет в очереди')
    f = Path(rec['file'])
    if not f.exists():
        review_close(rid, 'drop')
        raise ValueError('Файл документа не найден — запись убрана из очереди')
    ans = handle_doc({'b64': base64.b64encode(f.read_bytes()).decode(), 'filename': rec['name']})
    ans['review'] = rec
    return ans


def review_close(rid, how, actor=None):
    """how: 'done' — внесено через панель (файл уже в архиве), 'reject' — отклонено, 'drop' — убрать запись."""
    with REVIEW_LOCK:
        items = review_list()
        rec = next((x for x in items if x['id'] == rid), None)
        if not rec:
            return None
        _review_save([x for x in items if x['id'] != rid])
    f = Path(rec['file'])
    if f.exists():
        if how == 'done':
            f.unlink()
        elif how == 'reject':
            Y = year_obj(rec['year'])
            f.rename(unique_path(Y.protocols_done() / 'Отклонённые', f.name))
    if how == 'reject':
        log('info', f"{rec.get('oao') or rec['name']}: документ из папки отклонён", user=(actor or {}).get('fio') or 'панель')
    return rec


# ============================================================
# ПОЛЬЗОВАТЕЛИ И ВХОД
# ============================================================
# Пароли хранятся только в виде соли и хэша (PBKDF2). Сессия — случайный ключ в cookie.

USERS_LOCK = threading.Lock()
SESSIONS_FILE = 'Панель — сессии.json'
SESSION_DAYS = 30


def _hash(password, salt):
    return hashlib.pbkdf2_hmac('sha256', password.encode('utf-8'), bytes.fromhex(salt), 120_000).hex()


def load_users():
    return _json_file(ФАЙЛ_ПОЛЬЗОВАТЕЛЕЙ, [])


def save_users(users):
    write_atomic(ПАПКА_ПАНЕЛИ / ФАЙЛ_ПОЛЬЗОВАТЕЛЕЙ, json.dumps(users, ensure_ascii=False, indent=1))


def public_user(u):
    if not u:
        return None
    return {k: u.get(k) for k in ('login', 'fio', 'dept', 'admin', 'can_delete', 'must_change')}


def set_password(u, password):
    u['salt'] = secrets.token_hex(16)
    u['hash'] = _hash(password, u['salt'])


def ensure_first_admin():
    """Нет ни одного пользователя — создаём администратора и печатаем пароль в окне запуска."""
    with USERS_LOCK:
        users = load_users()
        if users:
            return None
        login, fio = ПЕРВЫЙ_АДМИНИСТРАТОР
        pw = secrets.token_urlsafe(8)
        u = {'login': login, 'fio': fio, 'dept': 'ОАО', 'admin': True, 'can_delete': True, 'must_change': True}
        set_password(u, pw)
        save_users([u])
        return login, pw


def check_login(login, password):
    for u in load_users():
        if u['login'].lower() == str(login).strip().lower() and u.get('hash'):
            if hmac.compare_digest(u['hash'], _hash(password, u['salt'])):
                return u
    return None


def new_session(login):
    token = secrets.token_urlsafe(24)
    with USERS_LOCK:
        sess = _json_file(SESSIONS_FILE, {})
        now = time.time()
        sess = {k: v for k, v in sess.items() if v.get('until', 0) > now}
        sess[token] = {'login': login, 'until': now + SESSION_DAYS * 86400}
        write_atomic(ПАПКА_ПАНЕЛИ / SESSIONS_FILE, json.dumps(sess))
    return token


def drop_session(token):
    with USERS_LOCK:
        sess = _json_file(SESSIONS_FILE, {})
        if sess.pop(token, None):
            write_atomic(ПАПКА_ПАНЕЛИ / SESSIONS_FILE, json.dumps(sess))


def user_by_session(token):
    if not token:
        return None
    rec = _json_file(SESSIONS_FILE, {}).get(token)
    if not rec or rec.get('until', 0) < time.time():
        return None
    return next((u for u in load_users() if u['login'] == rec['login']), None)


DEMO_USER = {'login': '', 'fio': '', 'dept': 'ОАО', 'admin': True, 'can_delete': True}


def save_user(data, actor):
    """Создать или изменить пользователя (только администратор)."""
    login = re.sub(r'\s+', '', str(data.get('login') or '')).lower()
    if not re.fullmatch(r'[a-z0-9._-]{3,32}', login):
        raise ValueError('Логин — латиница, цифры, точка или дефис, от 3 до 32 знаков')
    fio = fio_initials(data.get('fio'))
    if not fio:
        raise ValueError('Укажите ФИО')
    dept = data.get('dept') if data.get('dept') in ОТДЕЛЫ else ОТДЕЛЫ[0]
    with USERS_LOCK:
        users = load_users()
        u = next((x for x in users if x['login'] == login), None)
        if not u:
            if not data.get('password'):
                raise ValueError('Для нового пользователя задайте пароль')
            u = {'login': login}
            users.append(u)
        u.update(fio=fio, dept=dept, admin=bool(data.get('admin')), can_delete=bool(data.get('can_delete')))
        if data.get('password'):
            if len(data['password']) < 6:
                raise ValueError('Пароль — не короче 6 знаков')
            set_password(u, data['password'])
            u['must_change'] = login != (actor or {}).get('login')
        if not any(x.get('admin') for x in users):
            raise ValueError('Должен остаться хотя бы один администратор')
        save_users(users)
    log('edit', f'Пользователь {fio} ({login}) сохранён', user=(actor or {}).get('fio') or 'панель')
    return public_user(u)


def delete_user(login, actor):
    with USERS_LOCK:
        users = load_users()
        rest = [u for u in users if u['login'] != login]
        if not any(u.get('admin') for u in rest):
            raise ValueError('Нельзя удалить последнего администратора')
        save_users(rest)
    log('edit', f'Пользователь {login} удалён', user=(actor or {}).get('fio') or 'панель')


def change_own_password(u, old, new):
    if not check_login(u['login'], old):
        raise ValueError('Текущий пароль указан неверно')
    if len(new) < 6:
        raise ValueError('Новый пароль — не короче 6 знаков')
    with USERS_LOCK:
        users = load_users()
        me = next(x for x in users if x['login'] == u['login'])
        set_password(me, new)
        me['must_change'] = False
        save_users(users)


