# УДАЛЕНИЕ ЗАПИСЕЙ (мягкое): строка скрывается в Excel, данные остаются
# ============================================================

ФАЙЛ_УДАЛЁННЫХ = 'Реестр — удалённые записи.json'


def deleted_list():
    return _json_file(ФАЙЛ_УДАЛЁННЫХ, [])


def deleted_keys(year):
    return {(d['sheet'], d['key']) for d in deleted_list() if d.get('year') == year}


def soft_delete(number, expected_pub, reason, actor, restore=False):
    """Скрывает строку закупки в реестре и запоминает, кто и когда. restore=True — возвращает."""
    if restore:
        rec = next((d for d in deleted_list() if d.get('number') == number or d.get('id') == number), None)
        if not rec:
            raise ValueError('Такой удалённой записи нет')
        path = year_obj(rec['year']).registry
    else:
        path = registry_of(number)
        if not path:
            raise ValueError(f'Закупка {number} не найдена в реестре')
    Y = year_of_path(path)
    with REG_LOCK:
        try:
            wb = load_workbook(path)
        except PermissionError:
            raise RegistryBusy('Реестр сейчас открыт в Excel — закройте его и повторите.')
        if restore:
            ws = wb[rec['sheet']] if rec['sheet'] in wb.sheetnames else None
            row = None
            if ws:
                cols, _ = map_columns(ws, header_row(ws))
                for r in range(header_row(ws) + 1, ws.max_row + 1):
                    if nkey(cell_plain(ws.cell(r, cols.get('pub', 1)).value)) == rec['key']:
                        row = r
                        break
            if row:
                ws.row_dimensions[row].hidden = False
                save_workbook(wb, path)
            items = [d for d in deleted_list() if d is not rec and d.get('id') != rec.get('id')]
            write_atomic(ПАПКА_ПАНЕЛИ / ФАЙЛ_УДАЛЁННЫХ, json.dumps(items, ensure_ascii=False, indent=1))
            log('edit', f"{rec.get('oao') or rec.get('number')}: запись восстановлена в реестре {rec['year']}",
                user=actor.get('fio') or 'панель', number=rec.get('number'))
            refresh_cache(force=True)
            return rec
        loc = locate(wb, number)
        if not loc:
            raise ValueError(f'Закупка {number} не найдена в реестре')
        if expected_pub and nkey(loc['pub']) != nkey(expected_pub):
            raise ValueError('Строку в реестре успели изменить — откройте закупку заново')
        ws, row = loc['ws'], loc['row']
        name = cell_plain(ws.cell(row, loc['cols'].get('name', 1)).value) if loc['cols'].get('name') else ''
        oao = re.match(r'\s*(\d+\s*[а-яёА-ЯЁ]+)', loc['pub'])
        rec = {'id': secrets.token_hex(6), 'year': Y.y, 'sheet': ws.title, 'key': nkey(cell_plain(loc['pub'])),
               'pub': cell_plain(loc['pub']), 'number': number, 'oao': oao.group(1) if oao else '', 'name': name,
               'row': row, 'by': actor.get('fio') or actor.get('login') or 'панель',
               'at': datetime.now().isoformat(timespec='seconds'), 'reason': reason or ''}
        ws.row_dimensions[row].hidden = True
        save_workbook(wb, path)
    items = deleted_list() + [rec]
    write_atomic(ПАПКА_ПАНЕЛИ / ФАЙЛ_УДАЛЁННЫХ, json.dumps(items, ensure_ascii=False, indent=1))
    log('edit', f"{rec['oao'] or number}: запись удалена из реестра {Y.y}" + (f' — {reason}' if reason else ''),
        user=rec['by'], number=number, oao=rec['oao'])
    refresh_cache(force=True)
    return rec


# ============================================================
# ВЫГРУЗКА РЕЕСТРА: копия с сортировкой
# ============================================================

def export_sorted(path):
    """Копия реестра, где внутри каждого дня внесения (блок под «---дата---») строки идут
    по дате вскрытия по возрастанию; строки без даты — в конце дня. Рабочий файл не трогается.
    Формулы переносятся вместе со строкой (ссылки на свою строку пересчитываются)."""
    from openpyxl.formula.translate import Translator
    with REG_LOCK:
        wb = load_workbook(path)
    for ws in wb.worksheets:
        top = header_row(ws)
        cols, _ = map_columns(ws, top)
        bid = cols.get('bid')
        if not bid:
            continue
        last = last_row(ws, top)
        width = ws.max_column
        blocks, cur = [], []
        for r in range(top + 1, last + 1):
            first = ws.cell(r, 1).value
            if isinstance(first, str) and first.strip().startswith('---'):
                if cur:
                    blocks.append(cur)
                cur = []
                continue
            cur.append(r)
        if cur:
            blocks.append(cur)
        for rows in blocks:
            if len(rows) < 2:
                continue
            keyed = []
            for i, r in enumerate(rows):
                d = to_iso(ws.cell(r, bid).value)
                keyed.append(((0, d, i) if d else (1, '', i), r))
            order = [r for _, r in sorted(keyed)]
            if order == rows:
                continue
            snap = {}
            for r in rows:
                snap[r] = ([(ws.cell(r, c).value, copy(ws.cell(r, c)._style)) for c in range(1, width + 1)],
                           ws.row_dimensions[r].height, ws.row_dimensions[r].hidden)
            for dst, src in zip(rows, order):
                cells, height, hidden = snap[src]
                for c, (v, st) in enumerate(cells, 1):
                    if isinstance(v, str) and v.startswith('=') and src != dst:
                        try:
                            v = Translator(v, origin=ws.cell(src, c).coordinate).translate_formula(ws.cell(dst, c).coordinate)
                        except Exception:
                            pass
                    cell = ws.cell(dst, c)
                    cell.value = v
                    cell._style = st
                ws.row_dimensions[dst].height = height
                ws.row_dimensions[dst].hidden = hidden
    buf = io.BytesIO()
    wb.save(buf)
    return buf.getvalue()




def xls_sheets(data):
    """Старый Excel (.xls, BIFF8) без сторонних библиотек: {лист: [[значения строки]]}.
    Берутся текст и числа (в т. ч. результаты формул); оформление не читается."""
    import struct
    st = _cfb_streams(data)
    wb = st.get('Workbook') or st.get('Book')
    if not wb:
        raise ValueError('в файле нет книги Excel')

    def records(start=0):
        i = start
        while i + 4 <= len(wb):
            rt, ln = struct.unpack_from('<HH', wb, i)
            yield i, rt, wb[i + 4:i + 4 + ln]
            i += 4 + ln

    sheets, parts, collecting = [], [], False
    for pos, rt, body in records():
        if collecting and rt != 0x3C:
            collecting = False
        if rt == 0x85:                                   # BOUNDSHEET
            off = struct.unpack_from('<I', body, 0)[0]
            kind = body[5]
            cch, flags = body[6], body[7]
            name = body[8:8 + cch * 2].decode('utf-16le', 'ignore') if flags & 1 else body[8:8 + cch].decode('latin-1')
            if kind == 0:
                sheets.append((name, off))
        elif rt == 0xFC:                                 # SST
            parts, collecting = [body], True
        elif rt == 0x3C and collecting:                  # его продолжение
            parts.append(body)
        elif rt == 0x0A:                                 # конец глобальной части книги
            break
    sst = []
    if parts:
        # Разбор строк SST с учётом разрывов на границах CONTINUE.
        bufs = parts
        bi, pos = 0, 8
        total = struct.unpack_from('<I', bufs[0], 4)[0] if len(bufs[0]) >= 8 else 0

        def need(n):
            nonlocal bi, pos
            if pos + n <= len(bufs[bi]):
                return
            if pos >= len(bufs[bi]) and bi + 1 < len(bufs):
                bi += 1
                pos = 0

        for _ in range(total):
            if bi >= len(bufs):
                break
            need(3)
            b = bufs[bi]
            if pos + 3 > len(b):
                break
            cch = struct.unpack_from('<H', b, pos)[0]
            flags = b[pos + 2]
            pos += 3
            rich = struct.unpack_from('<H', b, pos)[0] if flags & 8 else 0
            pos += 2 if flags & 8 else 0
            ext = struct.unpack_from('<I', b, pos)[0] if flags & 4 else 0
            pos += 4 if flags & 4 else 0
            chars, left, wide = [], cch, flags & 1
            while left > 0:
                b = bufs[bi]
                if pos >= len(b):
                    bi += 1
                    if bi >= len(bufs):
                        break
                    b = bufs[bi]
                    wide = b[0] & 1
                    pos = 1
                size = 2 if wide else 1
                take = min(left, (len(b) - pos) // size)
                seg = b[pos:pos + take * size]
                chars.append(seg.decode('utf-16le', 'ignore') if wide else seg.decode('latin-1'))
                pos += take * size
                left -= take
            skip = rich * 4 + ext
            while skip > 0 and bi < len(bufs):
                b = bufs[bi]
                avail = len(b) - pos
                if skip <= avail:
                    pos += skip
                    skip = 0
                else:
                    skip -= avail
                    bi += 1
                    pos = 0
            sst.append(''.join(chars))

    def rk(v):
        if v & 2:
            x = float(v >> 2) if not (v >> 31) else float((v >> 2) - (1 << 30))
        else:
            x = struct.unpack('<d', struct.pack('<Q', (v & 0xFFFFFFFC) << 32))[0]
        return x / 100 if v & 1 else x

    out = {}
    for name, off in sheets:
        cells = {}
        pending = None
        for pos, rt, body in records(off):
            if rt == 0x0A:
                break
            if rt == 0xFD and len(body) >= 10:                 # LABELSST
                r, c, _, i = struct.unpack_from('<HHHI', body, 0)
                cells[(r, c)] = sst[i] if i < len(sst) else ''
            elif rt == 0x203 and len(body) >= 14:              # NUMBER
                r, c = struct.unpack_from('<HH', body, 0)
                cells[(r, c)] = struct.unpack_from('<d', body, 6)[0]
            elif rt == 0x27E and len(body) >= 10:              # RK
                r, c = struct.unpack_from('<HH', body, 0)
                cells[(r, c)] = rk(struct.unpack_from('<I', body, 6)[0])
            elif rt == 0xBD:                                   # MULRK
                r, c0 = struct.unpack_from('<HH', body, 0)
                n = (len(body) - 6) // 6
                for k in range(n):
                    cells[(r, c0 + k)] = rk(struct.unpack_from('<I', body, 4 + k * 6 + 2)[0])
            elif rt == 0x204 and len(body) >= 9:               # LABEL
                r, c = struct.unpack_from('<HH', body, 0)
                cch, flags = struct.unpack_from('<H', body, 6)[0], body[8]
                cells[(r, c)] = body[9:9 + cch * 2].decode('utf-16le', 'ignore') if flags & 1 else body[9:9 + cch].decode('latin-1')
            elif rt == 0x06 and len(body) >= 14:               # FORMULA
                r, c = struct.unpack_from('<HH', body, 0)
                res = body[6:14]
                if res[6:8] == b'\xff\xff':
                    if res[0] == 0:
                        pending = (r, c)
                    elif res[0] == 1:
                        cells[(r, c)] = bool(res[2])
                else:
                    cells[(r, c)] = struct.unpack('<d', res)[0]
            elif rt == 0x207 and pending:                      # STRING (результат формулы)
                cch, flags = struct.unpack_from('<H', body, 0)[0], body[2]
                cells[pending] = body[3:3 + cch * 2].decode('utf-16le', 'ignore') if flags & 1 else body[3:3 + cch].decode('latin-1')
                pending = None
        if cells:
            nr = max(r for r, _ in cells) + 1
            nc = max(c for _, c in cells) + 1
            rows = [[None] * nc for _ in range(nr)]
            for (r, c), v in cells.items():
                rows[r][c] = v
            out[name] = rows
        else:
            out[name] = []
    return out



# ============================================================
# РЕЕСТР ОПАиЗ (бывшая Google-таблица)
# ============================================================
# Таблицы хранятся в папке «Панель\ОПАиЗ» в json — по файлу на таблицу. Каждая строка имеет версию:
# если двое правят одну строку, второй получит предупреждение, а не затрёт чужое.
# «Электронные заявки» связываются с реестром ОАО по номеру заявки 1С (= номер ОАО) и НМЦК:
# публикация, даты, ответственный в ОАО, договор и статус подтягиваются сами.

def to_iso(v):
    """Любая дата → ГГГГ-ММ-ДД (None, если даты нет): ISO как есть, остальное — разбором текста ячейки."""
    if isinstance(v, str):
        m = re.fullmatch(r'\s*(\d{4}-\d\d-\d\d)(?:[T ][\d:.]*)?\s*', v)
        if m:
            return m.group(1)
    return _to_iso_text(v)


