def oz_can(user):
    return bool(user) and (user.get('admin') or user.get('dept') == 'ОПАиЗ')


def _oz_path(name):
    return ПАПКА_ПАНЕЛИ / OZ_DIR / f'{name}.json'


def oz_load(table):
    return _json_file(f'{OZ_DIR}/{table}.json', {'seq': 0, 'rows': []})


def oz_save_table(table, data):
    _oz_path(table).parent.mkdir(parents=True, exist_ok=True)
    write_atomic(_oz_path(table), json.dumps(data, ensure_ascii=False, indent=0, default=str))


def oz_lists():
    saved = _json_file(f'{OZ_DIR}/списки.json', {})
    out = {}
    for k, v in OZ_LISTS_DEFAULT.items():
        out[k] = saved.get(k, v)
    for k, v in saved.items():
        out.setdefault(k, v)
    return out


def oz_save_lists(lists, actor=None):
    cur = oz_lists()
    for k, v in (lists or {}).items():
        if k in cur:
            seen, vals = set(), []
            for x in v:
                x = str(x or '').strip()
                if x and x.lower() not in seen:
                    seen.add(x.lower())
                    vals.append(x)
            cur[k] = vals
    _oz_path('списки').parent.mkdir(parents=True, exist_ok=True)
    write_atomic(_oz_path('списки'), json.dumps(cur, ensure_ascii=False, indent=1))
    if actor:
        log('edit', 'ОПАиЗ: справочники изменены', user=actor.get('fio') or 'панель')
    return cur


def _learn_lists(table, values):
    """Новое значение в колонке со справочником — добавляется в справочник само. Инициатор → его подразделение
    запоминается («Иванов И.И.» → «Лаборатория № 1»), чтобы в следующий раз подставиться."""
    lists, changed = oz_lists(), False
    for c in OZ_TABLES[table]['cols']:
        if c.get('ty') == 'list' and c.get('l') in ('org', 'initiator', 'dept', 'grant', 'program', 'kosgu', 'fin', 'period', 'priority', 'prorector'):
            v = str(values.get(c['k']) or '').strip()
            if v and v.lower() not in {x.lower() for x in lists[c['l']]}:
                lists[c['l']].append(v)
                changed = True
        if c.get('ty') == 'multi' and c.get('l') in lists:
            for v in re.split(r'\s*,\s*', str(values.get(c['k']) or '')):
                if v and v.lower() not in {x.lower() for x in lists[c['l']]}:
                    lists[c['l']].append(v)
                    changed = True
        if c.get('ty') == 'initiators':
            for v in values.get(c['k']) or []:
                if v and v.lower() not in {x.lower() for x in lists['initiator']}:
                    lists['initiator'].append(v)
                    changed = True
    if changed:
        oz_save_lists(lists)
    inits = [v for c in OZ_TABLES[table]['cols'] if c.get('ty') == 'initiators' for v in (values.get(c['k']) or [])]
    dept = str(values.get('dept') or '').strip()
    if dept and len(inits) == 1:
        m = oz_init_depts()
        if m.get(inits[0]) != dept:
            m[inits[0]] = dept
            write_atomic(_oz_path('инициаторы'), json.dumps(m, ensure_ascii=False, indent=1))


def oz_init_depts():
    """{инициатор: подразделение}."""
    return _json_file(f'{OZ_DIR}/инициаторы.json', {})


def term_end(term, base):
    """«до 31.12.2026», «в течение 3 месяцев», «30 рабочих дней», «60 календарных дней» → дата (ISO) или ''."""
    t = str(term or '').lower().strip()
    if not t:
        return ''
    d = to_iso(t)
    if d and re.search(r'\d{1,2}\.\d{1,2}\.\d{2,4}|\d{1,2}\s+[а-яё]+\s+\d{4}', t):
        return d
    if not base:
        return ''
    b = date.fromisoformat(base)
    m = re.search(r'(\d+)\s*(?:\(\D*\)\s*)?(мес)', t)
    if m:
        mo = b.month - 1 + int(m.group(1))
        y, mo = b.year + mo // 12, mo % 12 + 1
        import calendar
        return date(y, mo, min(b.day, calendar.monthrange(y, mo)[1])).isoformat()
    m = re.search(r'(\d+)\s*(?:\(\D*\)\s*)?раб', t)
    if m:
        return add_workdays(b, int(m.group(1))).isoformat()
    m = re.search(r'(\d+)\s*(?:\(\D*\)\s*)?(?:кал|дн|день)', t)
    if m:
        return (b + timedelta(days=int(m.group(1)))).isoformat()
    return ''


def oz_calc(table, row, ctx=None):
    """Расчётные колонки — считаются сами."""
    if table == 'zayavki':
        row['end'] = term_end(row.get('term'), row.get('cdate'))
        row['pay'] = add_workdays(date.fromisoformat(row['end']), 7).isoformat() if row.get('end') else ''
    elif table == 'ep':
        row['end'] = term_end(row.get('term'), row.get('cdate'))
        nums = (ctx or {}).get('ds_nums')
        if nums is None:
            nums = {nkey(r.get('cnum')) for r in oz_load('ds')['rows'] if r.get('cnum')}
        row['has_ds'] = ('Да' if nkey(row.get('cnum')) in nums else 'Нет') if row.get('cnum') else ''
    elif table == 'invoices':
        s, p = row.get('sum'), row.get('paid')
        row['rest'] = round(float(s) - float(p or 0), 2) if isinstance(s, (int, float)) else ''
        d0 = str(row.get('date_oao') or '')
        row['oklong'] = workdays_between(date.fromisoformat(d0), date.today()) if re.fullmatch(r'\d{4}-\d\d-\d\d', d0) else ''
    elif table == 'kp':
        # «№ входящий» = № строки/месяц-год. Ставится, когда внесли цену КП (значит, КП пришло).
        if isinstance(row.get('price'), (int, float)) and row.get('price') and not row.get('inno'):
            if not row.get('received'):
                row['received'] = date.today().isoformat()
            d = str(row.get('received'))
            row['inno'] = f"{row.get('n') or '?'}/{d[5:7]}-{d[:4]}" if re.fullmatch(r'\d{4}-\d\d-\d\d', d) else f"{row.get('n') or '?'}/{date.today():%m-%Y}"
    elif table == 'sz':
        ex = []
        for it in row.get('items') or []:
            if it.get('resp') and it['resp'] not in ex:
                ex.append(it['resp'])
        row['resps'] = ', '.join(ex) if ex else (row.get('resp') or '')
        done = str(row.get('done') or '')
        if re.search(r'отклон', done, re.IGNORECASE):
            row['st'], row['done'] = 'отклонена', ''
        elif row.get('done') and row.get('st') != 'отклонена':
            row['st'] = 'исполнена'
        elif not row.get('st'):
            row['st'] = 'в работе'
    if table in ('ep', 'invoices'):
        pct = re.search(r'(\d+(?:[.,]\d+)?)\s*%', str(row.get('advance') or ''))
        base = row.get('sum')
        row['advance_sum'] = round(float(base) * float(pct.group(1).replace(',', '.')) / 100, 2) if pct and isinstance(base, (int, float)) else ''
    if table == 'ep':
        row['approval'] = ''
        if row.get('oao_date') and re.fullmatch(r'\d{4}-\d\d-\d\d', str(row['oao_date'])):
            a = date.fromisoformat(row['oao_date'])
            if row.get('cdate') and re.fullmatch(r'\d{4}-\d\d-\d\d', str(row['cdate'])):
                row['approval'] = f"подписан за {workdays_between(a, date.fromisoformat(row['cdate']))} раб. дн."
            else:
                n = workdays_between(a, date.today())
                row['approval'] = f"на согласовании {n} раб. дн." + (' — проверить статус' if n > ДОГОВОР_СОГЛАСОВАНИЕ_РАБ_ДНЕЙ else '')
    if table in ('zayavki', 'ep'):
        row['rt_where'], row['rt_days'], row['rt_stage'] = route_where(row, table)
    if table == 'zayavki':
        st, d0 = row.get('do_stage') or '', str(row.get('do_since') or '')
        n = workdays_between(date.fromisoformat(d0), date.today()) if re.fullmatch(r'\d{4}-\d\d-\d\d', d0) else None
        row['do_days'] = n if st and st != 'подписано' else ''
        row['do_view'] = ' · '.join(x for x in (st, row.get('do_who') or '', (f"с {d0[8:10]}.{d0[5:7]}" + (f" ({n} раб. дн.)" if n is not None and st != 'подписано' else '')) if d0 else '') if x)
    if table in ('zayavki', 'ep') and ctx is not None and 'ovrk' in ctx:
        amount = row.get('csum') if table == 'zayavki' else row.get('sum')
        row['ovrk_paid'] = row['ovrk_pct'] = ''
        if isinstance(amount, (int, float)) and amount > ОВРК_ПОРОГ_ИСПОЛНЕНИЯ and row.get('cnum'):
            hit = ovrk_find(ctx['ovrk'], row.get('cnum'), row.get('cdate'))
            if hit is None:
                row['ovrk_paid'] = 'нет в реестре ОВРК'
            else:
                row['ovrk_paid'] = hit
                row['ovrk_pct'] = f"{min(999, round(hit * 100 / amount)):.0f}%"
    if 'ex_ontime' in {c['k'] for c in OZ_TABLES[table]['cols']}:
        end, fact = str(row.get('end') or ''), str(row.get('ex_delivery') or '')
        full = 'полностью' in str(row.get('ex_status') or '')
        if end and fact:
            late = (date.fromisoformat(fact) - date.fromisoformat(end)).days if re.fullmatch(r'\d{4}-\d\d-\d\d', fact) else 0
            row['ex_ontime'] = 'да' if late <= 0 else f'нет, просрочка {late} дн.'
        elif end and not full and end < date.today().isoformat() and (row.get('cdate') or table != 'zayavki'):
            row['ex_ontime'] = 'просрочена'
        else:
            row['ex_ontime'] = ''
    return row


def _coerce_oz(col, v):
    ty = col.get('ty', 'text')
    if v is None:
        return ''
    if ty == 'money' or ty == 'num':
        if v == '':
            return ''
        return v if isinstance(v, (int, float)) else (parse_price(v) if parse_price(v) is not None else str(v).strip())
    if ty == 'date':
        if not v:
            return ''
        return to_iso(v) or str(v).strip()
    if ty in ('staff', 'oao_staff'):
        return fio_initials(v) if re.match(r'\s*[А-ЯЁа-яё]', str(v)) and len(str(v)) < 60 else str(v).strip()
    if ty == 'route':
        if isinstance(v, (datetime, date)):
            return iso_to_ru(to_iso(v))
        return re.sub(r'\s+', ' ', str(v)).strip()
    if ty == 'multi':
        vals = v if isinstance(v, list) else re.split(r'\s*[,;\n]\s*', str(v))
        out = []
        for x in vals:
            x = str(x or '').strip()
            if x and x not in out:
                out.append(x)
        return ', '.join(out)
    if ty in ('initiators', 'sz_links'):
        vals = v if isinstance(v, list) else re.split(r'\s*[,;\n]\s*', str(v))
        out = []
        for x in vals:
            x = str(x or '').strip()
            if ty == 'initiators' and re.match(r'[А-ЯЁ][а-яё\-]+\s+[А-ЯЁ]', x):
                x = fio_initials(x) or x
            if x and x not in out:
                out.append(x)
        return out
    if ty == 'items':
        return [_clean_item(x) for x in (v or []) if isinstance(x, dict) and str(x.get('name') or '').strip()][:2000]
    return str(v).strip()


def _hv(v):
    """Значение для истории: списки — коротко."""
    if isinstance(v, list):
        if v and isinstance(v[0], dict):
            return f'{len(v)} поз.'
        return ', '.join(map(str, v))
    return v


def _clean_item(x):
    it = {k: x.get(k, '') for k in ITEM_FIELDS}
    it['name'] = re.sub(r'\s+', ' ', str(it['name'])).strip()[:500]
    for k in ('qty', 'price', 'sum'):
        v = it[k]
        it[k] = v if isinstance(v, (int, float)) else (parse_price(v) if str(v).strip() and parse_price(v) is not None else '')
    if it['sum'] == '' and isinstance(it['qty'], (int, float)) and isinstance(it['price'], (int, float)):
        it['sum'] = round(it['qty'] * it['price'], 2)
    it['rf'] = bool(x.get('rf'))
    for k in ('okpd', 'unit', 'nr', 'src', 'smp', 'restr', 'cat', 'resp'):
        it[k] = str(it[k] or '').strip()[:300]
    if it['resp']:
        it['resp'] = fio_initials(it['resp'])
    return it


def _name_tokens(s):
    return {w for w in re.findall(r'[а-яёa-z0-9]{3,}', str(s or '').lower()) if w not in ('для', 'нужд', 'поставка', 'шт', 'или')}


def oz_sz_from_text(text):
    """«246 от 01.07.2025, 165 от 07.05.2025» → id служебных записок с такими номерами (и датами, если указаны)."""
    out = []
    for m in re.finditer(r'(\d+(?:/[\d\-]+)?)\s*(?:от\s*(\d{1,2}\.\d{1,2}\.\d{2,4}))?', str(text or '')):
        num, d = m.group(1), m.group(2)
        for r in oz_load('sz')['rows']:
            t = str(r.get('sz') or '')
            mm = re.search(r'(\d+(?:/[\d\-]+)?)\s*(?:от\s*(\d{1,2}\.\d{1,2}\.\d{2,4}))?', t)
            if mm and mm.group(1) == num and (not d or not mm.group(2) or to_iso(d) == to_iso(mm.group(2))) and r['id'] not in out:
                out.append(r['id'])
    return out


def oz_link_items(row, sz_rows=None):
    """Позиции строки, у которых не указан источник, сопоставляются с позициями связанных СЗ по названию."""
    links = row.get('sz_links') or []
    if not links or not row.get('items'):
        return
    sz_rows = sz_rows if sz_rows is not None else {r['id']: r for r in oz_load('sz')['rows']}
    pool = [(sid, i, _name_tokens(it.get('name'))) for sid in links if sid in sz_rows
            for i, it in enumerate(sz_rows[sid].get('items') or [])]
    for it in row['items']:
        if it.get('src') or not pool:
            continue
        mine = _name_tokens(it.get('name'))
        best, score = None, 0.0
        for sid, i, toks in pool:
            if mine and toks:
                sc = len(mine & toks) / len(mine | toks)
                if sc > score:
                    best, score = f'{sid}#{i}', sc
        if best and score >= 0.34:
            it['src'] = best
        elif len(pool) == 1:
            it['src'] = f'{pool[0][0]}#{pool[0][1]}'


def oz_save_row(table, row_id, values, ver, actor, auto=False, note='', system=False):
    """Создать (row_id пустой) или изменить строку. ver — версия, с которой правили: если строку уже
    поменял кто-то другой, — отказ (кроме автоматического заполнения)."""
    if table not in OZ_TABLES:
        raise ValueError('Нет такой таблицы')
    cols = {c['k']: c for c in OZ_TABLES[table]['cols']}
    who = (actor or {}).get('fio') or 'панель'
    with OZ_LOCK:
        data = oz_load(table)
        if row_id:
            row = next((r for r in data['rows'] if r['id'] == row_id), None)
            if not row:
                raise ValueError('Строку уже удалили')
            if not auto and ver is not None and int(ver) != row.get('_ver', 0):
                raise ValueError(f"Эту строку только что изменил(а) {row.get('_by', 'кто-то')} — откройте её заново")
        else:
            data['seq'] = data.get('seq', 0) + 1
            row = {'id': f"{table[:2]}{data['seq']}", '_ver': 0, '_auto': [], '_hist': [], '_created': datetime.now().isoformat(timespec='seconds')}
            if 'n' in cols:   # № п/п — сам, следующий по порядку
                row['n'] = max([r.get('n') for r in data['rows'] if isinstance(r.get('n'), (int, float))] or [0]) + 1
            data['rows'].append(row)
        changes = []
        for k, v in (values or {}).items():
            if k not in cols or cols[k].get('ty') == 'calc' or (cols[k].get('ty') == 'ro' and not (auto or system)):
                continue
            if cols[k].get('boss') and not (auto or system) and not oz_is_boss(actor):
                if str(_coerce_oz(cols[k], v)) != str(row.get(k, '')):
                    raise ValueError(f"«{cols[k]['t']}» ставит начальник отдела")
                continue
            nv = _coerce_oz(cols[k], v)
            if k == 'status' and nv and nv not in {s[0] for s in OZ_STATUSES}:
                nv = next((s[0] for s in OZ_STATUSES if s[1] == nv), '')
            ov = row.get(k, '')
            if str(nv) != str(ov):
                changes.append({'k': k, 'old': ov, 'new': nv})
                row[k] = nv
                if auto:
                    if k not in row['_auto']:
                        row['_auto'].append(k)
                elif k in row['_auto']:
                    row['_auto'].remove(k)        # поправили руками — больше сами не трогаем
        if not changes and row_id:
            return row, []
        if any(c['k'] == 'do_stage' for c in changes) and not any(c['k'] == 'do_since' for c in changes) and 'do_since' in cols:
            row['do_since'] = date.today().isoformat()     # сменили этап — «на этапе с» сегодня
        if 'sz_links' in cols and row.get('sz') and not row.get('sz_links'):
            row['sz_links'] = oz_sz_from_text(row['sz'])
        if 'items' in cols and row.get('items'):
            oz_link_items(row)
        oz_calc(table, row)
        row['_ver'] = row.get('_ver', 0) + 1
        row['_by'], row['_at'] = who, datetime.now().isoformat(timespec='seconds')
        row['_hist'] = (row.get('_hist') or [])[-40:] + [{'at': row['_at'], 'by': who, 'note': note,
                                                          'ch': [{'t': cols[c['k']]['t'], 'old': _hv(c['old']), 'new': _hv(c['new'])} for c in changes][:30]}]
        oz_save_table(table, data)
    if not auto:
        _learn_lists(table, row)
        if table == 'ds':
            oz_recalc('ep')
    return row, changes


def _route_dates(v):
    return [to_iso(m) for m in re.findall(r'\d{1,2}\.\d{1,2}\.\d{2,4}', str(v or '')) if to_iso(m)]


def route_where(row, table):
    """Где сейчас документация: последний этап с датой передачи; если по нему нет возврата — «сейчас там N раб. дн.»."""
    if table == 'zayavki' and (row.get('pub') or row.get('notice')):
        return ('опубликована', '', '') if any(row.get(k) for k, _ in ROUTE_STAGES) else ('', '', '')
    if table == 'ep' and row.get('cdate'):
        return ('договор подписан', '', '') if any(row.get(k) for k, _ in ROUTE_STAGES) else ('', '', '')
    last = None
    for k, t in ROUTE_STAGES:
        d = _route_dates(row.get(k))
        if d:
            last = (k, t, d)
    if not last:
        return '', '', ''
    k, t, d = last
    today = date.today()
    if k == 'rt_pub':
        n = workdays_between(date.fromisoformat(d[0]), today)
        return f'вернулась, на публикации с {iso_to_ru(d[0])[:5]} ({n} раб. дн.)', n, k
    if len(d) >= 2:
        nxt = next((tt for kk, tt in ROUTE_STAGES[[x for x, _ in ROUTE_STAGES].index(k) + 1:]), 'следующий этап')
        n = workdays_between(date.fromisoformat(d[-1]), today)
        return f'{t}: возвращена {iso_to_ru(d[-1])[:5]} → {nxt.lower()}', n, k
    n = workdays_between(date.fromisoformat(d[0]), today)
    return f'сейчас: {t} с {iso_to_ru(d[0])[:5]} ({n} раб. дн.)', n, k


def oz_route_import(raw, name=''):
    """Таблица ОАО с маршрутом согласования → предложения для строк ОПАиЗ. Ничего не пишет: сначала проверка в панели."""
    if str(name).lower().endswith('.xls'):
        sheets = xls_sheets(raw)
    else:
        wb = load_workbook(io.BytesIO(raw), data_only=True, read_only=True)
        sheets = {ws.title: [list(r) for r in ws.iter_rows(values_only=True)] for ws in wb.worksheets}
    Z, EP = oz_load('zayavki')['rows'], oz_load('ep')['rows']
    out = []
    for title, rows in sheets.items():
        if not rows:
            continue
        hi = next((i for i, r in enumerate(rows[:6]) if sum(1 for x in r if x not in (None, '')) >= 4), 0)
        head = [re.sub(r'\s+', ' ', str(x or '')).strip().lower() for x in rows[hi]]
        col = lambda *w, ex=(): next((i for i, h in enumerate(head) if all(x in h for x in w) and not any(e in h for e in ex)), None)
        C = {'oao': col('№ оао') if col('№ оао') is not None else col('оао', ex=('ответствен', 'передач')), 'date': col('дата', ex=('передач', 'договор', 'публикац', 'заявк', 'дс')),
             'n1c': col('1с'), 'subject': col('предмет') if col('предмет') is not None else col('наименован'), 'sum': col('сумма') if col('сумма') is not None else col('нмцк'),
             'org': col('организац'), 'resp': col('исполнитель'), 'rt_peo': col('пэо'), 'rt_223': col('ответственному в оао') if col('ответственному в оао') is not None else col('223'),
             'rt_law': col('юр'), 'rt_buh': col('бухгалтер'), 'rt_prr': col('проректор', 'передач'), 'rt_pub': col('публикац'), 'rt_note': col('замечан') if col('замечан') is not None else col('примечан')}
        if C['rt_223'] is None and C['rt_law'] is None:
            continue
        is_ep = 'еп' in title.lower() or 'единств' in title.lower() or C['n1c'] is None
        if is_ep:
            continue      # ЕП — отдельный блок, пока не трогаем
        for r in rows[hi + 1:]:
            g = lambda k: r[C[k]] if C.get(k) is not None and C[k] < len(r) else None
            if not any(x not in (None, '') for x in r) or not (g('oao') or g('n1c') or g('subject')):
                continue
            vals = {}
            reg = ' '.join(x for x in (f"№ {g('oao')}" if g('oao') not in (None, '') else '', iso_to_ru(to_iso(g('date'))) if to_iso(g('date')) else '') if x)
            if reg:
                vals['rt_reg'] = reg
            for k in ('rt_peo', 'rt_223', 'rt_law', 'rt_buh', 'rt_prr', 'rt_pub', 'rt_note'):
                v = g(k)
                if v not in (None, ''):
                    vals[k] = _coerce_oz({'ty': 'route'}, v) if k != 'rt_note' else str(v).strip()
            src = {'sheet': title, 'oao': str(g('oao') or '').strip(), 'n1c': re.sub(r'\.0$', '', str(g('n1c') or '').strip()), 'subject': str(g('subject') or '').strip()[:200],
                   'sum': g('sum') if isinstance(g('sum'), (int, float)) else parse_price(g('sum') or '') if g('sum') else None, 'org': str(g('org') or '').strip()}
            table = 'ep' if is_ep else 'zayavki'
            pool = EP if is_ep else Z
            hit = None
            if not is_ep and src['n1c']:
                hit = next((x for x in pool if str(x.get('n1c') or '').strip() == src['n1c']), None)
            if is_ep and src['oao']:
                hit = next((x for x in pool if re.sub(r'\D', '', str(x.get('oao_no') or '')) == re.sub(r'\D', '', src['oao']) and src['oao']), None)
            if hit is None and src['subject']:
                toks = _name_tokens(src['subject'])
                best = max(pool, key=lambda x: len(toks & _name_tokens(x.get('name') or x.get('subject'))) - (0 if not src['sum'] else abs((x.get('nmck') or x.get('sum') or 0) - src['sum']) / max(src['sum'], 1)), default=None)
                if best and len(toks & _name_tokens(best.get('name') or best.get('subject'))) >= 2:
                    hit = best
                    src['guess'] = True
            changes = []
            if hit:
                for k, v in vals.items():
                    if str(hit.get(k) or '') != str(v):
                        changes.append({'k': k, 'old': hit.get(k) or '', 'new': v})
            out.append({'table': table, 'id': hit['id'] if hit else '', 'label': (ozNo_py(table, hit) if hit else ''), 'src': src, 'values': vals,
                        'changes': changes, 'state': 'нет в реестре ОПАиЗ' if not hit else ('без изменений' if not changes else ('подобрано по названию — проверьте' if src.get('guess') else 'изменится'))})
    return out


def need_items(name, raw):
    """Файл потребности к СЗ: каждый лист — категория (расходка, оборудование, реагенты…). Категория позиции = имя листа."""
    if str(name).lower().endswith('.xls'):
        sheets = xls_sheets(raw)
    else:
        wb = load_workbook(io.BytesIO(raw), data_only=True, read_only=True)
        sheets = {ws.title: [list(r) for r in ws.iter_rows(values_only=True)] for ws in wb.worksheets}
    out = []
    for title, rows in sheets.items():
        hi = next((i for i, r in enumerate(rows[:15]) if any('наимен' in str(x or '').lower() for x in r)), None)
        if hi is None:
            continue
        head = [re.sub(r'\s+', ' ', str(x or '')).strip().lower() for x in rows[hi]]
        col = lambda *w, ex=(): next((i for i, h in enumerate(head) if any(x in h for x in w) and not any(e in h for e in ex)), None)
        C = {'name': col('наимен'), 'qty': col('кол-во', 'количеств', ex=('упак',)), 'unit': col('ед. изм', 'ед.изм', 'единиц'), 'price': col('цена'),
             'sum': col('сумм', 'стоимост'), 'okpd': col('окпд')}
        cat = re.sub(r'\s+', ' ', str(title)).strip().lower()
        for r in rows[hi + 1:]:
            g = lambda k: r[C[k]] if C.get(k) is not None and C[k] < len(r) else None
            nm = str(g('name') or '').strip()
            if not nm or nm.lower().startswith(('итого', 'всего')):
                continue
            out.append(_clean_item({'name': nm, 'qty': g('qty'), 'unit': g('unit') or '', 'price': g('price'), 'sum': g('sum'), 'okpd': g('okpd') or '', 'cat': cat}))
    return out


def ozNo_py(t, r):
    if not r:
        return ''
    if t == 'zayavki':
        return f"1С {r.get('n1c')}" if r.get('n1c') else (r.get('notice') or r['id'])
    return f"дог. {r.get('cnum')}" if r.get('cnum') else f"ЕП № ОАО {r.get('oao_no') or '—'}"


def oz_is_boss(actor):
    if not ОПАиЗ_НАЧАЛЬНИК or not ВХОД_ПО_ПАРОЛЮ:
        return True
    a = actor or {}
    return bool(a.get('admin')) or fio_initials(a.get('fio') or '') == fio_initials(ОПАиЗ_НАЧАЛЬНИК)


def ovrk_exec_index():
    """Договоры ОВРК → оплачено по ПП. Ключ — номер договора (без «от …») и дата."""
    out = {}
    try:
        rows = ovrk_all()[0]['rows']
    except Exception:
        return out
    for c in rows:
        num, d = _cnum_split(c.get('cnum'))
        if num:
            out.setdefault(num, []).append((d, c.get('pp_total') or 0))
    return out


def _cnum_split(v):
    s = str(v or '').strip()
    m = re.match(r'(.*?)\s+от\s+(\d{1,2}\.\d{1,2}\.\d{2,4})', s)
    num, d = (m.group(1), to_iso(m.group(2))) if m else (s, '')
    return nkey(num.replace('№', '')), d or ''


def ovrk_find(idx, cnum, cdate):
    num, d = _cnum_split(cnum)
    d = d or (str(cdate) if cdate else '')
    cands = idx.get(num) or []
    if not cands:
        return None
    exact = [x for x in cands if not d or not x[0] or x[0] == d]
    return round(sum(x[1] for x in (exact or cands)), 2)


def spec_items_kv(name, raw):
    """Обоснование к счёту (и похожие документы) — таблица «вопрос | ответ»: «Предмет договора», «Код ОКПД 2», «Сроки оплаты»…
    Позиций нет, есть предмет и один или несколько кодов ОКПД2 → одна «позиция» на каждый код."""
    spec_items_kv.last_kind = ''
    if not str(name).lower().endswith('.docx'):
        return []
    try:
        doc = Document(io.BytesIO(raw))
    except Exception:
        return []
    kv = {}
    for t in doc.tables:
        for r in t.rows:
            cells = [c.text.strip() for c in r.cells]
            if len(cells) >= 2 and cells[0]:
                k = re.sub(r'\s+', ' ', cells[0]).lower()
                v = next((x for x in cells[1:] if x and x != cells[0]), '')
                kv.setdefault(k, v)
    code_txt = ' '.join(v for k, v in kv.items() if 'окпд' in k)
    codes = []
    for m in re.finditer(r'\b\d{2}\.\d{2}(?:\.\d{1,2}){0,2}(?:\.\d{3})?\b', code_txt):
        if m.group(0) not in codes:
            codes.append(m.group(0))
    if not codes:
        return []
    subj = next((v for k, v in kv.items() if 'предмет' in k or 'наименование' in k), '') or 'предмет не указан'
    subj = re.sub(r'\s+', ' ', subj).strip()[:300]
    head = ' '.join(p.text for p in doc.paragraphs[:5]).lower()
    if 'обоснован' in head:
        spec_items_kv.last_kind = 'обоснование'
    return [{'name': subj + (f' (код {c})' if len(codes) > 1 else ''), 'okpd': c, 'qty': '', 'unit': '', 'price': '', 'sum': ''} for c in codes]


def oz_delete_row(table, row_id, actor):
    with OZ_LOCK:
        data = oz_load(table)
        row = next((r for r in data['rows'] if r['id'] == row_id), None)
        if not row:
            return
        data['rows'] = [r for r in data['rows'] if r['id'] != row_id]
        data.setdefault('deleted', []).append(dict(row, _deleted_by=(actor or {}).get('fio'), _deleted_at=datetime.now().isoformat(timespec='seconds')))
        data['deleted'] = data['deleted'][-200:]
        oz_save_table(table, data)
    log('edit', f"ОПАиЗ, «{OZ_TABLES[table]['title']}»: строка удалена", user=(actor or {}).get('fio') or 'панель')


def oz_recalc(table):
    with OZ_LOCK:
        data = oz_load(table)
        ctx = {'ds_nums': {nkey(r.get('cnum')) for r in oz_load('ds')['rows'] if r.get('cnum')}} if table == 'ep' else None
        for r in data['rows']:
            oz_calc(table, r, ctx)
        oz_save_table(table, data)


OZ_SYNC = {'sig': None}


def _contract_parts(text):
    m = re.match(r'\s*(?:№\s*)?(.*?)\s+от\s+(\d{1,2}\.\d{1,2}\.\d{2,4})', str(text or ''))
    return (m.group(1).strip(), to_iso(m.group(2))) if m else (str(text or '').strip(), None)


def oz_sync(force=False):
    """Электронные заявки ← реестр ОАО: по номеру заявки 1С (номер ОАО) и году, при нескольких — по НМЦК."""
    sig = (cache.get('mtime'), (_oz_path('zayavki').stat().st_mtime if _oz_path('zayavki').exists() else None))
    if not force and sig == OZ_SYNC['sig']:
        return 0
    index = {}
    for r in cache['rows']:
        m = re.match(r'(\d+)', r.get('oao') or '')
        if m:
            index.setdefault(m.group(1), []).append(r)
    rows = oz_load('zayavki')['rows']
    today = date.today().isoformat()
    n = 0
    for z in rows:
        d = re.match(r'\s*(\d+)', str(z.get('n1c') or ''))
        if not d or d.group(1) not in index:
            continue
        cands = index[d.group(1)]
        if z.get('fy') and str(z['fy']).isdigit():
            same = [c for c in cands if c.get('year') == int(z['fy'])]
            cands = same or cands
        if len(cands) > 1 and z.get('nmck'):
            cands.sort(key=lambda c: abs((c.get('nmck') or 0) - float(z['nmck'] or 0)))
        r = cands[0]
        if z.get('nmck') and r.get('nmck') and abs(r['nmck'] - float(z['nmck'])) > max(1.0, 0.05 * r['nmck']) and len(index[d.group(1)]) > 1:
            continue
        cnum, cdate = _contract_parts(r.get('contract'))
        want = {'notice': r.get('number'), 'pub': r.get('pub'), 'bid': r.get('bid'), 'review': r.get('review'),
                'trade': r.get('trade'), 'result': r.get('result'), 'resp_oao': r.get('responsible'),
                'csum': r.get('price') if r.get('contract_date') else None,
                'supplier': _org_name(r.get('winner')) if r.get('contract_date') else '',
                'cnum': cnum if r.get('contract_date') else '', 'cdate': r.get('contract_date') or cdate or ''}
        vals = {}
        for k, v in want.items():
            if v in (None, ''):
                continue
            if z.get(k) in (None, '') or k in (z.get('_auto') or []):
                if str(_coerce_oz({'ty': 'money' if k == 'csum' else 'date' if k in ('pub', 'bid', 'review', 'trade', 'result', 'cdate') else 'text'}, v)) != str(z.get(k, '')):
                    vals[k] = v
        st = z.get('status') or ''
        target = 'done' if r.get('contract_date') else 'fail' if r.get('status') == 'failed' else \
            'open' if r.get('bid') and r['bid'] <= today else 'pub' if r.get('pub') else ''
        if target and st not in OZ_LOCKED_STATUS and OZ_RANK.get(target, 0) > OZ_RANK.get(st, 0):
            vals['status'] = target
        if not z.get('method') and r.get('abbr'):
            vals['method'] = {'ЗЭА': 'ЗЭА', 'ЗЭК': 'ЗЭК', 'ЗЦП': 'ЗЦП', 'Р': 'редукцион'}.get(r['abbr'].upper(), '')
        if vals:
            oz_save_row('zayavki', z['id'], vals, None, {'fio': 'панель'}, auto=True,
                        note=f"из реестра ОАО: {r.get('oao')} {r.get('number') or ''}".strip())
            n += 1
    OZ_SYNC['sig'] = (cache.get('mtime'), (_oz_path('zayavki').stat().st_mtime if _oz_path('zayavki').exists() else None))
    return n


def oz_sz_label(sid, sz_rows):
    r = sz_rows.get(sid)
    return (r.get('sz') or sid) if r else sid


def oz_xlsx(table, ids=None):
    t = OZ_TABLES[table]
    sz_rows = {r['id']: r for r in oz_load('sz')['rows']}
    wb = Workbook()
    ws = wb.active
    ws.title = t['title'][:31]
    cols = t['cols']
    thin = Side(style='thin', color='CFCDC6')
    st_label = {s[0]: (s[1], s[2]) for s in OZ_STATUSES}
    if any(c.get('g') for c in cols):
        ws.append([c.get('g', '') for c in cols])
        for c in ws[1]:
            c.font = Font(bold=True, color='2A78D6', size=9)
    ws.append([c['t'] for c in cols])
    hr = ws.max_row
    for c in ws[hr]:
        c.font = Font(bold=True)
        c.fill = PatternFill('solid', fgColor='B7E1CD')
        c.alignment = Alignment(wrap_text=True, vertical='center')
        c.border = Border(top=thin, bottom=thin, left=thin, right=thin)
    rows = oz_load(table)['rows']
    if ids:
        order = {i: n for n, i in enumerate(ids)}
        rows = sorted([r for r in rows if r['id'] in order], key=lambda r: order[r['id']])
    for r in rows:
        vals = []
        for c in cols:
            v = r.get(c['k'], '')
            if c.get('ty') == 'status':
                v = st_label.get(v, ('', ''))[0]
            elif c.get('ty') == 'sz_links':
                v = ', '.join(oz_sz_label(x, sz_rows) for x in (v or []))
            elif c.get('ty') == 'items':
                v = '; '.join(f"{it.get('name')}" + (f" × {it['qty']:g}" if isinstance(it.get('qty'), (int, float)) else '') for it in (v or []))[:30000]
            elif isinstance(v, list):
                v = ', '.join(map(str, v))
            elif c.get('ty') in ('date', 'calc') and isinstance(v, str) and re.fullmatch(r'\d{4}-\d\d-\d\d', v):
                v = date.fromisoformat(v)
            vals.append(v)
        ws.append(vals)
        rr = ws.max_row
        color = st_label.get(r.get('status'), (None, None))[1] if t.get('status') else None
        for i, c in enumerate(cols, 1):
            cell = ws.cell(rr, i)
            cell.border = Border(top=thin, bottom=thin, left=thin, right=thin)
            cell.alignment = Alignment(wrap_text=True, vertical='top')
            if c.get('ty') == 'money' or (c.get('ty') == 'calc' and c['k'] == 'rest'):
                cell.number_format = '#,##0.00'
            if isinstance(cell.value, date):
                cell.number_format = 'DD.MM.YYYY'
            if color:
                cell.fill = PatternFill('solid', fgColor=color.lstrip('#'))
    for i, c in enumerate(cols, 1):
        from openpyxl.utils import get_column_letter
        ws.column_dimensions[get_column_letter(i)].width = 40 if c.get('ty') == 'long' else 16
    ws.freeze_panes = ws.cell(hr + 1, 2)
    ws.auto_filter.ref = f"A{hr}:{ws.cell(hr, len(cols)).coordinate}"
    buf = io.BytesIO()
    wb.save(buf)
    return buf.getvalue()


# ---------- документы → строки реестра ОПАиЗ ----------

def _short_fio(full):
    """«Телышев Дмитрий Викторович» → «Телышев Д.В.»; уже короткое — как есть."""
    m = re.search(r'([А-ЯЁ][а-яё\-]+)\s+([А-ЯЁ])[а-яё]+\s+([А-ЯЁ])[а-яё]+', full or '')
    if m:
        return f'{m.group(1)} {m.group(2)}.{m.group(3)}.'
    m = re.search(r'([А-ЯЁ][а-яё\-]+)\s+([А-ЯЁ])\.\s*([А-ЯЁ])\.', full or '')
    if m:
        return f'{m.group(1)} {m.group(2)}.{m.group(3)}.'
    m = re.search(r'([А-ЯЁ])\.\s*([А-ЯЁ])\.\s*([А-ЯЁ][а-яё\-]+)', full or '')
    return f'{m.group(3)} {m.group(1)}.{m.group(2)}.' if m else ''


def _pick(lst, text):
    """Значение справочника, которое встречается в тексте (самое длинное)."""
    low = str(text or '').lower()
    hits = [x for x in lst if x and x.lower() in low]
    return max(hits, key=len) if hits else ''


def _method_from(text):
    t = str(text or '').lower()
    return 'ЗЦП' if 'ценовых предложений' in t or 'зцп' in t else 'редукцион' if 'редукцион' in t else \
        'ЗЭК' if 'конкурс' in t else 'ЗЭА' if 'аукцион' in t else ''


FIO_FULL = r'([А-ЯЁ][а-яё\-]+)\s+([А-ЯЁ][а-яё]+)\s+([А-ЯЁ][а-яё]+(?:вич|вна|чна|ична|ич|оглы|кызы))\b'
POST_RE = r'(?:Директор\w*|Руководител\w*|Заведующ\w*|Начальник\w*|Заместител\w*|Главн\w+|Ведущ\w+|Контактное лицо)'


def initiators_from_text(text):
    """Все ответственные лица из заявки: [(«Фамилия И.О.», подразделение)]."""
    out = []
    for m in re.finditer(FIO_FULL, text or ''):
        fio = f'{m.group(1)} {m.group(2)[0]}.{m.group(3)[0]}.'
        before = text[max(0, m.start() - 220):m.start()]
        dept = ''
        d = re.search(POST_RE + r'(?:\s+по\s+\w+)?\s*[-–—]?\s*(?:' + POST_RE + r'\s+)?(.+?)\s*$', before.split(';')[-1].split('\n')[-1])
        if d:
            dept = re.sub(r'^(?:по\s+\w+\s+)', '', d.group(1)).strip(' ,-–—:')
        if fio not in [x[0] for x in out] and m.group(1).lower() not in ('федеральное',):
            out.append((fio, dept[:120]))
    return out


def clean_subject(name):
    """«Закупка … в электронной форме на поставку X для нужд …» → «Поставка X для нужд …»."""
    t = re.sub(r'\s+', ' ', str(name or '')).strip()
    t = re.sub(r'^Закупка\s+.*?(?:в электронной форме|способом)\s+(?=на\s)', '', t, flags=re.IGNORECASE)
    t = re.sub(r'^на\s+(поставку|оказание|выполнение)\b', lambda m: {'поставку': 'Поставка', 'оказание': 'Оказание', 'выполнение': 'Выполнение'}[m.group(1).lower()], t, flags=re.IGNORECASE)
    t = re.sub(r'\s*(?:с|для|среди)\s+субъект\w* малого и среднего предпринимательства\.?$', '', t, flags=re.IGNORECASE)
    return t[:1].upper() + t[1:] if t else t


def oz_parse_request(rows_by_sheet):
    """Заявка на закупку (.xls/.xlsx): шапка, предмет, сумма, КОСГУ, источник, подразделение, исполнитель."""
    rows = next(iter(rows_by_sheet.values()))
    cells = [[('' if v is None else (v if isinstance(v, (int, float)) and not isinstance(v, bool) else str(v).strip())) for v in r] for r in rows]
    flat = '\n'.join(' | '.join(str(v) for v in r if v not in ('', None)) for r in cells)
    lists = oz_lists()
    vals = {'status': 'work'}
    vals['method'] = _method_from(re.search(r'Заявка на закупку[^\n]*', flat).group(0) if re.search(r'Заявка на закупку[^\n]*', flat) else flat)
    m = re.search(r'Заявка\s*1\s*[СC][\s|:№]*(\d+)', flat)
    if m:
        vals['n1c'] = m.group(1)
    m = re.search(r'Код по ЭК\s*(\d{3})', flat)
    if m:
        vals['kosgu'] = next((x for x in lists['kosgu'] if x.startswith(m.group(1))), m.group(1))
    m = re.search(r'(20\d\d)', re.search(r'Дата составления[^\n]*', flat).group(0)) if re.search(r'Дата составления[^\n]*', flat) else None
    if m:
        vals['fy'] = m.group(1)
    for i, r in enumerate(cells):
        line = [v for v in r if v not in ('', None)]
        if line and str(line[0]).startswith('Предмет закупки') and i + 1 < len(cells):
            nxt = [v for v in cells[i + 1] if v not in ('', None)]
            if nxt:
                vals['name'] = re.sub(r'\s+', ' ', str(nxt[0]))
                num = next((v for v in nxt[1:] if isinstance(v, (int, float)) and not isinstance(v, bool)), None)
                if num:
                    vals['nmck'] = round(float(num), 2)
        if line and str(line[0]).strip() == '№' and any('Источник' in str(v) for v in line):
            hi = [str(v) for v in r]
            src = next((j for j, v in enumerate(hi) if 'Источник' in v), None)
            dep = next((j for j, v in enumerate(hi) if 'Подразделение' in v), None)
            for rr in cells[i + 1:i + 6]:
                if rr and str(rr[0]).replace('.0', '').strip() == '1':
                    if src is not None:
                        f = ' '.join(str(v) for v in rr[src:src + 2] if v not in ('', None))
                        vals['fin'] = _pick(lists['fin'], f) or (f.split()[0] if f and not _pick(lists['program'], f) else '')
                        prog = _pick(lists['program'], f)
                        if prog:
                            vals['program'] = prog
                    if dep is not None:
                        who = ' '.join(str(v) for v in rr[dep:] if v not in ('', None))
                        if who:
                            vals['initiator'] = _short_fio(who)
                            d = re.match(r'\s*(?:Директор\w*|Заведующ\w*|Руководител\w*|Начальник\w*)\s+(.+?)\s+[А-ЯЁ][а-яё\-]+\s+[А-ЯЁ][а-яё]+\s+[А-ЯЁ][а-яё]+', who)
                            if d:
                                vals['dept'] = d.group(1).strip(' ,')
                    break
    m = re.search(r'Исполнитель:\s*([А-ЯЁ][а-яё\-]+\s+[А-ЯЁ]\.\s*[А-ЯЁ]\.)', flat)
    if m:
        vals['resp'] = fio_initials(m.group(1))
    # площадка, предмет без «Закупка … способом», все инициаторы, приоритет, позиции
    m = re.search(r'Площадка\s*[:|]?\s*([^\n|]+)', flat)
    if m:
        vals['platform'] = _pick(lists['platform'], m.group(1)) or m.group(1).strip()
    if vals.get('name'):
        vals['name'] = clean_subject(vals['name'])
    resp_block = '\n'.join(re.findall(r'Ответственные лица:[^\n]*(?:\n[^\n|]*)?', flat)) + '\n' + \
        '\n'.join(str(v) for r in cells for v in r if isinstance(v, str) and re.search(POST_RE, v) and re.search(FIO_FULL, v))
    found = initiators_from_text(resp_block)
    if found:
        vals['initiator'] = [f for f, _ in found]
        if not vals.get('dept') and found[0][1]:
            vals['dept'] = found[0][1]
        vals['_init_depts'] = {f: d for f, d in found if d}
    elif vals.get('initiator'):
        vals['initiator'] = [vals['initiator']]
    m = re.search(r'\b(\d{2}\.\d{3}\.[А-ЯЁA-Z]\.\d{1,3})\s+([А-ЯЁ][а-яё\-]+)?\s*([А-ЯЁ]{2,})?', flat)
    if m:
        vals['priority'] = m.group(1)
        if m.group(3):
            vals['dept'] = m.group(3)
            if m.group(2):
                for f in vals.get('initiator') or []:
                    if f.startswith(m.group(2)):
                        vals.setdefault('_init_depts', {})[f] = m.group(3)
    items = _spec_from_rows(rows)
    if items:
        vals['items'] = items
    if re.search(r'только\s+(?:среди\s+)?(?:субъект|СМП)|Преимуществ\w*[^\n]*СМП\s*[-–—]\s*Требу', flat, re.IGNORECASE):
        vals['smp'] = 'да'
    cond = re.search(r'Условия поставки:([^\n]*)', flat)
    if cond:
        m = re.search(r'не позднее\s*\d{1,2}\.\d{1,2}\.\d{2,4}|в течение[^.\n|]+', cond.group(1))
        if m:
            vals['term'] = m.group(0).strip()
        per = _pick(lists['period'], cond.group(1))
        if per:
            vals['period'] = per
    m = re.search(r'Срок действия договора:[^\n]*?по\s*(\d{1,2}\.\d{1,2}\.\d{4})', flat)
    if m:
        vals['validity'] = to_iso(m.group(1))
    return 'zayavki', {k: v for k, v in vals.items() if v not in ('', None, [])}


def oz_parse_justification(text):
    """Обоснование цены договора с единственным поставщиком (к счёту) → строка «Счета»."""
    lists = oz_lists()
    t = re.sub(r'[ \t]+', ' ', text)
    vals = {}
    m = re.search(r'Характеристики объекта закупки\s*\n\s*(.+)', t)
    if m:
        vals['subject'] = m.group(1).strip()
    m = re.search(r'Расч[её]т цены контракта\s*\n\s*(.+)', t)
    if m:
        line = m.group(1)
        o = re.match(r'\s*(.+?)\s+Сч[её]т', line)
        if o:
            vals['org'] = o.group(1).strip()
        inv = re.search(r'Сч[её]т\s*(№\s*\S+)\s*от\s*(\d{1,2}\s+[а-яё]+\s+\d{4}|\d{1,2}\.\d{1,2}\.\d{2,4})', line, re.IGNORECASE)
        if inv:
            d = to_iso(inv.group(2))
            vals['inv'] = f"{inv.group(1).replace(' ', '')} от {iso_to_ru(d) if d else inv.group(2)}"
        s = re.search(r'на сумму\s*([\d\s]+[,.]\s*\d{2}|[\d\s]+)', line)
        if s:
            vals['sum'] = parse_price(s.group(1).replace(' ', ''))
    pay = re.search(r'Сроки оплаты\s*\n\s*(.+)', t)
    srv = re.search(r'Срок (?:оказания услуг|поставки|выполнения работ)\s*:\s*([^\n]+)', t)
    if pay:
        low = pay.group(1).lower()
        vals['pay_terms'] = ('аванс — 5 рабочих дней' if ('аванс' in low or 'предоплат' in low) and '5' in low else
                             'постоплата — 7 рабочих дней' if 'постоплат' in low and '7' in low else pay.group(1).strip())
    if srv:
        vals['terms'] = srv.group(1).strip()
    m = re.search(r'Ответственный:\s*([А-ЯЁ][а-яё\-]+\s+[А-ЯЁ]\.\s*[А-ЯЁ]\.)', t)
    if m:
        vals['dept_resp'] = fio_initials(m.group(1))
    m = re.search(r'Исполнитель:\s*\n?\s*([А-ЯЁ][а-яё\-]+\s+[А-ЯЁ]\.\s*[А-ЯЁ]\.)', t)
    if m:
        vals['resp'] = fio_initials(m.group(1))
    m = re.search(r'Обоснование способа закупки\s*\n.*\n\s*([^\n]{2,60})\n', t)
    if m and not re.search(r'метод|цены', m.group(1), re.IGNORECASE):
        vals['note'] = 'Источник: ' + m.group(1).strip()
    m = re.search(r'Дата подготовки\s*\n?\s*обоснования[^:]*:\s*(\d{1,2}\.\d{1,2}\.\d{4})', t)
    if m:
        vals['date_oao'] = to_iso(m.group(1))
    vals['fin'] = _pick(lists['fin'], t) if 'доход' not in t.lower() else 'Внебюджет'
    return 'invoices', {k: v for k, v in vals.items() if v not in ('', None)}


def oz_parse_justification_kv(raw, name=''):
    """Обоснование в виде таблицы «вопрос | ответ» (как в отделе): предмет, ОКПД2, сроки оплаты и поставки, расчёт цены."""
    if not str(name).lower().endswith('.docx'):
        return {}
    try:
        doc = Document(io.BytesIO(raw))
    except Exception:
        return {}
    kv = {}
    for t in doc.tables:
        for r in t.rows:
            cells = [c.text.strip() for c in r.cells]
            if len(cells) >= 2 and cells[0]:
                kv.setdefault(re.sub(r'\s+', ' ', cells[0]).lower(), next((x for x in cells[1:] if x and x != cells[0]), ''))
    g = lambda *w: next((v for k, v in kv.items() if all(x in k for x in w) and v), '')
    out = {}
    subj = re.sub(r'\s+', ' ', g('предмет')).strip()
    if subj:
        out['subject'] = subj
    pay = re.sub(r'\s+', ' ', g('сроки оплаты')).strip()
    if pay:
        low = pay.lower()
        out['pay_terms'] = ('аванс — 5 рабочих дней' if ('аванс' in low or 'предоплат' in low) and '5' in low else
                            'постоплата — 7 рабочих дней' if 'постоплат' in low and '7' in low else pay)
    term = re.sub(r'\s+', ' ', g('сроки поставки') or g('срок поставки')).strip()
    if term:
        out['terms'] = term
    calc = g('расчет цены') or g('расчёт цены')
    if calc:
        o = re.match(r'\s*(.+?)\s+Сч[её]т', calc)
        if o:
            out['org'] = o.group(1).strip()
        sm = re.search(r'на сумму\s*([\d\s]+[,.]\s*\d{2}|[\d\s]+)', calc)
        if sm:
            out['sum'] = parse_price(sm.group(1).replace(' ', ''))
    codes = re.findall(r'\b\d{2}\.\d{2}(?:\.\d{1,2}){0,2}(?:\.\d{3})?\b', g('окпд'))
    if codes:
        out['items'] = [_clean_item({'name': subj or 'позиция', 'okpd': c}) for c in dict.fromkeys(codes)]
    return out


def contract_subject(t):
    """Предмет договора: из заголовка («ДОГОВОР на поставку …»), иначе из п. 1.1 («Поставщик обязуется передать … (далее – Товар)»)."""
    m = re.search(r'Д\s*О\s*Г\s*О\s*В\s*О\s*Р\s*\n?\s*(на\s[^\n№]+)', t)
    if m and len(m.group(1).strip()) > 12:
        return clean_subject(m.group(1).strip().rstrip('№').strip())
    m = re.search(r'1\.1\.?\s*(?:Поставщик|Исполнитель|Подрядчик)\s+обязуется\s+(передать|поставить|оказать|выполнить)\s+'
                  r'(?:Заказчику\s+)?(?:на условиях настоящего Договора\s+)?(?:Заказчику\s+)?(.+?)\s*\(\s*далее', t, re.DOTALL)
    if m:
        verb = {'передать': 'Поставка', 'поставить': 'Поставка', 'оказать': 'Оказание услуг', 'выполнить': 'Выполнение работ'}[m.group(1).lower()]
        obj = re.sub(r'\s+', ' ', m.group(2)).strip(' ,')
        obj = re.sub(r'^(?:услуги|работы)\s+', '', obj) if verb != 'Поставка' else obj
        return f'{verb}: {obj}'[:400]
    m = re.search(r'Д\s*О\s*Г\s*О\s*В\s*О\s*Р\s*\n?\s*(поставки|возмездного оказания услуг|подряда)', t)
    return clean_subject(m.group(1)) if m else ''


def oz_parse_contract(text, raw=None, name=''):
    """Договор: если он по закупке из реестра ОАО — дополняет «Электронные заявки», иначе — «Договоры ЕП»."""
    lists = oz_lists()
    c = parse_contract(text)
    r = match_row(c.get('number', ''), c.get('oao', ''))
    t = re.sub(r'[ \t]+', ' ', text)
    subject = contract_subject(t)
    m = re.search(r'на основании\s+(?:пункта|п\.)\s*(\d+(?:\.\d+){1,3})\s+Положения', t)
    clause = m.group(1) if m else ''
    items = spec_items(name or 'договор.docx', raw) if raw and (name or '').lower().endswith('.docx') else []
    signer = ''
    m = re.search(r'в лице\s+([^,]+?)\s+([А-ЯЁ][а-яё\-]+(?:ой|ого|ы|а|я)?\s+[А-ЯЁ][а-яё]+\s+[А-ЯЁ][а-яё]+)', t)
    if m:
        signer = m.group(2)
    sig_short = ''
    m2 = re.findall(r'_{5,}\s*([А-ЯЁ][а-яё\-]+\s+[А-ЯЁ]\.\s*[А-ЯЁ]\.)', t)
    if m2:
        sig_short = fio_initials(m2[-1])          # последний подписант — заказчик
    prorector = sig_short if sig_short in lists['prorector'] else ''
    if not prorector:          # «в лице Первого проректора Свистунова Андрея Алексеевича» → «Свистунов А.А.» по справочнику
        m = re.search(r'в лице\s+(.{0,80}?)\s+' + r'([А-ЯЁ][а-яё\-]+)\s+([А-ЯЁ])[а-яё]+\s+([А-ЯЁ])[а-яё]+', t[:2500])
        if m:
            for p in lists['prorector']:
                sur, ini = p.split()[0], p.split()[-1] if len(p.split()) > 1 else ''
                if m.group(2).startswith(sur[:max(4, len(sur) - 2)]) and ini.startswith(m.group(3)):
                    prorector = p
                    break
    m = re.search(r'Договор заключ[её]н в рамках[^\n]*?,\s*([А-ЯЁ][а-яё\-]+\s+[А-ЯЁ]\.\s*[А-ЯЁ]\.)', t)
    resp_contract = [fio_initials(m.group(1))] if m else []
    m = re.search(r'Ответственн\w+ (?:лиц\w+|за исполнение)[^:\n]*:([^\n]+)', t)
    if m:
        resp_contract += [f for f, _ in initiators_from_text(m.group(1)) if f not in resp_contract]
    agreement = 'Приоритет' if 'приоритет-2030' in t.lower() else 'РНФ' if re.search(r'\bРНФ\b|Российского научного фонда', t) else \
        'Госзадание' if re.search(r'государственного задания', t, re.IGNORECASE) else ''
    fin = 'Внебюджет' if 'внебюджет' in t.lower() else ('Грант' if agreement else '')
    period = 'Партиями' if 'парти' in t.lower() else 'По заявкам' if 'по заявк' in t.lower() else ''
    term = ''
    m = re.search(r'(?:Срок|сроки)\s+(?:поставки|оказания услуг|выполнения работ)[^:\n]*[:\-–]\s*([^\n.;]{3,80})', t)
    if m:
        term = m.group(1).strip()
    validity = ''
    m = re.search(r'действует\s+(?:до|по)\s*(\d{1,2}\.\d{1,2}\.\d{4}|«?\d{1,2}»?\s+[а-яё]+\s+\d{4})', t)
    if m:
        validity = to_iso(m.group(1).replace('«', '').replace('»', ''))
    if r:
        vals = {'n1c': (re.match(r'(\d+)', r.get('oao') or '') or [None, ''])[1], 'cnum': c.get('contract_no', ''),
                'cdate': to_iso(c.get('date')) if c.get('date') else '', 'csum': c.get('price'), 'supplier': c.get('supplier', ''),
                'period': period, 'term': term, 'validity': validity, 'items': items}
        return 'zayavki', {k: v for k, v in vals.items() if v not in ('', None, [])}, r
    vals = {'org': c.get('supplier', ''), 'cnum': c.get('contract_no', ''), 'cdate': to_iso(c.get('date')) if c.get('date') else '',
            'subject': subject, 'sum': c.get('price'), 'prorector': prorector, 'resp_contract': resp_contract,
            'agreement': agreement, 'fin': fin, 'period': period, 'term': term, 'validity': validity,
            'kosgu': '341-лек.средства' if 'лекарствен' in subject.lower() else '', 'clause': clause, 'items': items,
            'oao_date': date.today().isoformat()}
    if c.get('inn'):
        vals['note'] = f"ИНН поставщика {c['inn']}"
    return 'ep', {k: v for k, v in vals.items() if v not in ('', None, [])}, None


def oz_find_match(table, vals):
    rows = oz_load(table)['rows']
    if table == 'zayavki':
        if vals.get('n1c'):
            hit = [r for r in rows if re.match(r'\s*(\d+)', str(r.get('n1c') or '')) and
                   re.match(r'\s*(\d+)', str(r['n1c'])).group(1) == str(vals['n1c'])]
            if hit:
                return hit[0]
        if vals.get('nmck') and vals.get('name'):
            hit = [r for r in rows if r.get('nmck') and abs(float(r['nmck']) - float(vals['nmck'])) < 0.01 and
                   nkey(r.get('name'))[:40] == nkey(vals['name'])[:40]]
            return hit[0] if hit else None
    if table == 'ep' and vals.get('cnum'):
        return next((r for r in rows if nkey(r.get('cnum')) == nkey(vals['cnum']) and nkey(r.get('org')) == nkey(vals.get('org'))), None)
    if table == 'invoices' and vals.get('inv'):
        return next((r for r in rows if nkey(r.get('inv')) == nkey(vals['inv']) and nkey(r.get('org')) == nkey(vals.get('org'))), None)
    return None


# ---------- спецификация: позиции (наименование, ОКПД2, количество…) из договора или заявки ----------

OKPD_RE = re.compile(r'\b(\d{2}\.\d{2}(?:\.\d{1,2})?(?:\.\d{3})?)\b')


def _spec_cols(head):
    """Строка заголовков → {поле: номер колонки} по смыслу заголовка (а не по номеру — шаблоны меняются)."""
    cols = {}
    for i, h in enumerate(head):
        t = re.sub(r'\s+', ' ', str(h or '')).strip().lower()
        if not t:
            continue
        if 'name' not in cols and ('наименование' in t or 'продукци' in t):
            cols['name'] = i
        elif 'okpd' not in cols and ('окпд' in t or t in ('код', 'код окпд2')):
            cols['okpd'] = i
        elif 'nr' not in cols and ('1875' in t or 'нацрежим' in t or 'национальн' in t):
            cols['nr'] = i
        elif 'unit' not in cols and (t.startswith('ед') or 'единица' in t):
            cols['unit'] = i
        elif 'qty' not in cols and ('кол-во' in t or 'количество' in t) and 'упаковк' not in t:
            cols['qty'] = i
        elif 'price' not in cols and 'цена' in t:
            cols['price'] = i
        elif 'sum' not in cols and ('сумма' in t or 'стоимость' in t):
            cols['sum'] = i
    return cols


def _spec_from_rows(rows):
    """rows: [[ячейки]] → позиции. Ищем строку заголовков с «наименование» и «ОКПД»/«код»."""
    for hi, head in enumerate(rows):
        t = ' '.join(str(x or '') for x in head).lower()
        if 'наименование' in t and ('окпд' in t or ' код' in t):
            cols = _spec_cols(head)
            if 'name' not in cols:
                continue
            items = []
            for r in rows[hi + 1:]:
                cell = lambda k: (r[cols[k]] if k in cols and cols[k] < len(r) else '')
                line = ' '.join(str(x or '') for x in r).lower()
                if re.match(r'\s*(итого|всего)', line):
                    break
                name = re.sub(r'\s+', ' ', re.sub(r'^\d+\s*[.)]?\s*', '', str(cell('name') or ''))).strip()
                m = OKPD_RE.search(str(cell('okpd') or '')) if 'okpd' in cols else None
                if not m:
                    m = next((OKPD_RE.search(str(x)) for x in r if OKPD_RE.search(str(x or ''))), None)
                if not name or len(name) < 3 or not m:
                    continue
                num = lambda v: v if isinstance(v, (int, float)) and not isinstance(v, bool) else parse_price(v) if str(v or '').strip() else None
                items.append(_clean_item({'name': name, 'okpd': m.group(1), 'qty': num(cell('qty')), 'unit': str(cell('unit') or ''),
                                          'price': num(cell('price')), 'sum': num(cell('sum')), 'nr': str(cell('nr') or '')}))
            if items:
                return items
    return []


def spec_items(name, raw):
    """Позиции из .docx (таблица спецификации), .xlsx/.xls (заявка)."""
    low = (name or '').lower()
    if low.endswith('.xls'):
        sheets = xls_sheets(raw)
        order = sorted(sheets, key=lambda n: 0 if 'заявк' in n.lower() else 1)
        for sh in order:
            items = _spec_from_rows(sheets[sh])
            if items:
                return items
        return []
    if low.endswith(('.xlsx', '.xlsm')):
        wb = load_workbook(io.BytesIO(raw), data_only=True, read_only=True)
        for ws in sorted(wb.worksheets, key=lambda w: 0 if 'заявк' in w.title.lower() else 1):
            items = _spec_from_rows([list(r) for r in ws.iter_rows(values_only=True)])
            if items:
                return items
        return []
    if low.endswith('.docx') or raw[:4] == b'PK\x03\x04':
        doc = Document(io.BytesIO(raw))
        for t in doc.tables:
            rows = []
            for row in t.rows:
                cells, prev = [], None
                for c in row.cells:            # объединённые ячейки python-docx повторяет — убираем повторы подряд
                    cells.append(c.text.strip() if c._tc is not prev else '')
                    prev = c._tc
                rows.append(cells)
            items = _spec_from_rows(rows)
            if items:
                return items
    return []


def oz_parse_doc(name, raw):
    """Документ, брошенный в реестр ОПАиЗ: заявка (.xls/.xlsx), обоснование к счёту, договор (.docx/.doc/.pdf)."""
    low = (name or '').lower()
    reg = None
    if low.endswith('.xlsx') or (raw[:4] == b'PK\x03\x04' and low.endswith('.xlsm')):
        wb = load_workbook(io.BytesIO(raw), data_only=True, read_only=True)
        sheets = {ws.title: [list(r) for r in ws.iter_rows(values_only=True)] for ws in wb.worksheets}
        table, vals = oz_parse_request(sheets)
        kind = 'заявка на закупку'
    elif low.endswith('.xls'):
        table, vals = oz_parse_request(xls_sheets(raw))
        kind = 'заявка на закупку'
    else:
        text = any_text(raw, name)
        if re.search(r'ОБОСНОВАНИЕ\s*\n?\s*цены договора', text, re.IGNORECASE) or 'единственным поставщиком' in text[:400].lower() or re.search(r'Обоснование способа закупки', text[:300], re.IGNORECASE):
            table, vals = oz_parse_justification(text)
            kvv = oz_parse_justification_kv(raw, name)
            if kvv.get('pay_terms'):           # срок оплаты — отдельно от срока поставки
                vals.pop('terms', None)
            for k, v in kvv.items():
                vals.setdefault(k, v)
            kind = 'обоснование к счёту'
        elif re.search(r'Д\s*О\s*Г\s*О\s*В\s*О\s*Р', text[:3000]):
            table, vals, reg = oz_parse_contract(text, raw, name)
            kind = 'договор'
        else:
            raise ValueError('Не понял, что это за документ: ожидаю заявку (.xls/.xlsx), обоснование к счёту или договор')
    match = oz_find_match(table, vals)
    return {'ok': True, 'kind': kind, 'table': table, 'values': vals, 'match': match,
            'oao': row_brief(reg) if reg else None}





# ============================================================
# ПРОВЕРКА СМП (логика check_smp.py v2 от ИТ + исправления)
# ============================================================
# Позиции (наименование + ОКПД2) из договора / счёта / заявки сверяются:
#  • с «Перечнем СМП» (лист «для работы»: КОД, НАЗВАНИЕ, признак «смп» / «б/о»…);
#  • с «Запрет и ограничение» (листы «Запрет», «Ограничение», код — в 3-й колонке; оговорки «за исключением …»);
#  • для договоров — с кодами, уже использованными по пункту положения (8.1.30) в месяце договора
#    («Прямые договоры ГГГГ.xlsx», лист года, колонки «Пункт положения», «Месяц публикации», «ОКПД 2»).
# Если справочник не прочитался — проверка останавливается, отчёт не создаётся (как в v2).
# Исправлено относительно v2: ОКПД2 в заявке ищется по заголовку колонки (в новом шаблоне это 6-я колонка),
# месяц для п. 8.1.30 — месяц договора, а не текущий; пункт положения в отчёте — из настроек.

ПАПКА_СМП = 'Проверка СМП'                       # внутри папки панели
СМП_ПУНКТ_ПОЛОЖЕНИЯ = '8.1.30'
ФАЙЛ_ПРЯМЫХ_ДОГОВОРОВ = r''                      # путь к «Прямые договоры {год}.xlsx» на сетевом диске; пусто — папка «Проверка СМП»
SMP_YES = {'смп', 'да', 'yes', '1'}
SMP_NO = {'нет', 'б/о', 'бо', 'no', '0', '', 'nan', 'none'}
SMP_REFS = {'smp': 'Перечень СМП.xlsx', 'restr': 'Запрет и ограничение.xlsx', 'direct': 'Прямые договоры {year}.xlsx'}
SMP_REF_TITLES = {'smp': 'Перечень СМП', 'restr': 'Запрет и ограничение', 'direct': 'Прямые договоры'}
_SMP_CACHE = {}
CODE_RE = re.compile(r'\d{2}(?:\.\d{1,3}){0,3}')
CODE_IN_TEXT_RE = re.compile(r'\b(\d{2}\.\d{2}\.\d{2}(?:\.\d{3})?)\b')


def smp_dir():
    return ПАПКА_ПАНЕЛИ / ПАПКА_СМП


def smp_ref_path(kind, year=None):
    if kind == 'direct' and ФАЙЛ_ПРЯМЫХ_ДОГОВОРОВ:
        return Path(ФАЙЛ_ПРЯМЫХ_ДОГОВОРОВ.format(year=year or date.today().year))
    return smp_dir() / SMP_REFS[kind].format(year=year or date.today().year)


def smp_refs_info():
    out = []
    for k in SMP_REFS:
        p = smp_ref_path(k)
        out.append({'kind': k, 'title': SMP_REF_TITLES[k], 'file': p.name, 'exists': p.exists(),
                    'mtime': datetime.fromtimestamp(p.stat().st_mtime).strftime('%d.%m.%Y %H:%M') if p.exists() else ''})
    return out


def _fmt_code(digits):
    n = len(digits)
    if n <= 2:
        return digits
    if n == 3:
        return f'{digits[:2]}.{digits[2]}'
    if n == 4:
        return f'{digits[:2]}.{digits[2:4]}'
    if n == 5:
        return f'{digits[:2]}.{digits[2:4]}.{digits[4]}'
    if n == 6:
        return f'{digits[:2]}.{digits[2:4]}.{digits[4:6]}'
    return f'{digits[:2]}.{digits[2:4]}.{digits[4:6]}.{digits[6:]}'


def code_levels(code):
    """Все уровни кода от раздела к самому коду: 32.99.59.000 → 32, 32.9, 32.99, 32.99.5, 32.99.59, …"""
    digits = re.sub(r'\D', '', str(code))
    return [_fmt_code(digits[:n]) for n in range(2, len(digits) + 1)]


def norm_code(v):
    return re.sub(r'\s+', '', str(v)).strip().rstrip('.')


def _parse_code_cell(raw):
    text = str(raw).replace('\xa0', ' ').strip()
    m = re.match(r'\s*(\d{2}(?:\.\d{1,3}){0,3})\.?(?![\d.])', text)
    if not m:
        return None, [], re.sub(r'\s+', ' ', text)
    rest = text[m.end():].strip(' .,;\n\t')
    exc = [x.group(0) for x in CODE_RE.finditer(rest)] if re.search(r'исключен|кроме', rest, re.IGNORECASE) else []
    return m.group(1), exc, re.sub(r'\s+', ' ', rest)


def _smp_cached(path, loader):
    key = (str(path), path.stat().st_mtime)
    if key not in _SMP_CACHE:
        _SMP_CACHE[key] = loader(path)
    return _SMP_CACHE[key]


def _load_restrictions(path):
    wb = load_workbook(path, read_only=True, data_only=True)
    rules = {}
    for sheet in ('Запрет', 'Ограничение'):
        if sheet not in wb.sheetnames:
            raise ValueError(f'В файле «{path.name}» нет листа «{sheet}». Есть листы: {", ".join(wb.sheetnames)}.')
        table, broken = {}, []
        for i, row in enumerate(wb[sheet].iter_rows(values_only=True), 1):
            if len(row) < 3 or row[2] is None or not re.search(r'\d', str(row[2])):
                continue
            code, exc, rest = _parse_code_cell(row[2])
            if code is None:
                broken.append(f'строка {i}: «{str(row[2])[:60]}»')
                continue
            e = table.setdefault(norm_code(code), {'exceptions': set(), 'note': ''})
            e['exceptions'].update(norm_code(x) for x in exc)
            if rest:
                e['note'] = rest
        if broken:
            raise ValueError(f'На листе «{sheet}» {len(broken)} ячеек не разобраны как код ОКПД2: {"; ".join(broken[:5])}. '
                             f'Проверка остановлена, чтобы не выдать отчёт по неполному реестру.')
        if not table:
            raise ValueError(f'На листе «{sheet}» не найдено ни одного кода (коды должны быть в 3-й колонке).')
        rules[sheet] = table
    return rules


def _load_smp_list(path):
    wb = load_workbook(path, read_only=True, data_only=True)
    if 'для работы' not in wb.sheetnames:
        raise ValueError(f'В перечне СМП нет листа «для работы». Есть листы: {", ".join(wb.sheetnames)}.')
    rows = wb['для работы'].iter_rows(values_only=True)
    head = [re.sub(r'\s+', ' ', str(h or '')).strip().lower() for h in next(rows)]
    code_col = next((i for i, h in enumerate(head) if h in ('код', 'код окпд2', 'код окпд 2')), None)
    smp_col = next((i for i, h in enumerate(head) if 'да/нет' in h or 'смп' in h or 'относ' in h), None)
    name_col = next((i for i, h in enumerate(head) if 'название' in h or 'наименование' in h), None)
    if code_col is None or smp_col is None:
        raise ValueError('В перечне СМП не найдены колонки кода и признака СМП. Колонки: ' + ', '.join(h for h in head if h))
    out, unknown, conflicts = {}, {}, []
    for row in rows:
        if code_col >= len(row):
            continue
        code = norm_code(row[code_col] if row[code_col] is not None else '')
        if not re.fullmatch(r'\d{2}(?:\.\d{1,3}){0,3}', code):
            continue
        flag = re.sub(r'\s+', ' ', str(row[smp_col] if smp_col < len(row) and row[smp_col] is not None else '')).strip().lower()
        if flag in SMP_YES:
            yes = True
        elif flag in SMP_NO:
            yes = False
        else:
            unknown[flag] = unknown.get(flag, 0) + 1
            continue
        if code in out and out[code]['is_smp'] != yes:
            conflicts.append(code)
        out[code] = {'name': str(row[name_col] or '') if name_col is not None and name_col < len(row) else '', 'is_smp': yes}
    if unknown:
        raise ValueError('В колонке признака СМП неизвестные значения: ' + ', '.join(f'«{k}» — {v}' for k, v in unknown.items()))
    if conflicts:
        raise ValueError('В перечне СМП один код помечен по-разному: ' + ', '.join(sorted(set(conflicts))[:10]))
    if not out:
        raise ValueError('Перечень СМП пустой — проверьте лист «для работы».')
    return out


def _load_direct(path, year, month, clause):
    wb = load_workbook(path, read_only=True, data_only=True)
    if str(year) not in wb.sheetnames:
        raise ValueError(f'В файле прямых договоров нет листа «{year}». Есть листы: {", ".join(wb.sheetnames)}.')
    rows = wb[str(year)].iter_rows(values_only=True)
    head = [re.sub(r'\s+', ' ', str(h or '')).strip().lower() for h in next(rows)]
    find = lambda w: next((i for i, h in enumerate(head) if w in h), None)
    cc, mc, oc = find('пункт'), find('месяц'), find('окпд')
    if None in (cc, mc, oc):
        raise ValueError('В прямых договорах не найдены колонки «Пункт положения», «Месяц публикации», «ОКПД 2».')
    used, stats = set(), {'по пункту': 0, 'без месяца': 0, 'другой год': 0}
    for row in rows:
        get = lambda i: row[i] if i < len(row) else None
        if re.sub(r'\s+', ' ', str(get(cc) or '')).strip() != clause:
            continue
        stats['по пункту'] += 1
        v = get(mc)
        if v in (None, ''):
            stats['без месяца'] += 1
            continue
        if hasattr(v, 'month'):
            if v.year != year:
                stats['другой год'] += 1
                continue
            mm = v.month
        else:
            txt = str(v).lower()
            mm = next((i + 1 for i, n in enumerate(MONTHS_NOM) if n in txt), None)
            if not mm:
                stats['без месяца'] += 1
                continue
            if str(year) not in txt:
                stats['другой год'] += 1
                continue
        if mm == month:
            used.update(norm_code(x) for x in CODE_IN_TEXT_RE.findall(str(get(oc) or '')))
    return used, stats


MONTHS_NOM = ['январ', 'феврал', 'март', 'апрел', 'ма', 'июн', 'июл', 'август', 'сентябр', 'октябр', 'ноябр', 'декабр']
MONTHS_NAME = ['январь', 'февраль', 'март', 'апрель', 'май', 'июнь', 'июль', 'август', 'сентябрь', 'октябрь', 'ноябрь', 'декабрь']


def _check_restr(code, rules):
    levels = list(reversed(code_levels(code)))
    for kind in ('Запрет', 'Ограничение'):
        for lv in levels:
            rule = rules.get(kind, {}).get(lv)
            if rule is None:
                continue
            if rule['exceptions'] & set(levels):
                continue
            note = f'по коду {lv}' if lv != norm_code(code) else ''
            if rule['note']:
                note = (note + '; ' if note else '') + 'в реестре: ' + rule['note']
            return kind, note
    return '', ''


def smp_check(items, kind, month_iso=None, clause=None):
    """items: [{name, okpd}]; kind: договор | счёт | заявка. → {'results', 'summary', 'sources', 'warnings', 'counters'}."""
    clause = clause or СМП_ПУНКТ_ПОЛОЖЕНИЯ
    p_smp, p_restr = smp_ref_path('smp'), smp_ref_path('restr')
    for k, p in (('smp', p_smp), ('restr', p_restr)):
        if not p.exists():
            raise ValueError(f'Нет справочника «{SMP_REF_TITLES[k]}» — загрузите файл в «Проверка СМП» → «Справочники».')
    rules = _smp_cached(p_restr, _load_restrictions)
    smp = _smp_cached(p_smp, _load_smp_list)
    d = date.fromisoformat(month_iso[:10]) if month_iso and re.match(r'\d{4}-\d\d', month_iso) else date.today()
    used, stats, warnings = set(), {}, []
    describe = lambda p: f'{p.name} — изменён {datetime.fromtimestamp(p.stat().st_mtime):%d.%m.%Y %H:%M}'
    sources = [describe(p_smp), describe(p_restr)]
    check_used = kind in ('договор', 'счёт')
    if check_used:
        p_dir = smp_ref_path('direct', d.year)
        if not p_dir.exists():
            raise ValueError(f'Нет файла «{p_dir.name}» — без него проверка по п. {clause} невозможна. '
                             f'Загрузите его в «Справочники» проверки или укажите путь в настройках (ФАЙЛ_ПРЯМЫХ_ДОГОВОРОВ).')
        used, stats = _load_direct(p_dir, d.year, d.month, clause)
        sources.append(describe(p_dir))
        if stats.get('без месяца'):
            warnings.append(f'В прямых договорах {stats["без месяца"]} строк по п. {clause} без месяца — не учтены.')
    res = []
    for it in items:
        code = norm_code(it.get('okpd') or it.get('code') or '')
        hit = next((lv for lv in reversed(code_levels(code)) if lv in smp), None)
        restr, note = _check_restr(code, rules)
        res.append({'name': it.get('name', ''), 'okpd': code, 'smp_code': hit or 'отсутствует в перечне СМП',
                    'smp_name': smp[hit]['name'] if hit else '', 'is_smp': 'ДА' if hit and smp[hit]['is_smp'] else 'НЕТ',
                    'used': 'ДА' if check_used and code in used else ('НЕТ' if check_used else '—'),
                    'restr': restr, 'note': note, 'qty': it.get('qty', ''), 'sum': it.get('sum', '')})
    summ = {'total': len(res), 'smp': sum(r['is_smp'] == 'ДА' for r in res), 'used': sum(r['used'] == 'ДА' for r in res),
            'ban': sorted({r['okpd'] for r in res if r['restr'] == 'Запрет'}),
            'lim': sorted({r['okpd'] for r in res if r['restr'] == 'Ограничение'}),
            'ban_n': sum(r['restr'] == 'Запрет' for r in res), 'lim_n': sum(r['restr'] == 'Ограничение' for r in res),
            'month': f'{MONTHS_NAME[d.month - 1]} {d.year}', 'clause': clause, 'kind': kind}
    counters = {'Кодов в перечне СМП': len(smp), 'Записей «Запрет»': len(rules['Запрет']), 'Записей «Ограничение»': len(rules['Ограничение'])}
    if check_used:
        counters[f'Кодов, использованных по п. {clause} за {summ["month"]}'] = len(used)
    return {'results': res, 'summary': summ, 'sources': sources, 'warnings': warnings, 'counters': counters}


def smp_summary_text(s):
    t = f"{s['smp']} из {s['total']} поз. в перечне СМП; запрет — {len(s['ban'])} код(ов), ограничение — {len(s['lim'])}"
    if s.get('kind') in ('договор', 'счёт'):
        t += f"; уже использовано по п. {s['clause']} за {s['month']} — {s['used']}"
    return t + f" (проверено {date.today():%d.%m.%Y})"


def smp_report_docx(data):
    """Отчёт Word — как у check_smp.py v2: исходные данные, итоги, коды под запретом/ограничением, перечень позиций."""
    from docx.shared import Cm
    from docx.enum.text import WD_ALIGN_PARAGRAPH
    res, s = data.get('results') or [], data.get('summary') or {}
    doc = Document()
    doc.add_heading('Отчёт о соответствии кодов ОКПД2 перечню СМП', 0)
    doc.add_paragraph(f"Документ: {data.get('file') or '—'} ({str(s.get('kind') or '').upper()})")
    doc.add_paragraph(f'Дата формирования: {datetime.now():%d.%m.%Y %H:%M} · панель УООЗД, проверка по логике check_smp v2')
    doc.add_heading('Исходные данные', level=2)
    for line in data.get('sources') or []:
        doc.add_paragraph(line, style='List Bullet')
    for k, v in (data.get('counters') or {}).items():
        doc.add_paragraph(f'{k}: {v}', style='List Bullet')
    if data.get('warnings'):
        doc.add_heading('Обратите внимание', level=2)
        for w in data['warnings']:
            doc.add_paragraph(w, style='List Bullet')
    doc.add_paragraph(f"Всего позиций: {s.get('total', 0)}")
    doc.add_paragraph(f"Из них соответствуют перечню СМП: {s.get('smp', 0)}")
    if s.get('kind') in ('договор', 'счёт'):
        doc.add_paragraph(f"Из них уже использованы по п. {s.get('clause')} за {s.get('month')}: {s.get('used', 0)}")
    doc.add_paragraph(f"Подпадают под ЗАПРЕТ: {s.get('ban_n', 0)} (уникальных кодов: {len(s.get('ban') or [])})")
    doc.add_paragraph(f"Подпадают под ОГРАНИЧЕНИЕ: {s.get('lim_n', 0)} (уникальных кодов: {len(s.get('lim') or [])})")
    if s.get('ban'):
        doc.add_heading('Коды под запретом (необходимо заменить)', level=2)
        for c in s['ban']:
            doc.add_paragraph(c, style='List Bullet')
    if s.get('lim'):
        doc.add_heading('Коды под ограничением', level=2)
        for c in s['lim']:
            doc.add_paragraph(c, style='List Bullet')
    if not s.get('ban') and not s.get('lim'):
        doc.add_paragraph('Все коды ОКПД2 не подпадают под запреты и ограничения.')
    doc.add_heading('Перечень позиций', level=2)
    heads = ['№', 'Наименование', 'Код ОКПД2', 'Код в перечне СМП', 'Наименование в перечне СМП', 'СМП', 'Использован', 'Запрет / ограничение', 'Примечание']
    t = doc.add_table(rows=1, cols=len(heads))
    t.style = 'Table Grid'
    for i, h in enumerate(heads):
        t.rows[0].cells[i].text = h
        t.rows[0].cells[i].paragraphs[0].runs[0].bold = True
        t.rows[0].cells[i].paragraphs[0].alignment = WD_ALIGN_PARAGRAPH.CENTER
    for n, r in enumerate(res, 1):
        c = t.add_row().cells
        for i, v in enumerate([n, r.get('name'), r.get('okpd'), r.get('smp_code'), r.get('smp_name'), r.get('is_smp'), r.get('used'), r.get('restr'), r.get('note')]):
            c[i].text = str(v if v is not None else '')
    for i, w in enumerate([1, 3.6, 2.2, 2.2, 2.8, 1.1, 1.4, 1.8, 3]):
        for row in t.rows:
            row.cells[i].width = Cm(w)
    buf = io.BytesIO()
    doc.save(buf)
    return buf.getvalue()


def smp_save_ref(kind, filename, raw):
    if kind not in SMP_REFS:
        raise ValueError('Неизвестный справочник')
    if not filename.lower().endswith(('.xlsx', '.xlsm')):
        raise ValueError('Нужен файл Excel (.xlsx)')
    tmp = smp_dir() / ('.проверка ' + SMP_REFS[kind].format(year=date.today().year))
    smp_dir().mkdir(parents=True, exist_ok=True)
    tmp.write_bytes(raw)
    try:
        if kind == 'smp':
            _load_smp_list(tmp)
        elif kind == 'restr':
            _load_restrictions(tmp)
        else:
            m = re.search(r'(20\d\d)', filename)
            _load_direct(tmp, int(m.group(1)) if m else date.today().year, 1, СМП_ПУНКТ_ПОЛОЖЕНИЯ)
    except Exception as e:
        tmp.unlink(missing_ok=True)
        raise ValueError(f'Файл не подходит: {e}')
    year = re.search(r'(20\d\d)', filename)
    dest = smp_dir() / SMP_REFS[kind].format(year=int(year.group(1)) if year else date.today().year)
    tmp.replace(dest)
    return dest.name




# ============================================================
# РЕЕСТР ОВРК: договор → исполнительные документы (УПД, акты) → платёжные поручения
# ============================================================
# Хранится в «Панель\ОВРК\договоры.json». На каждый договор — карточка: условия, сроки, остаток;
# в ней карточки УПД (№ РК, ответственный, сумма, дата внесения в ЕИС), к каждому УПД — платёжки (ПП).
# Панель сама считает: остатки, сроки размещения в ЕИС (УПД и ПП), срок исполнения обязательств и
# срок действия договора, статусы. Файлы платёжек ищет в папке ПАПКА_ПП по номеру и дате ПП: видно,
# какого файла не хватает. Если файл ПП — выгрузка из 1С (1CClientBankExchange) или PDF с текстом,
# сверяет сумму, ИНН получателя и назначение платежа — расхождения попадают в «Ошибки в ПП».

ОВРК_ПАПКА = 'ОВРК'
ПАПКА_ПП = ''                     # папка с файлами платёжек (сетевая); пусто — «Панель\ОВРК\Платёжки»
ОВРК_ДНЕЙ_ПП = 10                 # ПП должна быть в ЕИС не позднее стольких дней с даты платёжки
ОВРК_ДНЕЙ_УПД = 10                # УПД / акт — в ЕИС не позднее стольких дней с даты документа
ОВРК_РАБОЧИЕ_ДНИ = False          # True — считать рабочими днями (по ПРАЗДНИКИ), False — календарными
ОВРК_ПРЕДУПРЕЖДАТЬ_ЗА = 3         # «скоро срок» — за столько дней
ОВРК_СРОК_ДОГОВОРА_ЗА = 30        # «истекает срок действия / исполнения» — за столько дней
ОВРК_ШАБЛОН_ИМЕНИ_ПП = 'ПП {номер} от {дата}'    # как называется файл платёжки (расширение любое)
ОВРК_СОТРУДНИКИ = ['Волкова', 'Молочкова', 'Панова', 'Спиридонова', 'Тучкова', 'Сарсенова', 'Жидкова', 'Харитонова', 'Никитина']
ОВРК_СТАТУСЫ = ['да', 'нет', 'частично', 'закрыт', 'в ЕИС открыт', 'нет исполнения', 'не публикуется']
OVRK_LOCK = threading.Lock()
_PP_INDEX = {'at': 0, 'sig': None, 'items': [], 'by_num': {}}


def ovrk_can(user):
    return bool(user) and (user.get('admin') or user.get('dept') == 'ОВРК')


def _ovrk_path(name):
    return ПАПКА_ПАНЕЛИ / ОВРК_ПАПКА / name


def ovrk_load():
    return _json_file(f'{ОВРК_ПАПКА}/договоры.json', {'seq': 0, 'rows': []})


def ovrk_save_all(data):
    _ovrk_path('договоры.json').parent.mkdir(parents=True, exist_ok=True)
    write_atomic(_ovrk_path('договоры.json'), json.dumps(data, ensure_ascii=False, indent=0, default=str))


def pp_folder():
    return Path(ПАПКА_ПП) if ПАПКА_ПП else _ovrk_path('Платёжки')


def ovrk_add_days(d, n):
    return add_workdays(d, n) if ОВРК_РАБОЧИЕ_ДНИ else d + timedelta(days=n)


def pp_expected_name(num, d):
    try:
        ds = date.fromisoformat(d).strftime('%d.%m.%Y') if d else '__.__.____'
    except ValueError:
        ds = d
    return ОВРК_ШАБЛОН_ИМЕНИ_ПП.replace('{номер}', str(num or '').strip()).replace('{дата}', ds)


def _pp_from_exchange(text, rel):
    """Файл обмена 1С с банком (1CClientBankExchange): платёжные поручения → [{num, date, sum, inn, purpose}]."""
    out = []
    for block in re.findall(r'СекцияДокумент=[^\n]*\n(.*?)КонецДокумента', text, re.DOTALL):
        f = dict(re.findall(r'^([^=\n]+)=(.*)$', block, re.MULTILINE))
        out.append({'num': f.get('Номер', '').strip(), 'date': to_iso(f.get('Дата', '')) or '', 'sum': parse_price(f.get('Сумма', '')),
                    'inn': f.get('ПолучательИНН', '').strip(), 'payee': f.get('Получатель1', f.get('Получатель', '')).strip(),
                    'purpose': f.get('НазначениеПлатежа', '').strip(), 'file': rel, 'src': '1С'})
    return out


def _pp_from_name(stem):
    """«ПП 152431 от 06.02.2026», «пп_152431_06.02.26», «152431 06022026» → (номер, дата)."""
    s = stem.replace('_', ' ')
    d = to_iso(s)
    m = re.search(r'(?:пп|п/п|платежн\w*|поручени\w*)?\s*№?\s*(\d{3,})', s, re.IGNORECASE)
    num = m.group(1) if m else ''
    if num and d and num in re.sub(r'\D', '', d.replace('-', '')):
        num = ''
    if not d:
        m2 = re.search(r'(?<!\d)(\d{2})(\d{2})(20\d\d)(?!\d)', s)
        if m2:
            d = f'{m2.group(3)}-{m2.group(2)}-{m2.group(1)}'
    return num, d or ''


def pp_index(force=False):
    """Все файлы платёжек в папке: по номеру ПП. Пересканирование — не чаще раза в 30 секунд."""
    root = pp_folder()
    if not force and time.time() - _PP_INDEX['at'] < 30:
        return _PP_INDEX
    items = []
    if root.exists():
        for f in root.rglob('*'):
            if not f.is_file() or f.name.startswith(('~$', '.')):
                continue
            rel = str(f.relative_to(root))
            low = f.suffix.lower()
            got = []
            try:
                if low == '.txt' and f.stat().st_size < 5_000_000:
                    raw = f.read_bytes()
                    text = raw.decode('cp1251', errors='ignore') if b'1CClientBankExchange' not in raw[:200].replace(b'\x00', b'') else raw.decode('cp1251', errors='ignore')
                    if '1CClientBankExchange' in text[:200]:
                        got = _pp_from_exchange(text, rel)
                if not got:
                    num, d = _pp_from_name(f.stem)
                    entry = {'num': num, 'date': d, 'sum': None, 'inn': '', 'payee': '', 'purpose': '', 'file': rel, 'src': 'имя файла'}
                    if low == '.pdf' and f.stat().st_size < 10_000_000:
                        try:
                            t = pdf_text(f.read_bytes())
                            m = re.search(r'Сумма\s*[:\n]?\s*([\d\s]+[-.,]\d{2})', t)
                            if m:
                                entry['sum'] = parse_price(m.group(1).replace('-', '.'))
                            inns = [x for x in re.findall(r'ИНН\s*(\d{10}|\d{12})', t) if x != OUR_INN]
                            entry['inn'] = inns[-1] if inns else ''
                            m = re.search(r'Назначение платежа\s*\n?(.{5,300})', t)
                            entry['purpose'] = m.group(1).strip() if m else ''
                            entry['src'] = 'PDF'
                        except Exception:
                            pass
                    if num:
                        got = [entry]
            except OSError:
                continue
            items.extend(got)
    by = {}
    for it in items:
        if it['num']:
            by.setdefault(it['num'].lstrip('0'), []).append(it)
    _PP_INDEX.update({'at': time.time(), 'items': items, 'by_num': by})
    return _PP_INDEX


def _num_list(text):
    """В ячейке «номер и дата ПП» бывает несколько номеров через перенос строки."""
    return [x for x in re.findall(r'\d{3,}', str(text or ''))]


def ovrk_calc(c, idx=None, dup=None, today=None):
    """Пересчёт карточки договора: остатки, сроки, статусы, файлы и ошибки ПП. Меняет и возвращает c."""
    idx = idx or pp_index()
    today = today or date.today()
    T = today.isoformat()
    soon = (today + timedelta(days=ОВРК_ПРЕДУПРЕЖДАТЬ_ЗА)).isoformat()
    cont_inn = re.sub(r'\D', '', str(c.get('inn') or ''))
    cnum_digits = re.sub(r'\s+', '', str(c.get('cnum') or '')).lower()
    pp_total = upd_total = 0.0
    all_upd_ok = bool(c.get('upds'))
    tasks, errors = [], []
    for u in c.get('upds') or []:
        u['doc_date'] = to_iso(u.get('doc')) or u.get('doc_date') or ''
        u_sum = float(u['sum']) if isinstance(u.get('sum'), (int, float)) else 0.0
        upd_total += u_sum
        if u['doc_date']:
            u['eis_due'] = ovrk_add_days(date.fromisoformat(u['doc_date']), ОВРК_ДНЕЙ_УПД).isoformat()
        else:
            u['eis_due'] = ''
        u['eis_late'] = bool(not u.get('eis') and u['eis_due'] and u['eis_due'] < T)
        if not u.get('eis') and u['eis_due'] and u.get('status') != 'не публикуется':
            tasks.append({'kind': 'upd', 'due': u['eis_due'], 'late': u['eis_late'], 'resp': u.get('resp') or c.get('resp') or '',
                          'upd': u['id'], 'text': f"Разместить в ЕИС {u.get('doc') or 'исполнительный документ'}"})
        pp_sum, placed = 0.0, 0
        for p in u.get('pps') or []:
            p['date'] = to_iso(p.get('date')) or ''
            p_sum = float(p['sum']) if isinstance(p.get('sum'), (int, float)) else 0.0
            pp_sum += p_sum
            p['due'] = ovrk_add_days(date.fromisoformat(p['date']), ОВРК_ДНЕЙ_ПП).isoformat() if p['date'] else ''
            p['late'] = bool(not p.get('eis') and p['due'] and p['due'] < T)
            p['soon'] = bool(not p.get('eis') and p['due'] and T <= p['due'] <= soon)
            if p.get('eis'):
                placed += 1
            # файл платёжки: по номеру (и дате, если указана)
            p['expected'] = pp_expected_name(p.get('num'), p['date'])
            cands = idx['by_num'].get(str(p.get('num') or '').lstrip('0'), [])
            same = [x for x in cands if not p['date'] or not x['date'] or x['date'] == p['date']]
            hit = (same or cands or [None])[0]
            p['file'] = hit['file'] if hit else ''
            p['file_src'] = hit['src'] if hit else ''
            errs = []
            if not p.get('num'):
                errs.append('не указан номер ПП')
            elif not hit:
                errs.append(f"нет файла платёжки «{p['expected']}»")
            else:
                if hit['date'] and p['date'] and hit['date'] != p['date']:
                    errs.append(f"дата в файле {iso_to_ru(hit['date'])}, в реестре {iso_to_ru(p['date'])}")
                if not p['date'] and hit['date']:
                    p['date_from_file'] = hit['date']
                if hit.get('sum') is not None and p_sum and abs(hit['sum'] - p_sum) > 0.009:
                    errs.append(f"сумма в платёжке {_money_ru(hit['sum'])}, в реестре {_money_ru(p_sum)}")
                if hit.get('sum') is not None and not p_sum:
                    p['sum_from_file'] = hit['sum']
                if hit.get('inn') and cont_inn and hit['inn'] != cont_inn:
                    errs.append(f"ИНН получателя {hit['inn']} ≠ ИНН поставщика {cont_inn}")
                if hit.get('purpose') and cnum_digits and c.get('cnum'):
                    key = re.sub(r'\s+', '', str(c['cnum']).split(' от ')[0]).lower()
                    if key and key not in re.sub(r'\s+', '', hit['purpose']).lower():
                        errs.append('в назначении платежа нет номера договора')
            if p['date'] and u['doc_date'] and p['date'] < u['doc_date'] and not c.get('advance'):
                errs.append('платёжка раньше даты исполнительного документа')
            if p.get('eis') and p['date'] and p['eis'] < p['date']:
                errs.append('дата внесения в ЕИС раньше даты платёжки')
            if dup and len(dup.get(str(p.get('num') or '').lstrip('0'), [])) > 1:
                errs.append('этот номер ПП указан ещё в другом документе')
            p['errors'] = errs
            for e in errs:
                errors.append({'upd': u['id'], 'pp': p.get('num') or '', 'text': e, 'resp': u.get('resp') or c.get('resp') or ''})
            if not p.get('eis') and p['due'] and u.get('status') != 'не публикуется':
                tasks.append({'kind': 'pp', 'due': p['due'], 'late': p['late'], 'resp': u.get('resp') or c.get('resp') or '',
                              'upd': u['id'], 'pp': p.get('num'), 'text': f"Разместить в ЕИС ПП № {p.get('num') or '?'}"})
        u['pp_sum'] = round(pp_sum, 2)
        u['rest'] = round(u_sum - pp_sum, 2)
        if pp_sum - u_sum > 0.009:
            errors.append({'upd': u['id'], 'pp': '', 'text': f"оплачено по ПП больше суммы документа на {_money_ru(pp_sum - u_sum)}", 'resp': u.get('resp') or ''})
        n = len(u.get('pps') or [])
        auto = 'нет' if not n else ('да' if placed == n and u.get('eis') and u['rest'] <= 0.009 else 'частично' if placed or u.get('eis') else 'нет')
        u['status_auto'] = auto
        u['status_view'] = u['status'] if u.get('status') in ('закрыт', 'не публикуется') else auto
        pp_total += pp_sum
        if u['status_view'] not in ('да', 'закрыт', 'не публикуется'):
            all_upd_ok = False
    price = float(c['price']) if isinstance(c.get('price'), (int, float)) else 0.0
    # доп. соглашения: действующие цена и сроки — по последнему ДС, где они указаны
    term_src, val_src = c.get('term'), c.get('validity')
    c['price_eff'] = price
    for d in sorted(c.get('ds') or [], key=lambda x: x.get('date') or ''):
        if isinstance(d.get('price_new'), (int, float)) and d['price_new']:
            price = float(d['price_new'])
        if d.get('term_new'):
            term_src = d['term_new']
        if d.get('validity_new'):
            val_src = d['validity_new']
    c['price_eff'] = round(price, 2)
    for cl in c.get('claims') or []:
        if cl.get('due') and cl.get('status') in ('', 'открыта'):
            tasks.append({'kind': 'claim', 'due': cl['due'], 'late': cl['due'] < T, 'resp': next((u.get('resp') for u in c.get('upds') or [] if u.get('resp')), ''),
                          'text': f"Претензия {cl.get('num') or ''} от {iso_to_ru(cl.get('date')) if cl.get('date') else '—'}: срок ответа"})
    wk_ago = (today - timedelta(days=7)).isoformat()
    if c.get('new_at') and c['new_at'] >= wk_ago and not c.get('upds'):
        tasks.append({'kind': 'new', 'due': c['new_at'], 'late': False, 'resp': '', 'text': 'Новый договор — начать отслеживать исполнение'})
    for d in c.get('ds') or []:
        if d.get('new_at') and d['new_at'] >= wk_ago:
            tasks.append({'kind': 'ds', 'due': d['new_at'], 'late': False, 'resp': '',
                          'text': f"ДС {d.get('num') or ''} от {iso_to_ru(d.get('date')) if d.get('date') else '—'} — проверить новую цену и сроки"})
    seen_doc = {}
    for u in c.get('upds') or []:
        key = re.sub(r'[^0-9а-яёa-z]', '', str(u.get('doc') or '').lower())
        if key:
            if key in seen_doc:
                errors.append({'upd': u['id'], 'pp': '', 'text': f"документ «{u.get('doc')}» внесён в договор дважды", 'resp': u.get('resp') or ''})
            seen_doc[key] = 1
    c['pp_total'] = round(pp_total, 2)
    c['upd_total'] = round(upd_total, 2)
    c['rest'] = round(price - pp_total, 2)
    c['upd_rest'] = round(price - upd_total, 2)
    c['term_end'] = last_iso(term_src) or to_iso(term_src) or ''
    c['validity_iso'] = to_iso(val_src) or last_iso(val_src) or ''
    lim = (today + timedelta(days=ОВРК_СРОК_ДОГОВОРА_ЗА)).isoformat()
    alerts = []
    closed = c.get('status') == 'закрыт'
    if not closed:
        if c['term_end'] and c['term_end'] < T and c['upd_rest'] > 0.009:
            alerts.append({'kind': 'term', 'due': c['term_end'], 'late': True, 'text': f"срок исполнения обязательств прошёл, не исполнено на {_money_ru(c['upd_rest'])}"})
        elif c['term_end'] and T <= c['term_end'] <= lim and c['upd_rest'] > 0.009:
            alerts.append({'kind': 'term', 'due': c['term_end'], 'late': False, 'text': f"заканчивается срок исполнения обязательств, не исполнено на {_money_ru(c['upd_rest'])}"})
        if c['validity_iso'] and c['validity_iso'] < T:
            alerts.append({'kind': 'validity', 'due': c['validity_iso'], 'late': True, 'text': 'истёк срок действия договора — закрыть или продлить'})
        elif c['validity_iso'] and T <= c['validity_iso'] <= lim:
            alerts.append({'kind': 'validity', 'due': c['validity_iso'], 'late': False, 'text': 'заканчивается срок действия договора'})
        if c.get('upds') and all_upd_ok and c['rest'] <= 0.009:
            alerts.append({'kind': 'close', 'due': T, 'late': False, 'text': 'всё оплачено и внесено в ЕИС — договор можно закрыть'})
    if pp_total - price > 0.009 and price:
        errors.append({'upd': '', 'pp': '', 'text': f"оплачено больше цены договора на {_money_ru(pp_total - price)}", 'resp': c.get('resp') or ''})
    c['status_auto'] = 'закрыт' if closed else ('нет исполнения' if not c.get('upds') else 'в ЕИС открыт')
    c['status_view'] = c['status'] if c.get('status') in ('закрыт', 'не публикуется', 'нет исполнения') else c['status_auto']
    c['tasks'] = tasks
    c['alerts'] = alerts
    c['errors'] = errors
    c['resps'] = sorted({u.get('resp') for u in c.get('upds') or [] if u.get('resp')} | ({c['resp']} if c.get('resp') else set()))
    return c


def ovrk_all(force_index=False):
    data = ovrk_load()
    idx = pp_index(force_index)
    dup = {}
    for c in data['rows']:
        for u in c.get('upds') or []:
            for p in u.get('pps') or []:
                if p.get('num'):
                    dup.setdefault(str(p['num']).lstrip('0'), []).append((c['id'], u['id']))
    for c in data['rows']:
        ovrk_calc(c, idx, dup)
    used = set(dup)
    free = [x for x in idx['items'] if x['num'] and x['num'].lstrip('0') not in used]
    return data, idx, free


def _clean_pp(p):
    out = {'num': re.sub(r'\s+', '', str(p.get('num') or ''))[:30], 'date': to_iso(p.get('date')) or '', 'eis': to_iso(p.get('eis')) or ''}
    v = p.get('sum')
    out['sum'] = v if isinstance(v, (int, float)) else (parse_price(v) if str(v or '').strip() else '')
    out['note'] = str(p.get('note') or '')[:300]
    return out


def _clean_upd(u, seq):
    out = {'id': u.get('id') or f'u{seq}', 'rk': str(u.get('rk') or '').strip()[:60], 'resp': str(u.get('resp') or '').strip()[:60],
           'doc': str(u.get('doc') or '').strip()[:200], 'eis': to_iso(u.get('eis')) or '', 'status': str(u.get('status') or '')[:30],
           'note': str(u.get('note') or '')[:500]}
    v = u.get('sum')
    out['sum'] = v if isinstance(v, (int, float)) else (parse_price(v) if str(v or '').strip() else '')
    out['pps'] = [_clean_pp(p) for p in (u.get('pps') or []) if isinstance(p, dict) and (p.get('num') or p.get('sum') or p.get('date'))]
    return out


# Претензии: список полей — предварительный, уточнить у ОВРК.
CLAIM_STATUSES = ['открыта', 'ответ дан', 'удовлетворена', 'отклонена']


def _clean_claim(x):
    out = {k: str(x.get(k) or '').strip()[:300] for k in ('num', 'reason', 'status', 'note')}
    out['date'] = to_iso(x.get('date')) or ''
    out['due'] = to_iso(x.get('due')) or ''
    v = x.get('sum')
    out['sum'] = v if isinstance(v, (int, float)) else (parse_price(v) if str(v or '').strip() else '')
    return out


def _clean_ds(x):
    """Доп. соглашение: что поменялось — цена, срок исполнения, срок действия."""
    out = {k: str(x.get(k) or '').strip()[:300] for k in ('num', 'reason', 'term_new', 'validity_new', 'note')}
    out['date'] = to_iso(x.get('date')) or ''
    if x.get('new_at'):
        out['new_at'] = str(x['new_at'])[:10]
    for k in ('sum', 'price_new'):
        v = x.get(k)
        out[k] = v if isinstance(v, (int, float)) else (parse_price(v) if str(v or '').strip() else '')
    return out


CONTRACT_FIELDS = ('kind', 'unit', 'subject', 'org', 'inn', 'address', 'price', 'term', 'validity', 'cnum', 'monopolist', 'resp', 'status', 'note', 'advance')


def ovrk_save(cid, values, ver, actor, note='', _data=None):
    if _data is not None:          # пакетная загрузка: данные уже открыты и сохранятся одним разом
        return _ovrk_save(_data, cid, values, ver, actor, note)
    with OVRK_LOCK:
        data = ovrk_load()
        c, ch = _ovrk_save(data, cid, values, ver, actor, note)
        if ch:
            ovrk_save_all(data)
        return c, ch


def _ovrk_save(data, cid, values, ver, actor, note=''):
    who = (actor or {}).get('fio') or 'панель'
    if True:
        if cid:
            c = next((x for x in data['rows'] if x['id'] == cid), None)
            if not c:
                raise ValueError('Договор уже удалён')
            if ver is not None and int(ver) != c.get('_ver', 0):
                raise ValueError(f"Карточку только что изменил(а) {c.get('_by', 'кто-то')} — откройте её заново")
        else:
            data['seq'] = data.get('seq', 0) + 1
            c = {'id': f"d{data['seq']}", '_ver': 0, '_hist': [], 'upds': []}
            data['rows'].append(c)
        before = json.dumps({k: c.get(k) for k in CONTRACT_FIELDS + ('upds', 'claims', 'ds')}, ensure_ascii=False, sort_keys=True, default=str)
        for k in CONTRACT_FIELDS:
            if k in values:
                v = values[k]
                if k == 'price':
                    v = v if isinstance(v, (int, float)) else (parse_price(v) if str(v or '').strip() else '')
                elif k == 'monopolist' or k == 'advance':
                    v = bool(v)
                else:
                    v = str(v or '').strip()
                c[k] = v
        if 'upds' in values:
            seq = data.get('useq', 0)
            ups = []
            for u in values['upds'] or []:
                if not u.get('id'):
                    seq += 1
                ups.append(_clean_upd(u, seq))
            data['useq'] = seq
            c['upds'] = ups
        if 'claims' in values:
            c['claims'] = [_clean_claim(x) for x in values['claims'] or [] if isinstance(x, dict) and any(str(x.get(k) or '').strip() for k in ('num', 'date', 'sum', 'reason'))]
        if 'ds' in values:
            c['ds'] = [_clean_ds(x) for x in values['ds'] or [] if isinstance(x, dict) and any(str(x.get(k) or '').strip() for k in ('num', 'date', 'price_new', 'term_new', 'validity_new', 'sum'))]
        after = json.dumps({k: c.get(k) for k in CONTRACT_FIELDS + ('upds', 'claims', 'ds')}, ensure_ascii=False, sort_keys=True, default=str)
        if before == after and cid:
            return c, False
        c['_ver'] = c.get('_ver', 0) + 1
        c['_by'], c['_at'] = who, datetime.now().isoformat(timespec='seconds')
        c['_hist'] = (c.get('_hist') or [])[-60:] + [{'at': c['_at'], 'by': who, 'note': note or ('создан' if not cid else 'изменён')}]
        for k in ('tasks', 'alerts', 'errors'):
            c.pop(k, None)
    return c, True


def ovrk_staff_name(fio):
    """«Тучкова А.А.» → «Тучкова» (как в списке сотрудников ОВРК), если такая есть."""
    sur = str(fio or '').split()[0] if fio else ''
    return next((x for x in ОВРК_СОТРУДНИКИ if x.split()[0] == sur), fio)


def ovrk_mark_eis(cid, upd_id, pp_num, when, actor):
    """Быстрая отметка «Размещено в ЕИС» из задачи: для УПД (pp_num пустой) или для ПП."""
    with OVRK_LOCK:
        data = ovrk_load()
        c = next((x for x in data['rows'] if x['id'] == cid), None)
        u = next((x for x in (c or {}).get('upds') or [] if x['id'] == upd_id), None)
        if not u:
            raise ValueError('Документ не найден')
        what = ''
        if pp_num:
            p = next((x for x in u.get('pps') or [] if str(x.get('num')) == str(pp_num)), None)
            if not p:
                raise ValueError('ПП не найдена')
            p['eis'] = when
            what = f'ПП № {pp_num} внесена в ЕИС'
        else:
            u['eis'] = when
            what = f"{u.get('doc') or 'документ'} внесён в ЕИС"
        who = (actor or {}).get('fio') or 'панель'
        if not u.get('resp') and (actor or {}).get('fio'):
            u['resp'] = ovrk_staff_name(actor['fio'])   # ответственный за размещение в ЕИС — тот, кто отметил «Размещено»
        c['_ver'] = c.get('_ver', 0) + 1
        c['_by'], c['_at'] = who, datetime.now().isoformat(timespec='seconds')
        c['_hist'] = (c.get('_hist') or [])[-60:] + [{'at': c['_at'], 'by': who, 'note': what}]
        ovrk_save_all(data)
    log('edit', f"ОВРК, договор {c.get('cnum')}: {what}", user=(actor or {}).get('fio') or 'панель')
    return c


def ovrk_import_xlsx(raw):
    """Таблица ОВРК в прежнем виде: строка «1» — договор, строки «0» под ним — исполнительные документы с ПП.
    Листы «конкурентные» и «прямые» (колонки ищутся по заголовкам)."""
    wb = load_workbook(io.BytesIO(raw), data_only=True)
    out = []
    for ws in wb.worksheets:
        kind = 'прямые' if 'прям' in ws.title.lower() else 'конкурентные'
        head = [re.sub(r'\s+', ' ', str(c.value or '')).strip().lower() for c in ws[1]]

        def col(*words, exclude=()):
            for i, h in enumerate(head):
                if all(w in h for w in words) and not any(x in h for x in exclude):
                    return i
            return None
        C = {'unit': col('кц'), 'subject': col('предмет'), 'org': col('организаци'), 'price': col('цена') if col('цена') is not None else col('сумма', exclude=('испол', 'пп', 'п/п')),
             'term': col('срок', exclude=('действ',)), 'validity': col('срок', 'действ'), 'cnum': col('номер', 'договор') if col('номер', 'договор') is not None else col('номер и дата договора'),
             'rk': col('рк'), 'resp': col('ответствен'), 'flag': col('1/0'),
             'doc': next((i for i, h in enumerate(head) if 'испол' in h and 'сумма' not in h and ('наим' in h or 'ним' in h or 'док' in h)), None), 'dsum': col('сумма', 'испол'),
             'eis': col('дата внесения в еис', exclude=('пп', 'п/п')), 'ppnum': next((i for i, h in enumerate(head) if ('номер' in h and ('пп' in h or 'п/п' in h))), None),
             'ppeis': next((i for i, h in enumerate(head) if 'еис' in h and ('пп' in h or 'п/п' in h)), None), 'ppsum': col('сумма пп'),
             'mono': col('монопол')}
        # колонка статуса без заголовка — последняя заполненная после «остаток»
        st_i = None
        ost = col('остаток')
        if ost is not None:
            st_i = ost + 1
        cur = None
        for row in ws.iter_rows(min_row=2, values_only=True):
            g = lambda k: (row[C[k]] if C.get(k) is not None and C[k] < len(row) else None)
            if not any(v not in (None, '') for v in row):
                continue
            flag = str(g('flag') if g('flag') is not None else '').strip()
            status = str(row[st_i]).strip() if st_i is not None and st_i < len(row) and row[st_i] not in (None, '') else ''
            if flag in ('1', '1.0') or (cur is None):
                cur = {'kind': kind, 'unit': str(g('unit') or '').strip().upper(), 'subject': str(g('subject') or '').strip(), 'org': str(g('org') or '').strip(),
                       'price': g('price') if isinstance(g('price'), (int, float)) else parse_price(g('price') or ''), 'term': iso_to_ru(to_iso(g('term'))) if isinstance(g('term'), (datetime, date)) else str(g('term') or '').strip(),
                       'validity': iso_to_ru(to_iso(g('validity'))) if isinstance(g('validity'), (datetime, date)) else str(g('validity') or '').strip(),
                       'cnum': str(g('cnum') or '').strip(), 'monopolist': bool(str(g('mono') or '').strip()), 'status': status if status in ('закрыт', 'не публикуется') else '',
                       'upds': []}
                out.append(cur)
                if flag in ('1', '1.0'):
                    continue
            nums = _num_list(g('ppnum'))
            pp_total = g('ppsum') if isinstance(g('ppsum'), (int, float)) else parse_price(g('ppsum') or '') if g('ppsum') else None
            pps = []
            for k, n in enumerate(nums):
                pps.append({'num': n, 'date': '', 'sum': pp_total if k == 0 and pp_total is not None else '', 'eis': to_iso(g('ppeis')) or '',
                            'note': f'одной суммой с {", ".join(nums)}' if len(nums) > 1 and k == 0 else ''})
            if not nums and pp_total:
                pps.append({'num': '', 'sum': pp_total, 'eis': to_iso(g('ppeis')) or ''})
            if not (g('doc') or g('dsum') or nums):
                continue
            cur['upds'].append({'rk': str(g('rk') or '').strip(), 'resp': str(g('resp') or '').strip(), 'doc': str(g('doc') or '').strip(),
                                'sum': g('dsum') if isinstance(g('dsum'), (int, float)) else parse_price(g('dsum') or ''), 'eis': to_iso(g('eis')) or '',
                                'status': status if status in ('закрыт', 'не публикуется') else '', 'pps': pps})
    return out


def ovrk_import_oao(raw):
    """Выгрузка из таблицы делопроизводителей ОАО («прямые договоры»): лист года — договоры (берём только с номером
    договора, т. е. заключённые), лист «ДС» — доп. соглашения к ним. Пока ОАО не в панели — так раз в неделю."""
    wb = load_workbook(io.BytesIO(raw), data_only=True, read_only=True)
    out, by = [], {}
    for ws in wb.worksheets:
        rows = ws.iter_rows(values_only=True)
        head = [re.sub(r'\s+', ' ', str(x or '')).strip().lower() for x in next(rows, [])]
        col = lambda *w: next((i for i, h in enumerate(head) if all(x in h for x in w)), None)
        if col('номер договора') is not None and col('организация') is not None and col('предмет') is not None:
            C = {'cnum': col('номер договора'), 'org': col('организация'), 'subject': col('предмет'), 'price': col('сумма'), 'inn': col('инн'),
                 'term': col('срок поставки'), 'validity': col('срок действия'), 'mono': col('смп/монопол'), 'peo': col('пэо'), 'kc': col('кц/д'), 'note': col('примечание')}
            for r in rows:
                g = lambda k: r[C[k]] if C.get(k) is not None and C[k] < len(r) else None
                cn = str(g('cnum') or '').strip()
                if not cn or cn.lower() in ('none', '#n/a'):
                    continue
                unit = 'КЦ' if (g('kc') not in (None, '') or 'кц' in str(g('peo') or '').lower()) else 'ВУЗ'
                tl = ws.title.lower()
                c = {'kind': 'прямые' if 'прям' in tl else 'неконкурентные' if 'неконк' in tl else 'конкурентные' if ('конк' in tl or 'процед' in tl) else 'прямые', 'unit': unit, 'cnum': cn, 'org': str(g('org') or '').strip(), 'subject': str(g('subject') or '').strip(),
                     'price': g('price') if isinstance(g('price'), (int, float)) else parse_price(g('price') or ''),
                     'inn': re.sub(r'\D', '', str(g('inn') or ''))[:12], 'term': _cell_txt(g('term')), 'validity': _cell_txt(g('validity')),
                     'monopolist': 'монопол' in str(g('mono') or '').lower(), 'note': '', 'upds': [], 'ds': []}
                out.append(c)
                by.setdefault(_cnum_split(cn)[0], c)
        elif col('№ ds') is not None or col('№ дс') is not None:
            C = {'cnum': col('дата заключения догов'), 'num': col('№ дс'), 'sum': col('сумма дс'), 'reason': col('причина'), 'date': col('дата заключения дс'), 'note': col('замечания')}
            for r in rows:
                g = lambda k: r[C[k]] if C.get(k) is not None and C[k] < len(r) else None
                key = _cnum_split(g('cnum'))[0] if g('cnum') else ''
                if not key or not g('num'):
                    continue
                c = by.get(key)
                if c is None:          # ДС к договору, которого нет в этой выгрузке (заключён раньше) — сверим с реестром ОВРК
                    c = by[key] = {'cnum': str(g('cnum')).strip(), 'ds': [], '_ds_only': True}
                    out.append(c)
                c['ds'].append({'num': str(g('num')).strip(), 'date': to_iso(g('date')) or '', 'reason': str(g('reason') or '').strip(),
                                'sum': g('sum') if isinstance(g('sum'), (int, float)) else parse_price(g('sum') or '') if g('sum') else '',
                                'note': str(g('note') or '').strip()[:300] if g('note') else ''})
    return out


def _cell_txt(v):
    if isinstance(v, (datetime, date)):
        return iso_to_ru(to_iso(v))
    return str(v or '').strip()


ОВРК_НОВЫЕ_ДНЕЙ = 7      # «Новые за неделю» из реестра ОАО: договоры, заключённые за столько последних дней


def ovrk_from_registry(days=None):
    """Заключённые договоры из общего реестра ОАО (конкурентные и неконкурентные) — для ОВРК. days — только за последние N дней."""
    refresh_cache()
    out = []
    lim = (date.today() - timedelta(days=days)).isoformat() if days else ''
    for r in cache['rows']:
        cn = str(r.get('contract') or '').strip()
        if not cn or not r.get('contract_date') or (lim and r['contract_date'] < lim):
            continue
        out.append({'kind': 'неконкурентные' if r.get('sheet') == 'nk' else 'конкурентные', 'unit': 'КЦ' if 'КЦ' in str(r.get('subordination') or '').upper() else 'ВУЗ',
                    'cnum': cn, 'org': re.sub(r'\s*ИНН.*$', '', str(r.get('winner') or '')).strip(), 'inn': re.sub(r'\D', '', str(r.get('inn') or ''))[:12],
                    'subject': str(r.get('name') or '').strip(), 'price': r.get('price') if isinstance(r.get('price'), (int, float)) else '',
                    'note': f"из реестра ОАО: {r.get('oao') or ''}", 'upds': []})
    return out


def ovrk_new_parse(rows, src):
    """Что нового за неделю в таблицах ОАО: новые договоры дороже 500 000 и новые ДС к нашим договорам. Ничего не пишет."""
    have = {}
    for c in ovrk_load()['rows']:
        have.setdefault(_cnum_split(c.get('cnum'))[0], c)
    items, known, small = [], 0, 0
    seen = set()
    for c in rows:
        key = _cnum_split(c.get('cnum'))[0]
        if not key or key in seen:
            continue
        seen.add(key)
        old = have.get(key)
        if old is None and c.get('_ds_only'):
            continue           # ДС к договору, которого нет в реестре ОВРК (до 500 000 или ещё не внесён)
        if old is not None:
            nds = [d for d in c.get('ds') or [] if not any(str(x.get('num')) == str(d.get('num')) for x in old.get('ds') or [])]
            for d in nds:
                items.append({'type': 'ds', 'cid': old['id'], 'label': f"{old.get('cnum')} · {old.get('org') or ''}", 'ds': d,
                              'state': 'новое ДС к договору в реестре ОВРК'})
            known += 1
            continue
        if isinstance(c.get('price'), (int, float)) and c['price'] <= ОВРК_ПОРОГ_ИСПОЛНЕНИЯ:
            small += 1
            continue
        c = dict(c)
        items.append({'type': 'new', 'c': {k: c.get(k) for k in ('kind', 'unit', 'cnum', 'org', 'inn', 'subject', 'price', 'term', 'validity', 'monopolist')},
                      'ds': c.get('ds') or [], 'state': 'новый договор' + ('' if isinstance(c.get('price'), (int, float)) else ' · цена не указана — проверьте')})
    return {'items': items, 'known': known, 'small': small, 'src': src}


def ovrk_new_apply(items, actor):
    n_new = n_ds = 0
    today = date.today().isoformat()
    with OVRK_LOCK:
        data = ovrk_load()
        by = {c['id']: c for c in data['rows']}
        have = {_cnum_split(c.get('cnum'))[0] for c in data['rows']}
        for it in items:
            if it.get('type') == 'new' and it.get('c'):
                c = dict(it['c'])
                if _cnum_split(c.get('cnum'))[0] in have:
                    continue
                if isinstance(c.get('price'), str):
                    c['price'] = parse_price(c['price']) if c['price'].strip() else ''
                c['ds'] = [dict(d, new_at=today) for d in it.get('ds') or []]
                new, _ = ovrk_save(None, c, None, actor, note='новый договор из таблицы ОАО (за неделю)', _data=data)
                new['new_at'] = today
                have.add(_cnum_split(c.get('cnum'))[0])
                n_new += 1
            elif it.get('type') == 'ds' and by.get(it.get('cid')) and it.get('ds'):
                c = by[it['cid']]
                d = _clean_ds(it['ds'])
                d['new_at'] = today
                if not any(str(x.get('num')) == str(d.get('num')) for x in c.get('ds') or []):
                    c.setdefault('ds', []).append(d)
                    c['_ver'] = c.get('_ver', 0) + 1
                    c['_hist'] = (c.get('_hist') or [])[-60:] + [{'at': datetime.now().isoformat(timespec='seconds'), 'by': (actor or {}).get('fio') or 'панель', 'note': f"ДС {d.get('num')} из таблицы ОАО"}]
                    n_ds += 1
        if n_new or n_ds:
            ovrk_save_all(data)
    return n_new, n_ds


def ovrk_merge(rows, actor, src):
    """Добавить договоры без дублей: тот же номер (и дата) уже есть — пропускаем; новые ДС — дописываем."""
    with OVRK_LOCK:
        data = ovrk_load()
        res = _ovrk_merge(data, rows, actor, src)
        if res['added'] or res['ds_added']:
            ovrk_save_all(data)
    return res


def _ovrk_merge(data, rows, actor, src):
    have = {}
    for c in data['rows']:
        have.setdefault(_cnum_split(c.get('cnum'))[0], c)
    added = ds_added = skipped = small = 0
    for c in rows:
        key = _cnum_split(c.get('cnum'))[0]
        if not key:
            continue
        if isinstance(c.get('price'), (int, float)) and c['price'] <= ОВРК_ПОРОГ_ИСПОЛНЕНИЯ and key not in have:
            small += 1        # до 500 000 ОВРК не ведёт — остаётся в БГУ
            continue
        old = have.get(key)
        if old is None and c.get('_ds_only'):
            continue
        if old is None:
            new, _ = ovrk_save(None, c, None, actor, note=f'загружен: {src}', _data=data)
            have[key] = new
            added += 1
            continue
        skipped += 1
        nds = [d for d in c.get('ds') or [] if not any(str(x.get('num')) == str(d.get('num')) for x in old.get('ds') or [])]
        if nds:
            ovrk_save(old['id'], {'ds': (old.get('ds') or []) + nds}, None, actor, note=f'доп. соглашения: {src}', _data=data)
            ds_added += len(nds)
    return {'added': added, 'skipped': skipped, 'ds_added': ds_added, 'small': small}


def ovrk_pay_parse(raw, name=''):
    """Перечень платёжек от бухгалтерии → предложения: к какому договору и документу отнести. Ничего не пишет."""
    if str(name).lower().endswith('.xls'):
        sheets = xls_sheets(raw)
    else:
        wb = load_workbook(io.BytesIO(raw), data_only=True, read_only=True)
        sheets = {ws.title: [list(r) for r in ws.iter_rows(values_only=True)] for ws in wb.worksheets}
    data, _, _ = ovrk_all()
    C_ = data['rows']
    have = {}
    for c in C_:
        for u in c.get('upds') or []:
            for p in u.get('pps') or []:
                if p.get('num'):
                    have.setdefault(str(p['num']).lstrip('0'), []).append((c, u, p))
    out = []
    for title, rows in sheets.items():
        hi = next((i for i, r in enumerate(rows[:8]) if sum(1 for x in r if x not in (None, '')) >= 4 and any('сумм' in str(x).lower() for x in r)), None)
        if hi is None:
            continue
        head = [re.sub(r'\s+', ' ', str(x or '')).strip().lower() for x in rows[hi]]
        col = lambda *w, ex=(): next((i for i, h in enumerate(head) if all(x in h for x in w) and not any(e in h for e in ex)), None)
        C = {'num': col('номер') if col('номер') is not None else col('№', ex=('п/п',)), 'date': col('дата', ex=('провод', 'выгруз')), 'sum': col('сумм'),
             'payee': col('получател', ex=('инн',)), 'inn': col('инн'), 'purpose': col('назначен')}
        for r in rows[hi + 1:]:
            g = lambda k: r[C[k]] if C.get(k) is not None and C[k] < len(r) else None
            num = re.sub(r'\.0$', '', str(g('num') or '').strip())
            if not num or not g('sum'):
                continue
            pp = {'num': num, 'date': to_iso(g('date')) or '', 'sum': g('sum') if isinstance(g('sum'), (int, float)) else parse_price(g('sum')),
                  'payee': str(g('payee') or '').strip(), 'inn': re.sub(r'\D', '', str(g('inn') or '')), 'purpose': str(g('purpose') or '').strip()}
            it = {'pp': pp, 'cid': '', 'uid': '', 'dup': False}
            old = [x for x in have.get(num.lstrip('0'), []) if not pp['date'] or not x[2].get('date') or x[2]['date'] == pp['date']]
            if old:
                c, u, _ = old[0]
                it.update(dup=True, cid=c['id'], uid=u['id'], state=f"уже в реестре: дог. {c.get('cnum')}", why='дубль')
                out.append(it)
                continue
            purp = re.sub(r'\s+', '', pp['purpose']).lower()
            best, sc_best, why_best = None, 0, ''
            for c in C_:
                sc, why = 0, []
                if pp['inn'] and pp['inn'] == re.sub(r'\D', '', str(c.get('inn') or '')):
                    sc += 3; why.append('ИНН')
                key = re.sub(r'\s+', '', str(c.get('cnum') or '').split(' от ')[0]).lower()
                if key and (re.search(r'договор\w*\s*№?\s*' + re.escape(key) + r'(?![0-9/\-])', pp['purpose'].lower()) or (len(key) >= 6 and key in purp)):
                    sc += 4; why.append('№ договора')
                cinn = re.sub(r'\D', '', str(c.get('inn') or ''))
                if pp['inn'] and cinn and pp['inn'] != cinn:
                    sc -= 3        # получатель другой — не этот договор
                if pp['payee'] and c.get('org') and re.sub(r'[^а-яёa-z0-9]', '', c['org'].lower())[:12] in re.sub(r'[^а-яёa-z0-9]', '', pp['payee'].lower()):
                    sc += 1; why.append('получатель')
                if sc > sc_best:
                    best, sc_best, why_best = c, sc, ', '.join(why)
            if not best or sc_best < 3:
                it['state'] = 'нет в реестре ОВРК'
                out.append(it)
                continue
            it['cid'] = best['id']
            ups = best.get('upds') or []
            u = next((x for x in ups if isinstance(x.get('rest'), (int, float)) and pp['sum'] and abs(x['rest'] - pp['sum']) < 0.01), None)
            if u is None:
                u = next((x for x in ups if x.get('doc') and re.sub(r'\s+', '', x['doc'].split(' от ')[0]).lower() in purp), None)
            if u is None:
                u = next((x for x in reversed(ups) if isinstance(x.get('rest'), (int, float)) and x['rest'] > 0.01), None)
            it['uid'] = u['id'] if u else ''
            if not u:
                it['nodoc'] = True       # платёжку вешаем только на заведённый документ
            it['state'] = f"подобрано: {why_best}" + ('' if u else ' · документ не найден — сначала заведите УПД / акт')
            out.append(it)
    cands = [{'id': c['id'], 'label': f"{c.get('cnum') or '—'} · {c.get('org') or ''}"[:90],
              'upds': [{'id': u['id'], 'label': f"{u.get('doc') or 'документ'} · остаток {_money_ru(u.get('rest') or 0)}"} for u in c.get('upds') or []]} for c in C_]
    return out, cands


def ovrk_pay_apply(items, actor):
    n = 0
    with OVRK_LOCK:
        data = ovrk_load()
        by = {c['id']: c for c in data['rows']}
        for it in items:
            c, pp = by.get(it.get('cid')), it.get('pp') or {}
            if not c or not pp.get('num'):
                continue
            ups = c.setdefault('upds', [])
            u = next((x for x in ups if x.get('id') == it.get('uid')), None)
            if u is None:
                continue                 # без документа не вносим — сначала заводят УПД / акт
            if any(str(p.get('num')) == str(pp['num']) for p in u.get('pps') or []):
                continue
            u.setdefault('pps', []).append(_clean_pp({'num': pp['num'], 'date': pp.get('date'), 'sum': pp.get('sum'), 'eis': '',
                                                     'note': 'из перечня бухгалтерии'}))
            c['_ver'] = c.get('_ver', 0) + 1
            c['_by'], c['_at'] = (actor or {}).get('fio') or 'панель', datetime.now().isoformat(timespec='seconds')
            c['_hist'] = (c.get('_hist') or [])[-60:] + [{'at': c['_at'], 'by': c['_by'], 'note': f"ПП № {pp['num']} из перечня бухгалтерии"}]
            n += 1
        if n:
            ovrk_save_all(data)
    return n


def ovrk_xlsx(rows, idx=None):
    """Выгрузка в привычном виде: лист на вид договоров, строка договора (1) и строки документов (0)."""
    wb = Workbook()
    wb.remove(wb.active)
    thin = Side(style='thin', color='CFCDC6')
    heads = ['КЦ/ВУЗ', 'Предмет договора', 'Организация (Лицо)', 'Цена договора', 'Срок исполнения обязательств', 'Срок действия договора',
             'Номер и дата договора', '№ РК', 'Ответственный', '1/0', 'Исполнительный документ', 'Сумма документа', 'Дата внесения в ЕИС',
             'Номер ПП', 'Дата ПП', 'Дата внесения в ЕИС ПП', 'Сумма ПП', 'Остаток', 'Статус', 'Срок ЕИС', 'Файл ПП', 'Ошибки']
    for kind in ('конкурентные', 'прямые'):
        ws = wb.create_sheet(kind)
        ws.append(heads)
        for c in ws[1]:
            c.font = Font(bold=True)
            c.fill = PatternFill('solid', fgColor='FFF2CC')
            c.alignment = Alignment(wrap_text=True, vertical='center')
            c.border = Border(top=thin, bottom=thin, left=thin, right=thin)
        for c in [x for x in rows if (x.get('kind') or 'конкурентные') == kind]:
            base = [c.get('unit'), c.get('subject'), c.get('org'), c.get('price'), c.get('term'), c.get('validity'), c.get('cnum')]
            ws.append(base + ['', c.get('resp', ''), 1, '', '', '', '', '', '', c.get('pp_total'), c.get('rest'), c.get('status_view'), '', '', '; '.join(e['text'] for e in c.get('errors', []) if not e['upd'])])
            r0 = ws.max_row
            for cell in ws[r0]:
                cell.font = Font(bold=True)
                cell.fill = PatternFill('solid', fgColor='EEF4FB')
            for u in c.get('upds') or []:
                pps = u.get('pps') or [{}]
                for k, p in enumerate(pps):
                    ws.append(base + [u.get('rk'), u.get('resp'), 0, u.get('doc') if k == 0 else '', u.get('sum') if k == 0 else '',
                                      _xd(u.get('eis')) if k == 0 else '', p.get('num', ''), _xd(p.get('date')), _xd(p.get('eis')), p.get('sum', ''),
                                      u.get('rest') if k == 0 else '', u.get('status_view') if k == 0 else '', _xd(p.get('due')),
                                      p.get('file') or (('нет: ' + p['expected']) if p.get('expected') and p.get('num') else ''), '; '.join(p.get('errors') or [])])
        for row in ws.iter_rows(min_row=2):
            for cell in row:
                cell.border = Border(top=thin, bottom=thin, left=thin, right=thin)
                cell.alignment = Alignment(wrap_text=True, vertical='top')
                if isinstance(cell.value, (date, datetime)):
                    cell.number_format = 'DD.MM.YYYY'
                if cell.column in (4, 12, 17, 18) and isinstance(cell.value, (int, float)):
                    cell.number_format = '#,##0.00'
        from openpyxl.utils import get_column_letter
        for i, w in enumerate([8, 40, 26, 14, 22, 14, 16, 12, 14, 5, 28, 14, 12, 14, 12, 12, 14, 14, 14, 12, 26, 40], 1):
            ws.column_dimensions[get_column_letter(i)].width = w
        ws.freeze_panes = 'B2'
        ws.auto_filter.ref = f"A1:{get_column_letter(len(heads))}{ws.max_row}"
    buf = io.BytesIO()
    wb.save(buf)
    return buf.getvalue()


def _xd(v):
    try:
        return date.fromisoformat(v) if v else ''
    except (TypeError, ValueError):
        return v


def ovrk_payload():
    data, idx, free = ovrk_all()
    return {'ok': True, 'rows': data['rows'], 'staff': ОВРК_СОТРУДНИКИ, 'statuses': ОВРК_СТАТУСЫ,
            'settings': {'pp_days': ОВРК_ДНЕЙ_ПП, 'upd_days': ОВРК_ДНЕЙ_УПД, 'workdays': ОВРК_РАБОЧИЕ_ДНИ, 'soon': ОВРК_ПРЕДУПРЕЖДАТЬ_ЗА,
                         'contract_soon': ОВРК_СРОК_ДОГОВОРА_ЗА, 'folder': str(pp_folder()), 'template': ОВРК_ШАБЛОН_ИМЕНИ_ПП},
            'files': {'total': len(idx['items']), 'free': free[:300], 'free_n': len(free), 'scanned': datetime.fromtimestamp(idx['at']).strftime('%H:%M:%S') if idx['at'] else ''},
            'holidays': ПРАЗДНИКИ}


# ============================================================
# ВЕБ-СЕРВЕР
# ============================================================

# =====================================================================
# ПОДГОТОВКА ИЗВЕЩЕНИЯ ОАО — модуль «Подготовка извещения» встроен способом 2
# (VSTRAIVANIE.md): ядро модуля (папка «Модуль извещения/dokumentaciya») вызывается
# отсюда, экраны — вкладка ОАО «Подготовка извещения». Код ядра не меняется:
# новую версию модуля — просто заменить папку «Модуль извещения».
# Пять точек подключения — класс _IzvTochki (настройки — из панели; распознавание PDF,
# данные проверки заявки, сопоставление столбцов, ИИ — пока «выключено»).
# Данные: «Панель/Подготовка извещения/» — Карточки (карточки закупок), Папки закупок
# (файлы заявки и готовые документы), Справочники (копия справочников модуля при первом запуске).
# =====================================================================
ПАПКА_МОДУЛЯ_ИЗВЕЩЕНИЯ = Path(__file__).resolve().parent / 'Модуль извещения'
ИЗВ_БИБЛИОТЕКИ = 'pip install "docxtpl[subdoc]" xlrd'
_IZV = {'mod': None, 'err': None, 'n': None, 'key': None}
_IZV_LOCK = threading.RLock()


class _IzvTochki:
    """Пять точек подключения модуля (раздел 14 ТЗ модуля) — от панели."""
    VYKLYUCHENO = 'выключено'
    NEDOSTUPEN = 'недоступен'

    def nastrojki(self):
        d = izv_dir()
        return {'put_dannyh': ПАПКА_МОДУЛЯ_ИЗВЕЩЕНИЯ / 'dannye', 'put_obshchih_spravochnikov': d / 'Справочники',
                'put_obshchih_zakupok': None, 'put_zakupok': d / 'Карточки', 'polzovatel': None, 'port': None,
                'versiya': izv_versiya()}

    def raspoznannyj_tekst(self, put_fajla):          # 2. OCR-сервер — пока не подключён
        return self.VYKLYUCHENO

    def dannye_proverki_zayavki(self, put_zayavki):   # 3. данные проверки заявки — позже из реестра ОПАиЗ
        return self.VYKLYUCHENO

    def sopostavlenie_stolbcov(self, zagolovki):      # 4. сопоставление столбцов — пока как в заявке
        return self.VYKLYUCHENO

    def vyzov_ii(self, vopros):                       # 5. ИИ — пока не подключён
        return self.VYKLYUCHENO


def izv_dir():
    return ПАПКА_ПАНЕЛИ / 'Подготовка извещения'


def izv_versiya():
    try:
        import configparser
        c = configparser.ConfigParser()
        c.read(ПАПКА_МОДУЛЯ_ИЗВЕЩЕНИЯ / 'config.ini', encoding='utf-8')
        return c.get('programma', 'versiya', fallback='')
    except Exception:
        return ''


def izv_core():
    """(yadro, prosmotr_docx, Nastrojki). Модуль грузится один раз; без библиотек — понятная ошибка."""
    with _IZV_LOCK:
        if _IZV['mod'] is None and _IZV['err'] is None:
            base = ПАПКА_МОДУЛЯ_ИЗВЕЩЕНИЯ
            try:
                if not (base / 'dokumentaciya' / 'yadro.py').exists():
                    raise ImportError(f'нет папки модуля «{base}»')
                for p in (base / '_библиотеки', base / 'lokalnyj_vhod', base / 'dokumentaciya'):
                    if p.exists() and str(p) not in sys.path:
                        sys.path.insert(0, str(p))
                import yadro as _yadro            # noqa: E402 — ядро модуля
                import prosmotr_docx as _pd       # noqa: E402 — docx → HTML для просмотра
                _IZV['mod'] = (_yadro, _pd)
            except ImportError as e:
                miss = getattr(e, 'name', '') or ''
                _IZV['err'] = (f'Подготовка извещения не запущена: не хватает библиотеки «{miss}». Установите: {ИЗВ_БИБЛИОТЕКИ} — и перезапустите панель.'
                               if miss and miss not in ('yadro', 'prosmotr_docx') else f'Подготовка извещения не запущена: {e}')
        if _IZV['err']:
            raise ValueError(_IZV['err'])
        yadro, pd = _IZV['mod']
        d = izv_dir()
        if _IZV['key'] != str(d):
            sp = d / 'Справочники'
            if not sp.exists():
                shutil.copytree(ПАПКА_МОДУЛЯ_ИЗВЕЩЕНИЯ / 'dannye' / 'spravochniki', sp)
            (d / 'Папки закупок').mkdir(parents=True, exist_ok=True)
            _IZV['n'] = yadro.Nastrojki(ПАПКА_МОДУЛЯ_ИЗВЕЩЕНИЯ / 'dannye', put_zakupok=d / 'Карточки', tochki=_IzvTochki(),
                                        put_obshchih_spravochnikov=sp)
            _IZV['key'] = str(d)
        return yadro, pd, _IZV['n']


def izv_can(user):
    return bool(user) and (user.get('admin') or user.get('dept') == 'ОАО')


def _izv_staff(yadro, n):
    try:
        from izvlechenie_excel import zagruzit_sotrudnikov
        return list(zagruzit_sotrudnikov(n.sp('Сотрудники отдела.xlsx')).keys())
    except Exception:
        return []


def izv_me(yadro, n, user):
    """ФИО сотрудника для модуля (полностью, как в «Сотрудники отдела.xlsx») — по «Фамилия И.О.» панели."""
    fio = (user or {}).get('fio') or ''
    if not fio:
        return None
    for full in _izv_staff(yadro, n):
        if yadro.sokratit_fio(full) == fio or full == fio:
            return full
    return fio


def _izv_short(yadro, fio):
    return yadro.sokratit_fio(fio) if fio else ''


def izv_rights(yadro, n, user, z):
    """Права на закупку: сотрудник ОАО — свои; руководитель (администратор) — все, чужие только для просмотра;
    без входа («Все права (демо)») — всё."""
    if not izv_can(user):
        return {'see': False, 'edit': False, 'why': 'Подготовка извещения — для сотрудников ОАО'}
    me = izv_me(yadro, n, user)
    own = not z.get('sotrudnik') or (me and _izv_short(yadro, z.get('sotrudnik')) == _izv_short(yadro, me))
    if not user.get('fio'):           # демо «Все права» — может всё
        return {'see': True, 'edit': True, 'why': ''}
    if own:
        return {'see': True, 'edit': True, 'why': ''}
    if user.get('admin'):
        return {'see': True, 'edit': False, 'why': f'Закупку ведёт {_izv_short(yadro, z.get("sotrudnik"))} — у вас только просмотр («Передать…» — сменить сотрудника)'}
    return {'see': False, 'edit': False, 'why': 'Это закупка другого сотрудника'}


def _izv_kto(user):
    return {'fio': (user or {}).get('fio') or 'панель', 'komp': (user or {}).get('login') or 'demo'}


def _izv_chto_dalshe(yadro, n, z):
    if z.get('rashozhdeniya'):
        return 'отдельные файлы не совпали с заявкой', 'warn'
    if z.get('etap') == 'na_soglasovanii':
        s = f"с {date.fromisoformat(z['data_etapa']):%d.%m} · " if z.get('data_etapa') else ''
        try:
            if yadro.najti_izmeneniya_zayavki(n, z['id'])['est_izmeneniya']:
                return s + 'заявка изменилась — посмотрите изменения', 'warn'
        except Exception:
            pass
        return s + 'на согласовании — ждёт решения служб', 'wait'
    if z.get('etap') == 'razmeshchenie':
        return 'идёт размещение', 'ok'
    pr = z.get('proverka') or {}
    k = len(pr.get('reshit') or [])
    return (f'осталось решить: {k}', 'warn') if k else ('готово — сформируйте на согласование', 'ok')


def izv_list(user):
    yadro, _pd, n = izv_core()
    me = izv_me(yadro, n, user)
    out = []
    for z in yadro.spisok_zakupok(n):
        if not z.get('karta'):
            continue
        r = izv_rights(yadro, n, user, z)
        if not r['see']:
            continue
        if z.get('proverka') is None and (z.get('karta') or {}).get('znacheniya'):
            try:
                yadro.proverit(n, z['id'])
                z = yadro._zagruzit(n, z['id'])
            except Exception:
                pass
        znach = (z.get('karta') or {}).get('znacheniya') or {}
        t, cls = _izv_chto_dalshe(yadro, n, z)
        out.append({'id': z['id'], 'nomer': z.get('nomer_zakupki') or '', 'predmet': znach.get('predmet_im') or '',
                    'nmcd': znach.get('nmcd') or '', 'zayavka': yadro.format_nomer_i_data_zayavki(znach.get('_nomer_i_data_zayavki')) or '',
                    'sotrudnik': _izv_short(yadro, z.get('sotrudnik')), 'own': bool(me) and _izv_short(yadro, z.get('sotrudnik')) == _izv_short(yadro, me),
                    'etap': z.get('etap') or 'chernovik', 'etap_t': yadro.ETAPY_ZAKUPKI.get(z.get('etap') or 'chernovik', ''),
                    'chto': t, 'cls': cls, 'izmeneno': z.get('izmeneno') or '', 'edit': r['edit']})
    order = {'chernovik': 0, 'na_soglasovanii': 1, 'razmeshchenie': 2}
    out.sort(key=lambda x: (order.get(x['etap'], 9), x['nomer']))
    return {'ok': True, 'items': out, 'me': _izv_short(yadro, me), 'boss': bool(user.get('admin')), 'versiya': izv_versiya(),
            'staff': [_izv_short(yadro, f) for f in _izv_staff(yadro, n)],
            'warn': n.preduprezhdenie_spravochniki or ''}


def _izv_safe(name):
    name = re.sub(r'[\\/:*?"<>|]+', '-', str(name or '')).strip(' .')
    return name[:80] or 'Закупка'


def _izv_save_files(folder, files):
    folder.mkdir(parents=True, exist_ok=True)
    saved = []
    for f in files or []:
        nm = Path(str(f.get('name') or 'файл')).name
        if not nm or nm.startswith('.'):
            continue
        p = folder / nm
        k = 2
        while p.exists():
            p = folder / f'{Path(nm).stem} ({k}){Path(nm).suffix}'
            k += 1
        p.write_bytes(base64.b64decode(f.get('b64') or ''))
        saved.append(p.name)
    return saved


def _izv_docs(yadro, folder, proverka):
    return [{'imya': d['imya'], 'put': str(d['put']), 'rol': d.get('rol') or '', 'oshibka': d.get('oshibka_chteniya') or '',
             'gde': d.get('gde') or ''} for d in proverka.get('dokumenty') or []]


def izv_new(data, user):
    """Новая закупка: файлы заявки (и ТЗ, расчёт…) → папка закупки → проверка папки →
    карточка сразу или экран выбора ролей файлов (как «Новая закупка» модуля)."""
    yadro, _pd, n = izv_core()
    if not izv_can(user):
        raise ValueError('Подготовка извещения — для сотрудников ОАО')
    nomer = str(data.get('nomer') or '').strip()
    folder = Path(data['folder']) if data.get('folder') else None
    root = (izv_dir() / 'Папки закупок').resolve()
    if folder is not None:
        folder = folder.resolve()
        if root not in folder.parents:
            raise ValueError('Папка закупки не найдена')
    else:
        if not data.get('files'):
            raise ValueError('Добавьте файлы заявки')
        base = _izv_safe(nomer or f'Закупка {datetime.now():%d.%m %H-%M}')
        folder = root / base
        k = 2
        while folder.exists():
            folder = root / f'{base} ({k})'
            k += 1
        _izv_save_files(folder, data.get('files'))
    roli = {str(k): v for k, v in (data.get('roli') or {}).items() if v in yadro.ROLI_PODPISI}
    me = izv_me(yadro, n, user)
    if not roli:
        est = yadro.najti_po_papke(n, folder)
        if est:
            return {'ok': True, 'id': est['id']}
    pr = yadro.proverit_papku(n, folder, me, roli or None)
    if (pr.get('mozhno_srazu') and not roli) or (data.get('create') and not pr.get('oshibka_zayavki')):
        try:
            s = yadro.otkryt_kartochku(n, folder, me, nomer_zakupki=nomer or None, roli=roli or None)
        except yadro.ZayavkaNeProchitana as e:
            return {'ok': True, 'roles': True, 'folder': str(folder), 'nomer': nomer, 'oshibka_zayavki': str(e),
                    'dokumenty': _izv_docs(yadro, folder, pr), 'roli': yadro.ROLI_PODPISI, 'neopredeleny': pr.get('neopredeleny') or []}
        yadro.proverit(n, s['id'])
        log('edit', f'Подготовка извещения: новая закупка {s.get("nomer_zakupki") or folder.name}', user=(user or {}).get('fio') or 'панель')
        return {'ok': True, 'id': s['id'], 'rashozhdeniya': bool(s.get('rashozhdeniya'))}
    return {'ok': True, 'roles': True, 'folder': str(folder), 'nomer': nomer or yadro.nomer_iz_nazvaniya_papki(folder.name),
            'oshibka_zayavki': pr.get('oshibka_zayavki') or '', 'dokumenty': _izv_docs(yadro, folder, pr),
            'roli': yadro.ROLI_PODPISI, 'neopredeleny': pr.get('neopredeleny') or [], 'rashozhdeniya': bool(pr.get('rashozhdeniya'))}


def _izv_load(yadro, n, zid, user, edit=False):
    z = yadro._zagruzit(n, str(zid or ''))
    if z is None:
        raise ValueError('Закупка не найдена — возможно, она уже размещена')
    r = izv_rights(yadro, n, user, z)
    if not r['see'] or (edit and not r['edit']):
        raise ValueError(r['why'] or 'Только просмотр')
    if edit:
        drugoj = yadro.kto_otkryl(n, z['id'], _izv_kto(user))
        if drugoj:
            raise ValueError(f'Сейчас карточку правит {drugoj.get("fio")} — у вас только просмотр')
    return z, r


def izv_card(zid, user, fresh=False):
    """Всё для экрана карточки (как _ekran_kartochki в lokalnyj_vhod/server.py)."""
    yadro, _pd, n = izv_core()
    z, r = _izv_load(yadro, n, zid, user)
    zid = z['id']
    if r['edit']:
        drugoj = yadro.zanyat_kartochku(n, zid, _izv_kto(user))
        if drugoj:
            r = {'see': True, 'edit': False, 'why': f'Сейчас открыта у {drugoj.get("fio")} — только просмотр'}
    karta = z.get('karta') or {}
    if r['edit'] and karta.get('znacheniya') and (z.get('versiya_chteniya') or 0) < yadro.VERSIYA_CHTENIYA:
        yadro.dochitat_iz_zayavki(n, zid)
    izm = {'est_izmeneniya': False}
    if fresh and r['edit'] and z.get('snimok_zayavki'):
        try:
            izm = yadro.najti_izmeneniya_zayavki(n, zid)
        except Exception:
            izm = {'est_izmeneniya': False}
    proverka = yadro.proverit(n, zid) if karta.get('znacheniya') else {'reshit': [], 'oshibki': [], 'preduprezhdeniya': [], 'opechatki': [], 'mozhno_sformirovat': False}
    z = yadro._zagruzit(n, zid)
    soobshchenie = z.pop('soobshchenie', None)
    if soobshchenie:
        yadro._sohranit(n, zid, z)
    karta = z.get('karta') or {}
    znach = karta.get('znacheniya') or {}
    import raschety
    formy = yadro.sborka.zagruzit_formy_dogovora(n.sp(yadro.SPRAVOCHNIK_FORM_DOGOVORA))
    forma_podskazka = (yadro.sborka.podskazat_formu_dogovora(znach['predmet_im'], formy) or {}).get('nazvanie') if znach.get('predmet_im') else None
    try:
        tz_vid, tz_stroki, tz_vse, tz_skr = yadro.postroit_tablicu_tz(n, z)
    except Exception:
        tz_vid, tz_stroki, tz_vse, tz_skr = [], [], [], []
    pozicii = karta.get('pozicii') or []
    sluzh = {'нкми', 'фф омс', 'источник финансирования'}
    poz_h = [h for h in (list(pozicii[0].keys()) if pozicii else []) if h.lower() not in sluzh]
    poz_rows = [[str((p.get(h) or {}).get('znachenie', '')) for h in poz_h] for p in pozicii]
    itog = None
    st_sum = next((h for h in poz_h if 'общая сумма' in h.lower()), None)
    if st_sum and pozicii:
        itog = sum(raschety.chislo(p[st_sum]['znachenie']) for p in pozicii if p.get(st_sum, {}).get('znachenie'))
    itog_ok = itog is not None and bool(znach.get('nmcd')) and abs(itog - raschety.chislo(znach['nmcd'])) <= raschety.DOPUSK_NDS
    stavka = summa_nds = None
    if znach.get('nmcd') and 'в т.ч' in (znach.get('nds_tekst') or '').lower():
        stavka = raschety.izvlech_stavku_nds(pozicii)
        if stavka is not None:
            summa_nds = yadro.format_chislo(raschety.summa_nds(raschety.chislo(znach['nmcd']), stavka))
    nmck_ok = None
    rs = znach.get('nmck_raschet') or {}
    if rs.get('kp'):
        pr_ = raschety.rasschitat_nmck_po_kp([raschety.chislo(k['summa']) for k in rs['kp']])
        nmck_ok = all(p not in rs or raschety.sverit_s_dopuskom(raschety.chislo(rs[p]), v)
                      for p, v in (('srednyaya', pr_.srednyaya), ('sko', pr_.sko), ('koef_var', pr_.koef_var)))
    me = izv_me(yadro, n, user)
    staff = yadro.sotrudniki_po_alfavitu(_izv_staff(yadro, n), me)
    ist = karta.get('istochniki') or {}
    kontakt_vruchnuyu = (ist.get('kontakt_fio') or {}).get('fajl') == 'sotrudnik' or znach.get('kontakt_fio') not in staff
    podpisanty = yadro.zagruzit_podpisantov_spiska(n, rol='utverzhdaet')
    plosh = yadro.zagruzit_ploshchadki(n) or {}
    hint_key = izv_plosh_key(n, znach.get('_ploshchadka_podskazka') or '', plosh)
    fajly = {}
    for k, v in (z.get('poslednie_fajly') or {}).items():
        if k in ('izveshchenie', 'dogovor') and v:
            fajly[k] = Path(v).name
    v_papke = sorted(p.name for p in Path(z['put_papki']).iterdir() if p.is_file() and p.suffix.lower() == '.docx'
                     and p.name.startswith(('Аукцион.',))) if Path(z['put_papki']).exists() else []
    return {
        'ok': True, 'id': zid, 'nomer': z.get('nomer_zakupki') or '', 'etap': z.get('etap') or 'chernovik',
        'etap_t': yadro.ETAPY_ZAKUPKI.get(z.get('etap') or 'chernovik', ''), 'data_etapa': z.get('data_etapa') or '',
        'sotrudnik': _izv_short(yadro, z.get('sotrudnik')), 'edit': r['edit'], 'why': r['why'],
        'peredat': [x for x in (_izv_short(yadro, f) for f in _izv_staff(yadro, n)) if x != _izv_short(yadro, z.get('sotrudnik'))] if user.get('admin') else None,
        'forma_dogovora': z.get('forma_dogovora') or '', 'formy': [{'nazvanie': f.get('nazvanie'), 'zaglushka': bool(f.get('zaglushka'))} for f in formy],
        'forma_podskazka': forma_podskazka, 'znach': znach,
        'ist': {k: {'fajl': (v or {}).get('fajl', ''), 'citata': (v or {}).get('citata', '')} for k, v in ist.items() if isinstance(v, dict)},
        'zayavka': yadro.format_nomer_i_data_zayavki(znach.get('_nomer_i_data_zayavki')) or '',
        'dokumenty': [{'imya': d.get('imya'), 'put': str(d.get('put')), 'rol': d.get('rol') or '', 'rol_t': yadro.ROLI_PODPISI.get(d.get('rol') or '', ''),
                       'chto': yadro.CHTO_BERYOTSYA_PO_ROLI.get(d.get('rol') or '', ''), 'pdf': str(d.get('imya', '')).lower().endswith('.pdf')}
                      for d in z.get('dokumenty') or []],
        'roli': yadro.ROLI_PODPISI, 'rashozhdeniya': z.get('rashozhdeniya') or {},
        'proverka': {k: proverka.get(k) for k in ('reshit', 'oshibki', 'preduprezhdeniya', 'opechatki', 'mozhno_sformirovat', 'gotovo',
                                                   'otklonenie_nmcd', 'otklonenie_nmcd_storona')},
        'soobshchenie': soobshchenie, 'izmeneniya': bool(izm.get('est_izmeneniya')),
        'ploshchadki': plosh, 'ploshchadka_podskazka': znach.get('_ploshchadka_podskazka') or '', 'ploshchadka_hint_key': hint_key,
        'podpisanty': podpisanty, 'soglasuyushchie': yadro.zagruzit_soglasuyushchih(n),
        'staff': staff, 'me': me or '', 'kontakt_vruchnuyu': kontakt_vruchnuyu,
        'pozicii': {'h': poz_h, 'rows': poz_rows, 'itog': yadro.format_chislo(itog) if itog is not None else None, 'itog_ok': itog_ok},
        'tz': {'h': tz_vid, 'rows': tz_stroki, 'skrytye': tz_skr, 'dobavlennye': list((z.get('tz_dobavlennye') or {}).keys())},
        'stavka_nds': stavka, 'summa_nds': summa_nds, 'nmck_ok': nmck_ok,
        'fajly': fajly, 'v_papke': v_papke, 'ocr': yadro.PODPIS_OCR, 'ii': yadro.PODPIS_II,
        'versiya': izv_versiya(), 'warn': n.preduprezhdenie_spravochniki or '',
    }


def izv_plosh_key(n, hint, plosh):
    """«Как в заявке»: площадка из заявки → адрес из справочника — по адресу или по столбцу «Как пишут в заявке»."""
    norm = lambda x: re.sub(r'^https?://', '', str(x or '').strip().lower()).rstrip('/')
    h = norm(hint)
    if not h:
        return ''
    for k in plosh:
        if norm(k) == h:
            return k
    try:
        from openpyxl import load_workbook as _lw
        ws = _lw(n.sp('Электронные площадки.xlsx'), data_only=True)['Площадки']
        for adres, _nm, kak in ws.iter_rows(min_row=2, max_col=3, values_only=True):
            if adres and any(norm(x) == h for x in str(kak or '').split(',') if x.strip()):
                return str(adres).strip()
    except Exception:
        pass
    return ''


def izv_preview(data, user):
    yadro, pd, n = izv_core()
    z, _r = _izv_load(yadro, n, data.get('id'), user, edit=True)
    etap = 'razmeshchenie' if data.get('etap') == 'razmeshchenie' else 'soglasovanie'
    d_razm = None
    if etap == 'razmeshchenie':
        d_razm = date.fromisoformat(z['d_razmeshcheniya_vybrano']) if z.get('d_razmeshcheniya_vybrano') else yadro.data_razmeshcheniya_po_umolchaniyu(n)[0]
    pr = yadro.podgotovit_prosmotr(n, z['id'], etap=etap, d_razmeshcheniya=d_razm, dazhe_s_oshibkami=True)
    if not pr.get('ok'):
        return {'ok': False, 'message': pr.get('oshibka') or 'Документ не собрался — посмотрите «Решить» в карточке'}
    z = yadro._zagruzit(n, z['id'])
    podsv = pd.polya_dlya_podsvetki(z)
    proverka = pr.get('proverka') or {}
    return {'ok': True, 'etap': etap, 'imya_izv': pr.get('imya_izveshcheniya'), 'imya_dog': pr.get('imya_dogovora'),
            'html_izv': pd.docx_v_html(pr['izveshchenie'], podsv),
            'html_dog': pd.docx_v_html(pr['dogovor'], podsv) if pr.get('dogovor') else '',
            'oshibki': [o.get('tekst') if isinstance(o, dict) else str(o) for o in proverka.get('oshibki') or []],
            'preduprezhdeniya': [o.get('tekst') if isinstance(o, dict) else str(o) for o in proverka.get('preduprezhdeniya') or []],
            'oshibki_dokumenta': pr.get('oshibki_dokumenta') or [],
            'mozhno': bool(proverka.get('mozhno_sformirovat')) and not pr.get('oshibki_dokumenta')}


def izv_razm(zid, user):
    """Экран «Размещение»: дата размещения, даты этапов по производственному календарю."""
    yadro, _pd, n = izv_core()
    z, r = _izv_load(yadro, n, zid, user)
    perenesena = False
    if z.get('d_razmeshcheniya_vybrano'):
        d = date.fromisoformat(z['d_razmeshcheniya_vybrano'])
    else:
        d, perenesena = yadro.data_razmeshcheniya_po_umolchaniyu(n)
    tp, ta = z.get('t_podacha_vybrano') or '09:00', z.get('t_aukcion_vybrano') or '11:00'
    out = {'ok': True, 'id': z['id'], 'nomer': z.get('nomer_zakupki') or '', 'etap': z.get('etap'), 'edit': r['edit'],
           'd_razm': d.strftime('%d.%m.%Y'), 'd_razm_iso': d.isoformat(), 'perenesena': perenesena, 't_podacha': tp, 't_aukcion': ta,
           'daty': None, 'oshibka': ''}
    try:
        kal = yadro.zagruzit_kalendar(n.sp('Производственный календарь.xlsx'))
        rr = yadro.rasschitat_daty(d, kal)
        if z.get('d_podacha_do_vybrano'):
            dp = date.fromisoformat(z['d_podacha_do_vybrano'])
            ost = yadro.rasschitat_ostalnye_daty(dp, kal)
            rr = yadro.DatyIzveshcheniya(rr.d_razmeshcheniya, ost.d_zaprosy_do, dp, ost.d_rassmotrenie, ost.d_aukcion, ost.d_itogi)
        dd = yadro.format_dannye_dlya_shablona(rr, tp, ta)
        out['daty'] = {k: (re.sub(r'г\.?$', '', str(v)) if k.startswith('d_') else v) for k, v in dd.items()}
        out['iso'] = {k: getattr(rr, k).isoformat() for k in ('d_razmeshcheniya', 'd_zaprosy_do', 'd_podacha_do', 'd_rassmotrenie', 'd_aukcion', 'd_itogi')}
        pervaya = yadro.pervaya_dostupnaya_data_podachi(n, d)
        out['pervaya_podacha'] = pervaya.isoformat()
        out['poyasnenie'] = yadro.poyasnenie_sroka_podachi(n, d)
    except Exception as e:      # нет календаря на год, дата размещения — нерабочий день
        out['oshibka'] = str(e)
    return out


def izv_razm_set(data, user):
    yadro, _pd, n = izv_core()
    z, _r = _izv_load(yadro, n, data.get('id'), user, edit=True)
    kal = yadro.zagruzit_kalendar(n.sp('Производственный календарь.xlsx'))
    if data.get('d_razm'):
        d = date.fromisoformat(data['d_razm'])
        if not kal.rabochij_den(d):
            raise ValueError(f'{d:%d.%m.%Y} — нерабочий день, выберите рабочий')
        if z.get('d_razmeshcheniya_vybrano') != d.isoformat():
            z.pop('d_podacha_do_vybrano', None)       # другая дата размещения — срок подачи считается заново
        z['d_razmeshcheniya_vybrano'] = d.isoformat()
    for k in ('t_podacha', 't_aukcion'):
        if data.get(k):
            if not re.fullmatch(r'\d{1,2}:\d{2}', data[k]):
                raise ValueError('Время — в виде 09:00')
            z[k + '_vybrano'] = data[k]
    if 'd_podacha' in data:
        if data['d_podacha']:
            dp = date.fromisoformat(data['d_podacha'])
            d = date.fromisoformat(z['d_razmeshcheniya_vybrano']) if z.get('d_razmeshcheniya_vybrano') else yadro.data_razmeshcheniya_po_umolchaniyu(n)[0]
            first = yadro.pervaya_dostupnaya_data_podachi(n, d)
            if dp < first or not kal.rabochij_den(dp):
                raise ValueError(f'Срок подачи — не раньше {first:%d.%m.%Y} и в рабочий день ({yadro.poyasnenie_sroka_podachi(n, d)})')
            z['d_podacha_do_vybrano'] = dp.isoformat()
        else:
            z.pop('d_podacha_do_vybrano', None)
    yadro._sohranit(n, z['id'], z)
    return izv_razm(z['id'], user)


def izv_placed(data, user):
    """«Закупка размещена»: данные для формы «Извещение» панели (то, что формируется после публикации),
    карточка удаляется из модуля (файлы в папке закупки остаются)."""
    yadro, _pd, n = izv_core()
    z, _r = _izv_load(yadro, n, data.get('id'), user, edit=True)
    znach = (z.get('karta') or {}).get('znacheniya') or {}
    info = izv_razm(z['id'], user)
    iso = info.get('iso') or {}
    fmt = lambda k: date.fromisoformat(iso[k]).strftime('%d.%m.%Y') if iso.get(k) else ''
    plosh = (yadro.zagruzit_ploshchadki(n) or {}).get(znach.get('ploshchadka') or '', znach.get('ploshchadka') or '')
    prefill = {'oao': z.get('nomer_zakupki') or '', 'name': znach.get('predmet_im') or '', 'price': znach.get('nmcd') or '',
               'publish': iso.get('d_razmeshcheniya', ''), 'bid': iso.get('d_podacha_do', ''), 'review': iso.get('d_rassmotrenie', ''),
               'trade': iso.get('d_aukcion', ''), 'result': iso.get('d_itogi', ''), 'responsible': _izv_short(yadro, z.get('sotrudnik')),
               'site_url': znach.get('ploshchadka') or '', 'site': plosh, 'kind': 'k', 'dates_text': {k: fmt(k) for k in iso}}
    folder = z.get('put_papki')
    yadro.zakupka_razmeshchena(n, z['id'])
    log('edit', f'Подготовка извещения: закупка {z.get("nomer_zakupki") or ""} размещена (документы — в «{folder}»)', user=(user or {}).get('fio') or 'панель')
    return {'ok': True, 'prefill': prefill}


def izv_api(path, data, user):
    """POST /api/izv/… → ответ (словарь)."""
    if not izv_can(user):
        raise ValueError('Подготовка извещения — для сотрудников ОАО')
    act = path[len('/api/izv/'):]
    if act == 'list':
        return izv_list(user)
    if act == 'new':
        return izv_new(data, user)
    if act == 'card':
        return izv_card(data.get('id'), user, fresh=bool(data.get('fresh')))
    if act == 'preview':
        return izv_preview(data, user)
    if act == 'razm':
        return izv_razm(data.get('id'), user)
    if act == 'razm_set':
        return izv_razm_set(data, user)
    if act == 'placed':
        return izv_placed(data, user)
    yadro, _pd, n = izv_core()
    if act == 'release':
        z = yadro._zagruzit(n, str(data.get('id') or ''))
        if z:
            yadro.osvobodit_kartochku(n, z['id'], _izv_kto(user))
        return {'ok': True}
    z, _r = _izv_load(yadro, n, data.get('id'), user, edit=act not in ('changes',))
    zid = z['id']
    if act == 'hold':
        return {'ok': not yadro.zanyat_kartochku(n, zid, _izv_kto(user))}
    if act == 'set':
        pole = str(data.get('pole') or '')
        if not pole:
            raise ValueError('Нет поля')
        yadro.izmenit_pole(n, zid, pole, data.get('znachenie'))
    elif act == 'many':                     # несколько полей подряд (подписант: должность + ФИО)
        for it in data.get('items') or []:
            yadro.izmenit_pole(n, zid, str(it.get('pole') or ''), it.get('znachenie'))
    elif act == 'refill':
        if z.get('snimok_zayavki'):
            izm = yadro.najti_izmeneniya_zayavki(n, zid)
            if izm['est_izmeneniya']:
                return {'ok': True, 'izmeneniya': True}
            got = yadro.dochitat_iz_zayavki(n, zid, soobshchit=True)
            if not got:
                c = izv_card(zid, user)
                c['toast'] = 'Заявка не менялась'
                return c
        else:
            yadro.zapolnit_iz_zayavki(n, zid, izv_me(yadro, n, user))
    elif act == 'changes':
        izm = yadro.najti_izmeneniya_zayavki(n, zid)
        return {'ok': True, 'izm': {'est_izmeneniya': izm['est_izmeneniya'], 'polya': izm['polya'], 'pozicii': izm['pozicii']}}
    elif act == 'apply_changes':
        yadro.primenit_izmeneniya_zayavki(n, zid, prinyat=bool(data.get('prinyat')), vybor_konfliktov=data.get('vybor') or {})
    elif act == 'files_add':
        _izv_save_files(Path(z['put_papki']), data.get('files'))
        yadro.pereschitat_dokumenty(n, zid)
    elif act == 'tz':
        dej = data.get('dejstvie')
        if dej == 'znachenie':
            yadro.tz_izmenit_znachenie(n, zid, data.get('nazvanie', ''), int(data.get('indeks') or 0), data.get('znachenie', ''))
        elif dej in ('ubrat', 'vernut', 'peremestit', 'sbros', 'dobavit'):
            yadro.tz_izmenit(n, zid, dej, data.get('nazvanie', ''), data.get('napravlenie'))
    elif act == 'save':
        res = yadro.sohranit_prosmotr(n, zid, data.get('zamena') or None)
        if res.get('ok'):
            log('edit', f'Подготовка извещения: {z.get("nomer_zakupki") or ""} — сохранено «{Path(res["izveshchenie"]).name}»',
                user=(user or {}).get('fio') or 'панель')
        return {'ok': bool(res.get('ok')), 'nuzhno_reshenie_fajl': res.get('nuzhno_reshenie_fajl'), 'pravili_v_word': res.get('pravili_v_word') or [],
                'otmeneno': bool(res.get('otmeneno')), 'message': res.get('oshibka') or '',
                'izveshchenie': Path(res['izveshchenie']).name if res.get('izveshchenie') else '',
                'dogovor': Path(res['dogovor']).name if res.get('dogovor') else '', 'etap': res.get('etap') or ''}
    elif act == 'peredat':
        if not user.get('admin'):
            raise ValueError('Передать закупку может руководитель')
        full = next((f for f in _izv_staff(yadro, n) if yadro.sokratit_fio(f) == data.get('fio') or f == data.get('fio')), data.get('fio'))
        yadro.peredat_zakupku(n, zid, full)
        return {'ok': True}
    elif act == 'smp':
        return izv_smp(z)
    else:
        raise ValueError('Нет такой команды')
    return izv_card(zid, user)


def izv_smp(z):
    """Проверка СМП по позициям извещения (ОАО проверяет на своём этапе) — та же логика, что во вкладке ОПАиЗ."""
    pozicii = (z.get('karta') or {}).get('pozicii') or []
    items = []
    for p in pozicii:
        name = next((str(v.get('znachenie') or '') for h, v in p.items() if 'наимен' in h.lower() or 'характерист' in h.lower() or h.lower() == 'мнн'), '')
        okpd = next((str(v.get('znachenie') or '') for h, v in p.items() if 'окпд' in h.lower()), '')
        if okpd:
            items.append({'name': name.split('\n')[0][:200], 'okpd': okpd})
    if not items:
        return {'ok': True, 'results': [], 'message': 'В позициях нет кодов ОКПД2'}
    try:
        return {'ok': True, **smp_check(items, 'заявка')}
    except ValueError as e:
        return {'ok': True, 'results': [], 'message': str(e)}


def izv_file(q, user):
    """GET /api/izv/file?id=…&name=… — файл из папки закупки (готовые документы и файлы заявки)."""
    yadro, _pd, n = izv_core()
    z, _r = _izv_load(yadro, n, q.get('id', [''])[0], user)
    root = Path(z['put_papki']).resolve()
    f = (root / q.get('name', [''])[0]).resolve()
    if f.parent != root or not f.is_file():
        raise ValueError('Файл не найден')
    return f


# Блокировка подбора пароля: неудачи по паре (IP, логин), 5 промахов — пауза 15 минут.
LOGIN_FAILS = {}
LOGIN_FAILS_LOCK = threading.Lock()
LOGIN_LOCK_AFTER = 5
LOGIN_LOCK_SECONDS = 15 * 60


def login_lock_key(handler, login):
    return (handler.client_address[0] if handler.client_address else '?', (login or '').strip().lower())


def login_locked_until(key):
    with LOGIN_FAILS_LOCK:
        rec = LOGIN_FAILS.get(key)
        if rec and rec['until'] > time.time():
            return rec['until']
        return 0


def login_register_fail(key):
    with LOGIN_FAILS_LOCK:
        rec = LOGIN_FAILS.setdefault(key, {'fails': 0, 'until': 0})
        rec['fails'] += 1
        if rec['fails'] >= LOGIN_LOCK_AFTER:
            rec['until'] = time.time() + LOGIN_LOCK_SECONDS
            rec['fails'] = 0


def login_register_ok(key):
    with LOGIN_FAILS_LOCK:
        LOGIN_FAILS.pop(key, None)


class Handler(BaseHTTPRequestHandler):
    server_version = 'Reestr/1.0'

    def log_message(self, fmt, *args):   # без шума в консоли на каждый запрос
        pass

    def sec_headers(self):
        """Заголовки безопасности на все ответы панели."""
        self.send_header('X-Content-Type-Options', 'nosniff')
        self.send_header('X-Frame-Options', 'DENY')
        self.send_header('Referrer-Policy', 'same-origin')
        self.send_header('Content-Security-Policy', "default-src 'self' 'unsafe-inline'; img-src 'self' data:")

    def send_json(self, code, obj):
        body = json.dumps(obj, ensure_ascii=False, default=str).encode('utf-8')
        self.send_response(code)
        self.send_header('Content-Type', 'application/json; charset=utf-8')
        self.send_header('Cache-Control', 'no-store')
        self.send_header('Content-Length', str(len(body)))
        self.sec_headers()
        self.end_headers()
        self.wfile.write(body)

    def send_file(self, content, filename, mime):
        self.send_response(200)
        self.send_header('Content-Type', mime)
        self.send_header('Content-Disposition', f"attachment; filename*=UTF-8''{quote(filename)}")
        self.send_header('Content-Length', str(len(content)))
        self.send_header('Cache-Control', 'no-store')
        self.sec_headers()
        self.end_headers()
        self.wfile.write(content)

    def cookie(self, name):
        for part in (self.headers.get('Cookie') or '').split(';'):
            k, _, v = part.strip().partition('=')
            if k == name:
                return v
        return ''

    def current_user(self):
        """Кто за компьютером. Без входа по паролю (демо) — роль из переключателя в шапке."""
        if ВХОД_ПО_ПАРОЛЮ:
            return user_by_session(self.cookie('uoozd'))
        login = (self.headers.get('X-Demo-As') or '').strip()
        u = next((x for x in load_users() if x['login'] == login), None) if login else None
        return u or DEMO_USER

    def need_user(self, path):
        """→ пользователь или None (тогда уже отправлен ответ 401)."""
        u = self.current_user()
        if u or path in ('/', '/index.html', '/api/login', '/api/me'):
            return u or {}
        self.send_json(401, {'ok': False, 'login': True, 'message': 'Войдите в панель'})
        return None

    def read_json(self):
        length = int(self.headers.get('Content-Length') or 0)
        if length > 30 * 1024 * 1024:
            raise ValueError('Слишком большой запрос')
        return json.loads(self.rfile.read(length).decode('utf-8') or '{}')

    def do_GET(self):
        path = urlparse(self.path).path
        try:
            user = self.need_user(path)
            if user is None:
                return
            if path == '/api/me':
                self.send_json(200, {'ok': True, 'user': public_user(user) if user.get('login') else None,
                                     'login_required': ВХОД_ПО_ПАРОЛЮ, 'depts': ОТДЕЛЫ, 'start_dept': СТАРТ_ОТДЕЛ, 'start_demo_as': СТАРТ_ДЕМО_ПОЛЬЗОВАТЕЛЬ,
                                     'demo_users': [public_user(u) for u in load_users()] if not ВХОД_ПО_ПАРОЛЮ else []})
            elif path in ('/', '/index.html'):
                body = PANEL_HTML.encode('utf-8')
                self.send_response(200)
                self.send_header('Content-Type', 'text/html; charset=utf-8')
                self.send_header('Cache-Control', 'no-store')
                self.send_header('Content-Length', str(len(body)))
                self.sec_headers()
                self.end_headers()
                self.wfile.write(body)
            elif path == '/baza-znaniy':
                kb = Path(__file__).resolve().parent / 'База знаний.html'
                if not kb.exists():
                    raise ValueError('Файл «База знаний.html» не найден рядом с панелью')
                body = kb.read_bytes()
                self.send_response(200)
                self.send_header('Content-Type', 'text/html; charset=utf-8')
                self.send_header('Cache-Control', 'no-store')
                self.send_header('Content-Length', str(len(body)))
                self.sec_headers()
                self.end_headers()
                self.wfile.write(body)
            elif path == '/api/data':
                self.send_json(200, build_payload())
            elif path == '/api/item':
                from urllib.parse import parse_qs
                q = parse_qs(urlparse(self.path).query)
                self.send_json(200, handle_item(q.get('number', [''])[0]))
            elif path == '/api/file':
                from urllib.parse import parse_qs
                q = parse_qs(urlparse(self.path).query)
                f = archive_file(q.get('path', [''])[0])
                self.send_file(f.read_bytes(), f.name, 'application/octet-stream')
            elif path == '/api/oz/xlsx':
                from urllib.parse import parse_qs
                q = parse_qs(urlparse(self.path).query)
                t = q.get('table', ['zayavki'])[0]
                if not oz_can(user) or t not in OZ_TABLES:
                    raise ValueError('Нет доступа к реестру ОПАиЗ')
                self.send_file(oz_xlsx(t), f"Реестр ОПАиЗ — {OZ_TABLES[t]['title']} — {date.today():%d.%m.%Y}.xlsx",
                               'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet')
            elif path == '/api/izv/file':
                from urllib.parse import parse_qs
                f = izv_file(parse_qs(urlparse(self.path).query), user)
                mime = 'application/vnd.openxmlformats-officedocument.wordprocessingml.document' if f.suffix.lower() == '.docx' else 'application/octet-stream'
                self.send_file(f.read_bytes(), f.name, mime)
            elif path == '/api/news':
                self.send_json(200, {'ok': True, 'items': sorted(news_load()['items'], key=lambda x: x.get('at', ''), reverse=True)})
            elif path == '/api/notify':
                data_n = notify_load()
                self.send_json(200, {'ok': True, 'items': list(reversed((data_n.get('items') or [])[-400:])),
                                     'settings': {'max': УВЕДОМЛЕНИЯ_МАКС and bool(МАКС_ТОКЕН), 'mail': УВЕДОМЛЕНИЯ_ПОЧТА and bool(ПОЧТА_SMTP), 'demo': УВЕДОМЛЕНИЯ_ДЕМО}})
            elif path in ('/api/catalog/html', '/api/catalog/xlsx', '/api/catalog/info'):
                html_f, xlsx_f = ПАПКА_КАТАЛОГА / 'Каталог.html', ПАПКА_КАТАЛОГА / 'Каталог позиций.xlsx'
                if path == '/api/catalog/info':
                    self.send_json(200, {'ok': True, 'html': html_f.exists(), 'xlsx': xlsx_f.exists(), 'folder': str(ПАПКА_КАТАЛОГА),
                                         'updated': datetime.fromtimestamp(html_f.stat().st_mtime).strftime('%d.%m.%Y %H:%M') if html_f.exists() else ''})
                elif path == '/api/catalog/xlsx':
                    if not xlsx_f.exists():
                        raise ValueError('Каталог ещё не собран')
                    self.send_file(xlsx_f.read_bytes(), xlsx_f.name, 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet')
                else:
                    body = html_f.read_bytes() if html_f.exists() else ('<meta charset="utf-8"><p style="font:16px sans-serif;padding:24px">Каталог ещё не собран. '
                                                                       f'Запустите spec_extract.py и положите «Каталог.html» в папку {ПАПКА_КАТАЛОГА}</p>').encode('utf-8')
                    self.send_response(200)
                    self.send_header('Content-Type', 'text/html; charset=utf-8')
                    self.send_header('Content-Length', str(len(body)))
                    self.send_header('Cache-Control', 'no-store')
                    self.end_headers()
                    self.wfile.write(body)
            elif path == '/api/ovrk/file':
                from urllib.parse import parse_qs
                q = parse_qs(urlparse(self.path).query)
                root = pp_folder().resolve()
                f = (root / q.get('path', [''])[0]).resolve()
                if not ovrk_can(user) or root not in f.parents or not f.is_file():
                    raise ValueError('Файл не найден')
                self.send_file(f.read_bytes(), f.name, 'application/octet-stream')
            elif path == '/api/registry':
                from urllib.parse import parse_qs
                q = parse_qs(urlparse(self.path).query)
                Y = year_obj(int(q['year'][0]) if q.get('year', [''])[0].isdigit() else None)
                if not Y.registry.exists():
                    raise ValueError(f'Реестра {Y.y} ещё нет')
                content = export_sorted(Y.registry)
                self.send_file(content, f'{Y.registry.stem} — {date.today():%d.%m.%Y}.xlsx',
                               'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet')
            else:
                self.send_json(404, {'ok': False, 'message': 'Нет такой страницы'})
        except (BrokenPipeError, ConnectionResetError):
            pass
        except Exception as e:
            self.fail(e)

    def do_POST(self):
        path = urlparse(self.path).path
        try:
            data = self.read_json()
            if path == '/api/login':
                key = login_lock_key(self, data.get('login', ''))
                until = login_locked_until(key)
                if until:
                    self.send_json(429, {'ok': False, 'message': f'Слишком много неудачных попыток. '
                                                                 f'Повторите через {int((until - time.time()) // 60) + 1} мин.'})
                    return
                u = check_login(data.get('login', ''), data.get('password', ''))
                if not u:
                    time.sleep(1)
                    login_register_fail(key)
                    log('auth', f"Неудачный вход: {data.get('login', '')} с {self.client_address[0] if self.client_address else '?'}")
                    self.send_json(401, {'ok': False, 'message': 'Неверный логин или пароль'})
                    return
                login_register_ok(key)
                token = new_session(u['login'])
                body = json.dumps({'ok': True, 'user': public_user(u)}, ensure_ascii=False).encode('utf-8')
                self.send_response(200)
                self.send_header('Content-Type', 'application/json; charset=utf-8')
                self.send_header('Set-Cookie', f'uoozd={token}; Path=/; Max-Age={SESSION_DAYS * 86400}; HttpOnly; SameSite=Lax')
                self.send_header('Content-Length', str(len(body)))
                self.end_headers()
                self.wfile.write(body)
                log('info', f"Вход: {u['fio']}", user=u['fio'])
                return
            user = self.need_user(path)
            if user is None:
                return
            if user.get('fio'):
                data['author'] = user['fio']      # в журнал — тот, кто вошёл
            if path == '/api/logout':
                drop_session(self.cookie('uoozd'))
                self.send_json(200, {'ok': True})
            elif path == '/api/password':
                change_own_password(user, data.get('old', ''), data.get('new', ''))
                self.send_json(200, {'ok': True})
            elif path.startswith('/api/izv/'):
                self.send_json(200, izv_api(path, data, user))
            elif path == '/api/news/save':
                self.send_json(200, {'ok': True, 'item': news_save(data, user if user.get('fio') else {'fio': data.get('author') or 'панель'})})
            elif path == '/api/news/delete':
                news_delete(data.get('id', ''), user)
                self.send_json(200, {'ok': True})
            elif path.startswith('/api/users'):
                if not user.get('admin'):
                    self.send_json(403, {'ok': False, 'message': 'Только для администратора'})
                elif path == '/api/users/save':
                    self.send_json(200, {'ok': True, 'user': save_user(data, user)})
                elif path == '/api/users/delete':
                    delete_user(data.get('login', ''), user)
                    self.send_json(200, {'ok': True})
                else:
                    self.send_json(200, {'ok': True, 'users': [public_user(u) for u in load_users()], 'depts': ОТДЕЛЫ})
            elif path in ('/api/delete', '/api/restore', '/api/deleted'):
                if not user.get('can_delete'):
                    self.send_json(403, {'ok': False, 'message': 'Удалять записи может только назначенный сотрудник'})
                elif path == '/api/deleted':
                    self.send_json(200, {'ok': True, 'items': deleted_list()[::-1]})
                elif path == '/api/restore':
                    rec = soft_delete(data.get('id', ''), '', '', user, restore=True)
                    self.send_json(200, {'ok': True, 'message': f"{rec.get('oao') or rec.get('number')} восстановлена"})
                else:
                    rec = soft_delete(data.get('number', ''), data.get('pub', ''), data.get('reason', ''), user)
                    self.send_json(200, {'ok': True, 'message': f"{rec['oao'] or rec['number']} удалена из реестра {rec['year']}. "
                                                                f"Вернуть можно в «Удалённые записи»."})
            elif path.startswith('/api/ovrk'):
                if not ovrk_can(user):
                    self.send_json(403, {'ok': False, 'message': 'Реестр ОВРК ведут сотрудники ОВРК'})
                elif path == '/api/ovrk':
                    self.send_json(200, ovrk_payload())
                elif path == '/api/ovrk/rescan':
                    pp_index(force=True)
                    self.send_json(200, ovrk_payload())
                elif path == '/api/ovrk/save':
                    c, changed = ovrk_save(data.get('id') or None, data.get('values') or {}, data.get('ver'), user, data.get('note', ''))
                    if changed:
                        log('edit', f"ОВРК: договор {c.get('cnum') or c['id']} " + ('изменён' if data.get('id') else 'добавлен'), user=user.get('fio') or 'панель')
                    self.send_json(200, {'ok': True, 'id': c['id'], 'changed': changed})
                elif path == '/api/ovrk/delete':
                    with OVRK_LOCK:
                        d = ovrk_load()
                        gone = [x for x in d['rows'] if x['id'] == data.get('id')]
                        d['rows'] = [x for x in d['rows'] if x['id'] != data.get('id')]
                        d.setdefault('deleted', []).extend(dict(x, _deleted_by=user.get('fio'), _deleted_at=datetime.now().isoformat(timespec='seconds')) for x in gone)
                        ovrk_save_all(d)
                    self.send_json(200, {'ok': True})
                elif path == '/api/ovrk/eis':
                    ovrk_mark_eis(data.get('id', ''), data.get('upd', ''), data.get('pp') or '', to_iso(data.get('date')) or date.today().isoformat(), user)
                    self.send_json(200, {'ok': True})
                elif path == '/api/ovrk/new/parse':
                    if data.get('pull'):
                        res = ovrk_new_parse(ovrk_from_registry(ОВРК_НОВЫЕ_ДНЕЙ), f'реестр ОАО (заключены за {ОВРК_НОВЫЕ_ДНЕЙ} дн.)')
                    else:
                        res = ovrk_new_parse(ovrk_import_oao(base64.b64decode(data.get('b64', ''))), data.get('filename', ''))
                    self.send_json(200, dict(res, ok=True))
                elif path == '/api/ovrk/new/apply':
                    a, b2 = ovrk_new_apply(data.get('items') or [], user)
                    log('edit', f'ОВРК: из таблиц ОАО за неделю — новых договоров {a}, ДС {b2}', user=user.get('fio') or 'панель')
                    self.send_json(200, {'ok': True, 'n': a + b2, 'new': a, 'ds': b2})
                elif path == '/api/ovrk/pay/parse':
                    items, cands = ovrk_pay_parse(base64.b64decode(data.get('b64', '')), data.get('filename', ''))
                    self.send_json(200, {'ok': True, 'items': items, 'cands': cands})
                elif path == '/api/ovrk/pay/apply':
                    n = ovrk_pay_apply(data.get('items') or [], user)
                    log('edit', f'ОВРК: из перечня бухгалтерии разнесено платёжек {n}', user=user.get('fio') or 'панель')
                    self.send_json(200, {'ok': True, 'n': n})
                elif path == '/api/ovrk/pull':
                    res = ovrk_merge(ovrk_from_registry(), user, 'реестр ОАО (конкурентные и неконкурентные)')
                    log('edit', f"ОВРК: из реестра ОАО добавлено договоров {res['added']}, уже были — {res['skipped']}", user=user.get('fio') or 'панель')
                    self.send_json(200, dict(res, ok=True))
                elif path == '/api/ovrk/import' and data.get('fmt') == 'oao':
                    rows = ovrk_import_oao(base64.b64decode(data.get('b64', '')))
                    if data.get('dry'):
                        self.send_json(200, {'ok': True, 'fmt': 'oao', 'contracts': len(rows), 'ds': sum(len(c.get('ds') or []) for c in rows)})
                    else:
                        res = ovrk_merge(rows, user, 'таблица ОАО (прямые договоры)')
                        log('edit', f"ОВРК: из таблицы ОАО добавлено договоров {res['added']}, уже были — {res['skipped']}, ДС {res['ds_added']}", user=user.get('fio') or 'панель')
                        self.send_json(200, dict(res, ok=True, contracts=res['added']))
                elif path == '/api/ovrk/import':
                    rows = ovrk_import_xlsx(base64.b64decode(data.get('b64', '')))
                    if data.get('dry'):
                        self.send_json(200, {'ok': True, 'contracts': len(rows), 'upds': sum(len(c['upds']) for c in rows),
                                             'pps': sum(len(u['pps']) for c in rows for u in c['upds'])})
                    else:
                        if data.get('mode') == 'replace':
                            with OVRK_LOCK:
                                d = ovrk_load()
                                d.setdefault('deleted', []).extend(d['rows'])
                                d['rows'] = []
                                ovrk_save_all(d)
                        res = ovrk_merge(rows, user, 'таблица ОВРК (Excel)')   # без дублей: такой договор уже есть — пропускаем
                        log('edit', f"ОВРК: загружено из таблицы договоров — {res['added']}, уже были — {res['skipped']}", user=user.get('fio') or 'панель')
                        self.send_json(200, dict(res, ok=True, contracts=res['added']))
                elif path == '/api/ovrk/xlsx':
                    d, idx, _ = ovrk_all()
                    rows = d['rows']
                    if data.get('ids'):
                        keep = set(data['ids'])
                        rows = [x for x in rows if x['id'] in keep]
                    self.send_file(ovrk_xlsx(rows), f'Реестр ОВРК — {date.today():%d.%m.%Y}.xlsx',
                                   'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet')
                else:
                    self.send_json(404, {'ok': False, 'message': 'Нет такой команды'})
            elif path.startswith('/api/smp'):
                if not oz_can(user):
                    self.send_json(403, {'ok': False, 'message': 'Проверка СМП — для сотрудников ОПАиЗ'})
                elif path == '/api/smp/check':
                    raw = base64.b64decode(data.get('b64', ''))
                    name = data.get('filename', '')
                    items = data.get('items') or spec_items(name, raw) or spec_items_kv(name, raw)
                    if not items:
                        raise ValueError('Не нашла в файле позиций с кодами ОКПД2 (таблица с «наименование» и «ОКПД»)')
                    low = name.lower()
                    kind = data.get('kind') or ('заявка' if low.endswith(('.xls', '.xlsx')) or 'заявк' in low else 'обоснование' if 'обосн' in low or getattr(spec_items_kv, 'last_kind', '') == 'обоснование' else 'счёт' if 'сч' in low[:6] else 'договор')
                    month = data.get('month') or ''
                    if not month and raw and kind == 'договор' and low.endswith(('.docx', '.doc', '.pdf')):
                        c = parse_contract(any_text(raw, name))
                        month = to_iso(c.get('date')) if c.get('date') else ''
                    out = smp_check(items, kind, month or date.today().isoformat(), data.get('clause') or None)
                    out.update({'ok': True, 'kind': kind, 'items': items, 'file': name, 'month_iso': (month or date.today().isoformat())[:10],
                                'text': smp_summary_text(out['summary'])})
                    self.send_json(200, out)
                elif path == '/api/smp/report':
                    fname = re.sub(r'[^\w .-]+', '', data.get('file') or 'документ')[:60]
                    self.send_file(smp_report_docx(data), f"Отчёт СМП — {fname} — {datetime.now():%Y-%m-%d_%H-%M}.docx",
                                   'application/vnd.openxmlformats-officedocument.wordprocessingml.document')
                elif path == '/api/smp/ref':
                    name = smp_save_ref(data.get('kind', ''), data.get('filename', ''), base64.b64decode(data.get('b64', '')))
                    log('edit', f'Проверка СМП: обновлён справочник «{name}»', user=user.get('fio') or 'панель')
                    self.send_json(200, {'ok': True, 'refs': smp_refs_info()})
                elif path == '/api/smp/save':
                    t, rid = data.get('table', ''), data.get('id', '')
                    vals = {'smpchk': data.get('text', '')}
                    if data.get('items'):
                        vals['items'] = data['items']
                    row, _ = oz_save_row(t, rid or None, vals, None, user, system=True, note='проверка СМП')
                    self.send_json(200, {'ok': True, 'row': row})
                else:
                    self.send_json(404, {'ok': False, 'message': 'Нет такой команды'})
            elif path.startswith('/api/oz'):
                if not oz_can(user):
                    self.send_json(403, {'ok': False, 'message': 'Реестр ОПАиЗ ведут сотрудники ОПАиЗ'})
                elif path == '/api/oz':
                    refresh_cache()
                    oz_sync()
                    ctx = {'ds_nums': {nkey(r.get('cnum')) for r in oz_load('ds')['rows'] if r.get('cnum')}, 'ovrk': ovrk_exec_index()}
                    self.send_json(200, {'ok': True, 'tables': OZ_TABLES, 'check_days': СЧЁТ_ПРОВЕРКА_РАБ_ДНЕЙ, 'ovrk_limit': ОВРК_ПОРОГ_ИСПОЛНЕНИЯ, 'boss': ОПАиЗ_НАЧАЛЬНИК, 'statuses': OZ_STATUSES, 'lists': oz_lists(),
                                         'list_titles': OZ_LIST_TITLES, 'staff': staff_opaiz(),
                                         'staff_oao': [r['fio'] for r in load_responsibles()],
                                         'rows': {t: [oz_calc(t, r, ctx) for r in oz_load(t)['rows']] for t in OZ_TABLES},
                                         'init_depts': oz_init_depts(), 'approval_days': ДОГОВОР_СОГЛАСОВАНИЕ_РАБ_ДНЕЙ, 'route_norm': МАРШРУТ_НОРМА_РАБ_ДНЕЙ,
                                         'workdays_extra': РАБОЧИЕ_ВЫХОДНЫЕ, 'contract_wait_days': ДОГОВОР_ЖДЁМ_ДНЕЙ,
                                         'smp_refs': smp_refs_info(),
                                         'holidays': [d.isoformat() if hasattr(d, 'isoformat') else d for d in ПРАЗДНИКИ]})
                elif path == '/api/oz/save':
                    row, ch = oz_save_row(data.get('table', ''), data.get('id') or None, data.get('values') or {},
                                          data.get('ver'), user, note=data.get('note', ''))
                    if not data.get('id'):
                        log('edit', f"ОПАиЗ, «{OZ_TABLES[data['table']]['title']}»: новая строка", user=user.get('fio') or 'панель')
                    oz_sync(force=True)
                    self.send_json(200, {'ok': True, 'row': next((r for r in oz_load(data['table'])['rows'] if r['id'] == row['id']), row),
                                         'changed': len(ch)})
                elif path == '/api/oz/delete':
                    oz_delete_row(data.get('table', ''), data.get('id', ''), user)
                    self.send_json(200, {'ok': True})
                elif path == '/api/oz/need':
                    items = need_items(data.get('filename', ''), base64.b64decode(data.get('b64', '')))
                    if not items:
                        raise ValueError('В файле не нашлись позиции: на листах нужна строка заголовков с «Наименование»')
                    self.send_json(200, {'ok': True, 'items': items})
                elif path == '/api/oz/spec':
                    items = spec_items(data.get('filename', ''), base64.b64decode(data.get('b64', '')))
                    if not items:
                        raise ValueError('В файле не нашлась таблица позиций (наименование, ОКПД2, количество)')
                    self.send_json(200, {'ok': True, 'items': items})
                elif path == '/api/oz/route/parse':
                    items = oz_route_import(base64.b64decode(data.get('b64', '')), data.get('filename', ''))
                    self.send_json(200, {'ok': True, 'items': items,
                                         'cands': {t: [{'id': r['id'], 'label': ozNo_py(t, r) + ' · ' + str(r.get('name') or r.get('subject') or '')[:70]} for r in oz_load(t)['rows']] for t in ('zayavki', 'ep')}})
                elif path == '/api/oz/route/apply':
                    n = 0
                    for it in data.get('items') or []:
                        if it.get('table') in ('zayavki', 'ep') and it.get('id') and it.get('values'):
                            vals = {k: v for k, v in it['values'].items() if k.startswith('rt_') and k != 'rt_where'}
                            _, ch = oz_save_row(it['table'], it['id'], vals, None, user, note='маршрут из таблицы ОАО — проверено в панели')
                            n += bool(ch)
                    log('edit', f'ОПАиЗ: маршрут согласования из таблицы ОАО — обновлено строк {n}', user=user.get('fio') or 'панель')
                    oz_sync(force=True)
                    self.send_json(200, {'ok': True, 'n': n})
                elif path == '/api/oz/parse':
                    self.send_json(200, oz_parse_doc(data.get('filename', ''), base64.b64decode(data.get('b64', ''))))
                elif path == '/api/oz/xlsx':
                    t = data.get('table', 'zayavki')
                    if t not in OZ_TABLES:
                        raise ValueError('Нет такой таблицы')
                    self.send_file(oz_xlsx(t, data.get('ids')), f"Реестр ОПАиЗ — {OZ_TABLES[t]['title']} — {date.today():%d.%m.%Y}.xlsx",
                                   'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet')
                elif path == '/api/oz/lists':
                    if isinstance(data.get('init_depts'), dict):
                        _oz_path('инициаторы').parent.mkdir(parents=True, exist_ok=True)
                        write_atomic(_oz_path('инициаторы'), json.dumps({str(k).strip(): str(v).strip() for k, v in data['init_depts'].items() if str(k).strip()}, ensure_ascii=False, indent=1))
                    self.send_json(200, {'ok': True, 'lists': oz_save_lists(data.get('lists') or {}, user), 'init_depts': oz_init_depts()})
                else:
                    self.send_json(404, {'ok': False, 'message': 'Нет такой команды'})
            elif path == '/api/dirs':
                self.send_json(200, {'ok': True, **dirs_payload()})
            elif path.startswith('/api/odata/'):
                self.send_json(200, odata_api(path, data, user))
            elif path.startswith('/api/src/'):
                self.send_json(200, src_api(path, data, user))
            elif path.startswith('/api/sync/'):
                self.send_json(200, sync_api(path, data, user))
            elif path.startswith('/api/docs/'):
                self.send_json(200, docs_api(path, data, user))
            elif path.startswith('/api/dmap/'):
                self.send_json(200, dmap_api(path, data, user))
            elif path == '/api/dirs/save':
                if not user.get('admin'):
                    self.send_json(403, {'ok': False, 'message': 'Справочники меняет администратор'})
                else:
                    self.send_json(200, {'ok': True, **save_directories(data, user)})
            elif path == '/api/suppliers':
                self.send_json(200, {'ok': True, 'items': suppliers()})
            elif path == '/api/suppliers/save':
                self.send_json(200, {'ok': True, 'item': save_supplier(data, user)})
            elif path == '/api/review':
                self.send_json(200, {'ok': True, 'items': review_list()})
            elif path == '/api/review/open':
                self.send_json(200, review_open(data.get('id', '')))
            elif path == '/api/review/close':
                review_close(data.get('id', ''), data.get('how', 'done'), user)
                self.send_json(200, {'ok': True})
            elif path == '/api/parse':
                if data.get('docx_b64'):
                    raw = base64.b64decode(data['docx_b64'])
                    text = docx_text(io.BytesIO(raw))
                    d = parse_text(text, data.get('filename', ''))
                    tok = keep_upload(data.get('filename') or 'извещение.docx', raw)
                    self.send_json(200, {'ok': True, 'token': tok, 'form': d_to_form(d), 'body': split_body(text),
                                         'noncompetitive': d['noncompetitive']})
                else:
                    text = data.get('text', '')
                    d = parse_text(text)
                    self.send_json(200, {'ok': True, 'form': d_to_form(d),
                                         'noncompetitive': d['noncompetitive']})
            elif path == '/api/submit':
                d = form_to_d(data.get('form', {}))
                d['upload_token'] = data.get('token') or ''
                code, answer = submit_from_panel(d, data.get('body', ''))
                self.send_json(code, answer)
            elif path == '/api/doc':
                self.send_json(200, handle_doc(data))
            elif path == '/api/preview':
                self.send_json(200, handle_preview(data))
            elif path == '/api/apply':
                code, answer = handle_apply(data)
                self.send_json(code, answer)
            elif path == '/api/protocol/docx':
                info = protocol_info(data.get('number', ''))
                p = _clean_protocol(data.get('protocol'))
                content = build_protocol_docx(data.get('kind'), info, p, data.get('present') or {}, data.get('executor', ''),
                                              data.get('extra_members') or [])
                self.send_file(content, f"Протокол {info['number']}-{p.get('seq')} {info['oao']}.docx",
                               'application/vnd.openxmlformats-officedocument.wordprocessingml.document')
            elif path == '/api/resp/fixes':
                ch, un = responsible_fixes()
                self.send_json(200, {'ok': True, 'changes': ch, 'unclear': un})
            elif path == '/api/resp/apply':
                try:
                    done = apply_responsible_fixes(data.get('items') or [], (data.get('author') or '').strip() or 'панель')
                    self.send_json(200, {'ok': True, 'done': len(done)})
                except RegistryBusy as e:
                    self.send_json(409, {'ok': False, 'message': str(e)})
            elif path == '/api/report/weeks':
                self.send_json(200, {'ok': True, 'weeks': weekly_list(), 'cutoff': ОТЧЁТ_ВРЕМЯ, 'auto': ОТЧЁТ_АВТО})
            elif path == '/api/report/week':
                self.send_json(200, {'ok': True, 'report': weekly_data(date.fromisoformat(data['day']))})
            elif path == '/api/report/week/xlsx':
                content, name = build_weekly_xlsx(date.fromisoformat(data['day']))
                self.send_file(content, name, 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet')
            elif path == '/api/report/week/ep':
                save_ep(date.fromisoformat(data['day']), data.get('ep') or {})
                self.send_json(200, {'ok': True})
            elif path == '/api/report/week/fix':
                day = date.fromisoformat(data['day'])
                who = (data.get('author') or '').strip() or 'панель'
                if data.get('undo'):
                    unfix_week(day, who)
                else:
                    fix_week(day, who)
                self.send_json(200, {'ok': True})
            elif path == '/api/report/buh':
                d = buh_data(date.fromisoformat(data['start']), date.fromisoformat(data['end']))
                self.send_json(200, {'ok': True, 'rows': d})
            elif path == '/api/report/buh/docx':
                content, name, _ = build_buh_docx(date.fromisoformat(data['start']), date.fromisoformat(data['end']),
                                                  data.get('manual') or {})
                self.send_file(content, name, 'application/vnd.openxmlformats-officedocument.wordprocessingml.document')
            elif path == '/api/analytics/xlsx':
                spec = data.get('spec') or {}
                self.send_file(build_analytics_xlsx(spec), (spec.get('file') or 'Аналитика') + '.xlsx',
                               'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet')
            elif path == '/api/short':
                fio, kind = data.get('fio', ''), data.get('kind', 'nk')
                self.send_json(200, {'ok': True, 'short': responsible_short(fio, kind)})
            elif path == '/api/docx':
                d = form_to_d(data.get('form', {}))
                self.send_file(build_docx(d, data.get('body', '')), docx_filename(d),
                               'application/vnd.openxmlformats-officedocument.wordprocessingml.document')
            else:
                self.send_json(404, {'ok': False, 'message': 'Нет такого действия'})
        except (BrokenPipeError, ConnectionResetError):
            pass
        except (ValueError, RegistryBusy) as e:
            self.send_json(400, {'ok': False, 'message': str(e)})
        except Exception as e:
            self.fail(e)

    def fail(self, e):
        log('error', f'Ошибка сервера: {type(e).__name__}: {e}')
        traceback.print_exc()
        try:
            if isinstance(e, PermissionError):
                self.send_json(403, {'ok': False, 'message': str(e)})
            elif isinstance(e, ValueError):
                # ValueError — осознанные сообщения для пользователя («Нет доступа…», «Файл не найден»)
                self.send_json(500, {'ok': False, 'message': str(e)})
            else:
                # внутренние детали (пути, стеки) клиенту не показываем
                self.send_json(500, {'ok': False, 'message': 'Внутренняя ошибка сервера. Подробности — в журнале панели.'})
        except OSError:
            pass


# ---------- новости УООЗД: «ОАО решили, что теперь делаем так» ----------
NEWS_LOCK = threading.Lock()


def news_load():
    return _json_file('Новости.json', {'seq': 0, 'items': []})


def news_save(data, actor):
    who = (actor or {}).get('fio') or 'панель'
    with NEWS_LOCK:
        d = news_load()
        title, text = str(data.get('title') or '').strip()[:200], str(data.get('text') or '').strip()[:4000]
        if not title:
            raise ValueError('Напишите заголовок новости')
        it = next((x for x in d['items'] if x['id'] == data.get('id')), None) if data.get('id') else None
        if it is None:
            d['seq'] = d.get('seq', 0) + 1
            it = {'id': f"n{d['seq']}", 'at': datetime.now().isoformat(timespec='seconds'), 'by': who}
            d['items'].append(it)
        elif it.get('by') != who and not (actor or {}).get('admin') and ВХОД_ПО_ПАРОЛЮ:
            raise ValueError('Изменить новость может автор или администратор')
        it.update(title=title, text=text, dept=str(data.get('dept') or 'УООЗД')[:20], important=bool(data.get('important')),
                  since=to_iso(data.get('since')) or '', edited=datetime.now().isoformat(timespec='seconds') if it.get('title') else '')
        write_atomic(ПАПКА_ПАНЕЛИ / 'Новости.json', json.dumps(d, ensure_ascii=False, indent=1))
    log('info', f"Новость: {title}", user=who)
    return it


def news_delete(nid, actor):
    with NEWS_LOCK:
        d = news_load()
        it = next((x for x in d['items'] if x['id'] == nid), None)
        if not it:
            return
        if it.get('by') != (actor or {}).get('fio') and not (actor or {}).get('admin') and ВХОД_ПО_ПАРОЛЮ:
            raise ValueError('Удалить новость может автор или администратор')
        d['items'] = [x for x in d['items'] if x['id'] != nid]
        write_atomic(ПАПКА_ПАНЕЛИ / 'Новости.json', json.dumps(d, ensure_ascii=False, indent=1))


# ---------- уведомления ----------
NOTIFY_LOCK = threading.Lock()


def _notify_path():
    return ПАПКА_ПАНЕЛИ / 'Уведомления.json'


def notify_load():
    return _json_file('Уведомления.json', {'items': [], 'pub_seen': []})


def _fmt_money(v):
    return f'{v:,.2f}'.replace(',', ' ').replace('.', ',') + ' ₽' if isinstance(v, (int, float)) else str(v or '—')


def _ru(d):
    return iso_to_ru(d)[:5] if d else ''


def notify_text(kind, d):
    """Тексты разные по виду события: значок и первое слово видно даже в списке чатов."""
    oao, subj = d.get('oao') or d.get('number') or '', (d.get('name') or '').strip()
    subj = re.sub(r'\s+для нужд ФГАОУ ВО.*$', '', subj)[:160]
    if kind == 'notice':
        dates = ' · '.join(x for x in (f"Вскрытие {_ru(d.get('bid'))}" if d.get('bid') else '', f"Итоги {_ru(d.get('result'))}" if d.get('result') else '') if x)
        return (f"🟡 ИЗВЕЩЕНИЕ → на публикацию · {oao}\n{subj}\n━━━━━━━━━━\n💰 НМЦК: {_fmt_money(d.get('price') or d.get('nmck'))}"
                f"{' · ' + d['subordination'] if d.get('subordination') else ''}\n👤 {d.get('responsible') or '—'}" + (f"\n🗓 {dates}" if dates else '') + "\n👉 Опубликовать на площадке")
    if kind == 'pub':
        pg = ' · '.join(x for x in (d.get('plan_month') and f"план-график: {d.get('plan_month')}", d.get('plan_no') and f"№ {d.get('plan_no')}") if x)
        return (f"🟢 ОПУБЛИКОВАНО · {oao} · {iso_to_ru(d.get('pub')) if d.get('pub') else ''}\n{subj}\n━━━━━━━━━━\n💰 {_fmt_money(d.get('nmck'))}" + (f" · {pg}" if pg else '') +
                f"\n👤 {d.get('responsible') or '—'}\n✅ Заявки принимаются" + (f" до {_ru(d.get('bid'))}" if d.get('bid') else ''))
    if kind == 'buh':
        return f"Извещение {oao}: {subj}. НМЦК {_fmt_money(d.get('price') or d.get('nmck'))}. Ответственный: {d.get('responsible') or '—'}. Файл извещения — во вложении."
    return subj


def _send_max(text):
    import urllib.request
    req = urllib.request.Request(f'{МАКС_API}?chat_id={quote(str(МАКС_ЧАТ))}', data=json.dumps({'text': text}).encode('utf-8'),
                                 headers={'Authorization': МАКС_ТОКЕН, 'Content-Type': 'application/json'}, method='POST')
    urllib.request.urlopen(req, timeout=15).read()


def _send_mail(to, subject, text, attach=None):
    import smtplib
    from email.message import EmailMessage
    m = EmailMessage()
    m['From'], m['To'], m['Subject'] = ПОЧТА_ОТ, to, subject
    m.set_content(text)
    if attach:
        m.add_attachment(attach[1], maintype='application', subtype='octet-stream', filename=attach[0])
    host, _, port = ПОЧТА_SMTP.partition(':')
    with smtplib.SMTP(host, int(port or 587), timeout=20) as srv:
        srv.starttls()
        if ПОЧТА_ЛОГИН:
            srv.login(ПОЧТА_ЛОГИН, ПОЧТА_ПАРОЛЬ)
        srv.send_message(m)


def notify(kind, d, attach=None, when=None):
    """Записать уведомление в журнал и (если включено) отправить. kind: notice | pub."""
    out = []
    if kind == 'notice':
        out.append(('Макс', 'чат отдела', 'notice', notify_text('notice', d)))
        if d.get('email'):
            out.append(('Почта бухгалтерии', d['email'], 'buh', notify_text('buh', d)))
    elif kind == 'pub':
        out.append(('Макс', 'чат отдела', 'pub', notify_text('pub', d)))
    items = []
    for ch, to, k, text in out:
        st, err = 'в журнале — отправка выключена в настройках', ''
        try:
            if УВЕДОМЛЕНИЯ_ДЕМО:
                st = 'отправлено (демо)'
            elif ch == 'Макс' and УВЕДОМЛЕНИЯ_МАКС and МАКС_ТОКЕН and МАКС_ЧАТ:
                _send_max(text)
                st = 'отправлено'
            elif ch == 'Почта бухгалтерии' and УВЕДОМЛЕНИЯ_ПОЧТА and ПОЧТА_SMTP:
                _send_mail(to, f"Извещение {d.get('oao') or d.get('number')}", text, attach)
                st = 'отправлено'
        except Exception as e:
            st, err = 'ошибка отправки', str(e)[:200]
        items.append({'ts': (when or datetime.now()).isoformat(timespec='seconds'), 'kind': k, 'channel': ch, 'to': to, 'text': text,
                      'status': st, 'error': err, 'oao': d.get('oao') or '', 'number': d.get('number') or '',
                      'file': attach[0] if attach else ''})
    with NOTIFY_LOCK:
        data = notify_load()
        data['items'] = (data.get('items') or [])[-1500:] + items
        write_atomic(_notify_path(), json.dumps(data, ensure_ascii=False, indent=1))
    return items


def check_publications():
    """Новая публикация: в реестре появилась дата публикации за последние 2 дня — одно уведомление на закупку."""
    rows = cache.get('rows') or []
    lim = (date.today() - timedelta(days=2)).isoformat()
    fresh = [r for r in rows if r.get('pub') and r['pub'] >= lim and r.get('number')]
    if not fresh:
        return
    with NOTIFY_LOCK:
        seen = set(notify_load().get('pub_seen') or [])
    new = [r for r in fresh if r['number'] not in seen]
    for r in new:
        notify('pub', {'oao': r.get('oao'), 'number': r.get('number'), 'name': r.get('name'), 'nmck': r.get('nmck'), 'pub': r.get('pub'),
                       'bid': r.get('bid'), 'responsible': r.get('responsible'), 'plan_month': r.get('plan_month') or '', 'plan_no': r.get('plan_no') or ''})
    if new:
        with NOTIFY_LOCK:
            data = notify_load()
            data['pub_seen'] = sorted(set(data.get('pub_seen') or []) | {r['number'] for r in new})[-5000:]
            write_atomic(_notify_path(), json.dumps(data, ensure_ascii=False, indent=1))


def watch_folder():
    while True:
        try:
            process_incoming()
            process_pending()
            process_protocols()
            refresh_cache()
            auto_weekly()
            check_publications()
        except Exception as e:
            log('error', f'Сбой обработки «Входящих»: {type(e).__name__}: {e}')
        time.sleep(ИНТЕРВАЛ)


def main():
    for stream in (sys.stdout, sys.stderr):
        try:
            stream.reconfigure(encoding='utf-8', errors='replace')
        except (AttributeError, ValueError):
            pass
    ПАПКА_ПАНЕЛИ.mkdir(parents=True, exist_ok=True)
    for Y in years():
        if not Y.intake:
            continue
        for d in [d for _, d in Y.intake_dirs()] + [Y.protocols_in()]:
            d.mkdir(parents=True, exist_ok=True)
            (d.parent / 'отработанные').mkdir(parents=True, exist_ok=True)
        if not Y.registry.exists():
            create_registry(Y.registry, Y.y)
            log('info', f'Создан реестр {Y.y}: {Y.registry}')
    first_admin = ensure_first_admin() if ВХОД_ПО_ПАРОЛЮ else None

    try:
        server = ThreadingHTTPServer(('0.0.0.0', ПОРТ), Handler)
    except OSError as e:
        print(f'Не удалось занять порт {ПОРТ}: {e}')
        print('Скорее всего, панель уже запущена. Или поменяйте ПОРТ в настройках.')
        return
    server.daemon_threads = True

    try:
        ip = socket.gethostbyname(HOST)
    except OSError:
        ip = '127.0.0.1'
    print('=' * 64)
    print('  ПАНЕЛЬ УООЗД — реестры закупок')
    print('=' * 64)
    for Y in years():
        print(f'  {Y.y}: {Y.registry}' + ('' if Y.intake else '   (только чтение)'))
        if Y.intake:
            print(f'        извещения: {Y.notices_in("k").parent.parent}   протоколы: {Y.protocols_in().parent}')
    print(f'  Панель:     http://{HOST}:{ПОРТ}   или   http://{ip}:{ПОРТ}')
    print('=' * 64)
    if first_admin:
        print(f'  ВХОД АДМИНИСТРАТОРА: логин {first_admin[0]}, пароль {first_admin[1]}')
        print('  (панель попросит сменить пароль после первого входа)')
        print('=' * 64)
    print('Работает. Остановить — Ctrl+C (в PyCharm — красный квадрат).\n')

    log('info', f'Панель запущена на {HOST}:{ПОРТ}')
    try:
        src_migrate_once()          # старые подключения OData/COM → единые «Источники 1С»
    except Exception as e:
        log('error', f'Миграция источников 1С не выполнена: {type(e).__name__}: {e}')
    threading.Thread(target=watch_folder, daemon=True).start()
    threading.Thread(target=watch_sync, daemon=True).start()   # планировщик авто-синхронизации 1С
    if ОТКРЫТЬ_ПАНЕЛЬ:
        def _open_browser():
            try:
                webbrowser.open(f'http://localhost:{ПОРТ}')
            except Exception:      # headless-сервер без браузера (в т.ч. Linux) — не критично
                pass
        threading.Timer(1.0, _open_browser).start()
    try:
        server.serve_forever()
    except KeyboardInterrupt:
        pass
    finally:
        log('info', 'Панель остановлена')
        print('\nОстановлено.')


